async function loadCompanies() {
  const { data } = await sb.from('companies').select('*').order('zone').order('zone_number');
  allCompanies = data || [];
  activeCompanies = allCompanies.filter(c => c.is_active !== false && /^(SVKSEZ-|SSEZ@)/i.test(c.username || ''));
}

// ============================================================
// ສ້າງລະຫັດຜ່ານແບບສຸ່ມອັດຕະໂນມັດ: SVKSEZ@ + ຕົວອັກສອນນ້ອຍ2ໂຕ + ເລກ1ໂຕ + ຕົວອັກສອນໃຫຍ່1ໂຕ (ສະຫຼັບຕຳແໜ່ງ)
// ============================================================
// ============================================================
// ບັງຄັບໃຫ້ຄໍລຳວັນທີໃນ Excel Template ເປັນ "ຂໍ້ຄວາມ (Text)" ສະເໝີ
// ເພື່ອປ້ອງກັນ Excel ປ່ຽນຮູບແບບວັນທີເປັນແບບອື່ນ (ເຊັ່ນ MM/DD/YYYY ຕາມພາສາເຄື່ອງ) ໂດຍບໍ່ຮູ້ໂຕ
// ໃຫ້ຄົງຮູບແບບ ວັນທີ/ເດືອນ/ປີ (DD/MM/YYYY) ຕະຫຼອດ
// ============================================================
function forceExcelTextColumns(ws, colIndices, totalRows) {
  for (let r = 0; r <= totalRows; r++) {
    colIndices.forEach(c => {
      const addr = XLSX.utils.encode_cell({ r, c });
      if (ws[addr]) { ws[addr].t = 's'; ws[addr].z = '@'; }
    });
  }
}

// ============================================================
// AUTO-RETRY: ລອງໃໝ່ອັດຕະໂນມັດຖ້າ Supabase ຊ້າ/ບໍ່ຕອບຊົ່ວຄາວ (ເຊັ່ນ ຄົນໃຊ້ພ້ອມກັນຫຼາຍ)
// ໃຊ້ກັບ Excel bulk upload ທຸກຟັງຊັນ ເພື່ອຫຼຸດຄວາມສ່ຽງ error ຊົ່ວຄາວ
// ============================================================
async function supabaseRetry(queryFn, maxRetries = 3, delayMs = 1500) {
  let result;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      result = await queryFn();
    } catch (e) {
      result = { data: null, error: e };
    }
    if (!result || !result.error) return result;
    const msg = String(result.error.message || result.error || '').toLowerCase();
    const status = result.error.status || result.error.code;
    const isTransient = msg.includes('fetch') || msg.includes('network') || msg.includes('timeout') ||
      msg.includes('rate') || msg.includes('too many') || msg.includes('unavailable') ||
      status === 429 || status === '429' || (typeof status === 'number' && status >= 500);
    if (!isTransient || attempt === maxRetries) return result;
    await new Promise(r => setTimeout(r, delayMs * attempt));
  }
  return result;
}

// ============================================================
// ຄວາມປອດໄພ: ກັ່ນຕອງຂໍ້ຄວາມທີ່ຜູ້ໃຊ້ພິມເອງ ກ່ອນສະແດງເປັນ HTML (ປ້ອງກັນ XSS)
// ໃຊ້ກັບຊື່ພະນັກງານ, ຊື່ບໍລິສັດ, ຕຳແໜ່ງ, ໝາຍເຫດ ຫຼືຂໍ້ຄວາມອື່ນທີ່ຜູ້ໃຊ້ພິມເອງ ທຸກຄັ້ງກ່ອນໃສ່ໃນ innerHTML
// ============================================================
function esc(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// ໃຊ້ສະເພາະຄ່າທີ່ຝັງຢູ່ໃນ onclick="fn('...')" — ຕ້ອງ escape ທັງ JS string quote ແລະ HTML attribute
function escAttr(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function generateRandomPassword() {
  const lowers = 'abcdefghijklmnopqrstuvwxyz';
  const uppers = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const digits = '0123456789';
  const pick = s => s[Math.floor(Math.random() * s.length)];
  const chars = [pick(lowers), pick(lowers), pick(digits), pick(uppers)];
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  const randomBlock = chars.join('');
  return Math.random() < 0.5 ? randomBlock + 'SVKSEZ@' : 'SVKSEZ@' + randomBlock;
}

