// NOTIFICATIONS
// ============================================================
async function checkNotifications() {
  notifications = [];
  const today = new Date();

  if (currentUser.role === 'admin' || currentUser.role === 'director') {
    activeCompanies.forEach(c => {
      if (c.rule_date) {
        const exp = new Date(c.rule_date);
        exp.setFullYear(exp.getFullYear() + 2);
        if (exp <= today) notifications.push({ 
          type: 'danger', 
          msg: `🏭 [${esc(c.username)}] ໃບອະນຸຍາດນຳໃຊ້ກົດລະບຽບ ໝົດອາຍຸແລ້ວ`,
          companyId: c.id,
          page: 'companies'
        });
      }
      // Health doc expires in 1yr, warn 1 month before
      if (c.health_date) {
        const exp = new Date(c.health_date);
        exp.setFullYear(exp.getFullYear() + 1);
        const warn = new Date(exp);
        warn.setMonth(warn.getMonth() - 1);
        if (exp <= today) notifications.push({ 
          type: 'danger', 
          msg: `🏥 [${esc(c.username)}] ໃບຢັ້ງຢືນກວດສຸຂະພາບ ໝົດອາຍຸແລ້ວ`,
          companyId: c.id,
          page: 'companies'
        });
        else if (warn <= today) notifications.push({ 
          type: 'warning', 
          msg: `⚠️ [${esc(c.username)}] ໃບຢັ້ງຢືນກວດສຸຂະພາບ ຈະໝົດອາຍຸໃນ 1 ເດືອນ`,
          companyId: c.id,
          page: 'companies'
        });
      }
    });
  } else if (currentUser.role === 'company' && currentUser.companyData) {
    // Companies only ever see their OWN document status — never other companies' data
    const c = currentUser.companyData;
    if (c.rule_date) {
      const exp = new Date(c.rule_date);
      exp.setFullYear(exp.getFullYear() + 2);
      if (exp <= today) notifications.push({ type: 'danger', msg: `🏭 ໃບອະນຸຍາດນຳໃຊ້ກົດລະບຽບ ໝົດອາຍຸແລ້ວ`, companyId: c.id, page: 'myCompany' });
    }
    if (c.health_date) {
      const exp = new Date(c.health_date);
      exp.setFullYear(exp.getFullYear() + 1);
      const warn = new Date(exp);
      warn.setMonth(warn.getMonth() - 1);
      if (exp <= today) notifications.push({ type: 'danger', msg: `🏥 ໃບຢັ້ງຢືນກວດສຸຂະພາບ ໝົດອາຍຸແລ້ວ`, companyId: c.id, page: 'myCompany' });
      else if (warn <= today) notifications.push({ type: 'warning', msg: `⚠️ ໃບຢັ້ງຢືນກວດສຸຂະພາບ ຈະໝົດອາຍຸໃນ 1 ເດືອນ`, companyId: c.id, page: 'myCompany' });
    }
  }

  // Labour card 15 days (Section C foreign worker registry)
  if (currentUser.role === 'admin' || currentUser.role === 'director') {
    const { data: workers } = await sb.from('foreign_workers').select('*, companies(id,username)');
    if (workers) {
      workers.forEach(w => {
        if (w.labour_card_expiry) {
          const exp = new Date(w.labour_card_expiry);
          const warn = new Date(exp);
          warn.setDate(warn.getDate() - 15);
          if (warn <= today && exp > today) {
            notifications.push({ 
              type: 'warning', 
              msg: `🪪 ບັດແຮງງານ ${esc(w.firstname)} ${esc(w.lastname)} (${esc(w.companies?.username)}) ຈະໝົດອາຍຸໃນ 15 ວັນ`,
              companyId: w.companies?.id,
              page: 'fnNew'
            });
          } else if (exp <= today) {
            notifications.push({ 
              type: 'danger', 
              msg: `🪪 ບັດແຮງງານ ${esc(w.firstname)} ${esc(w.lastname)} (${esc(w.companies?.username)}) ໝົດອາຍຸແລ້ວ`,
              companyId: w.companies?.id,
              page: 'fnNew'
            });
          }
        }
      });
    }
  }

  // ---- Company-side: warn about expiring documents for own workers ----
  if (currentUser.role === 'company') {
    const { data: myWorkers } = await sb.from('foreign_workers')
      .select('id,firstname,lastname,passport_expiry,labour_card_expiry,residence_card_expiry,visa_expiry')
      .eq('company_id', currentUser.companyId);
    if (myWorkers) {
      const seen = new Set(JSON.parse(sessionStorage.getItem('seenDocExpiry') || '[]'));
      myWorkers.forEach(w => {
        const name = `${esc(w.firstname||'')} ${esc(w.lastname||'')}`.trim();

        // Passport: warn 6 months before expiry
        if (w.passport_expiry) {
          const exp = new Date(w.passport_expiry);
          const warn180 = new Date(today); warn180.setDate(warn180.getDate() + 180);
          const key = `pp_${w.id}`;
          if (exp <= warn180 && exp > today && !seen.has(key)) {
            notifications.push({ type: 'warning', key,
              msg: `🛂 ໜັງສືເດີນທາງ ຂອງພະນັກງານ ${name} ແມ່ນຈະໝົດອາຍຸໃນອີກ 6 ເດືອນຂ້າງໜ້າແລ້ວ ກະລຸນາແຈ້ງໃຫ້ຜູ້ກ່ຽວຊາບດ້ວຍ`,
              page: 'fwRequestCompany' });
          } else if (exp <= today && !seen.has(key+'_exp')) {
            notifications.push({ type: 'danger', key: key+'_exp',
              msg: `🛂 ໜັງສືເດີນທາງ ຂອງພະນັກງານ ${name} ໝົດອາຍຸແລ້ວ`,
              page: 'fwRequestCompany' });
          }
        }

        // Labour card, Residence card, Visa: warn 21 calendar days (~15 working days)
        [
          ['labour_card_expiry', '🪪 ບັດແຮງງານ', 'lc'],
          ['residence_card_expiry', '🏠 ບັດພັກເຊົາ', 'rc'],
          ['visa_expiry', '🛂 ວີຊ່າ', 'vi']
        ].forEach(([field, label, pfx]) => {
          if (!w[field]) return;
          const exp = new Date(w[field]);
          const warn21 = new Date(today); warn21.setDate(warn21.getDate() + 21);
          const key = `${pfx}_${w.id}`;
          if (exp <= warn21 && exp > today && !seen.has(key)) {
            notifications.push({ type: 'warning', key,
              msg: `${label} ຂອງພະນັກງານ ${name} ຈະໝົດອາຍຸການໃຊ້ງານແລ້ວ ກະລຸນາຂຶ້ນທະບຽນຂໍຕໍ່ເອກະສານດ້ວຍ`,
              page: 'fwRequestCompany' });
          } else if (exp <= today && !seen.has(key+'_exp')) {
            notifications.push({ type: 'danger', key: key+'_exp',
              msg: `${label} ຂອງພະນັກງານ ${name} ໝົດອາຍຸແລ້ວ`,
              page: 'fwRequestCompany' });
          }
        });
      });
    }
  }
  if (currentUser.role === 'admin' || currentUser.role === 'director') {
    const { data: reqsRaw } = await sb.from('fw_requests').select('id,company_id,request_type,created_at').eq('status', 'submitted');
    const reqs = await attachCompanyInfo(reqsRaw);
    const seenAt = parseInt(sessionStorage.getItem('seenFwReqAt') || '0');
    (reqs || []).forEach(r => {
      if (new Date(r.created_at).getTime() > seenAt) {
        notifications.push({
          type: 'warning',
          msg: `📥 [${esc(r.companies?.username)}] ສົ່ງຄຳຂໍ${r.request_type === 'new' ? 'ລົງທະບຽນແຮງງານ ຕປທ ໃໝ່' : 'ຕໍ່ອາຍຸເອກະສານແຮງງານ ຕປທ'}`,
          companyId: r.company_id,
          page: 'fwRequestsAdmin'
        });
      }
    });
  }

  // ---- Company-side: ແຈ້ງເຕືອນເມື່ອແອັດມິນກວດເອກະສານຄຳຮ້ອງ (ໃບໂຄຕ້າ/ໃບອາກອນ/ລາຍຊື່ພະນັກງານ) ຄົບຖ້ວນແລ້ວ ----
  if (currentUser.role === 'company') {
    const { data: reviewedReqs } = await sb.from('fw_requests').select('id,request_type,reviewed_at').eq('company_id', currentUser.companyId).eq('status', 'reviewed');
    if (reviewedReqs) {
      const seenReviewed = new Set(JSON.parse(sessionStorage.getItem('seenDocExpiry') || '[]')); // ໃຊ້ storage ດຽວກັນກັບປຸ່ມ "ຮັບຊາບ" ທົ່ວໄປ
      reviewedReqs.forEach(r => {
        const key = `fwrev_${r.id}`;
        if (!seenReviewed.has(key)) {
          notifications.push({
            type: 'success',
            key,
            msg: `✅ ຄຳຂໍ${r.request_type === 'new' ? 'ລົງທະບຽນແຮງງານ ຕປທ ໃໝ່' : 'ຕໍ່ອາຍຸເອກະສານແຮງງານ ຕປທ'} ຂອງທ່ານ ຖືກແອັດມິນກວດເອກະສານຄົບຖ້ວນແລ້ວ — ⏳ ລໍຖ້າອະນຸມັດຂັ້ນສຸດທ້າຍ`,
            page: 'myFwRequests'
          });
        }
      });
    }
    // ແຈ້ງເຕືອນເມື່ອອະນຸມັດຂັ້ນສຸດທ້າຍ ຫຼື ຖືກປະຕິເສດ
    const { data: finalReqs } = await sb.from('fw_requests').select('id,request_type,final_approved,rejected,rejected_reason').eq('company_id', currentUser.companyId).or('final_approved.eq.true,rejected.eq.true');
    if (finalReqs) {
      const seenFinal = new Set(JSON.parse(sessionStorage.getItem('seenDocExpiry') || '[]'));
      finalReqs.forEach(r => {
        const label = r.request_type === 'new' ? 'ລົງທະບຽນແຮງງານ ຕປທ ໃໝ່' : 'ຕໍ່ອາຍຸເອກະສານແຮງງານ ຕປທ';
        if (r.final_approved) {
          const key = `fwfin_${r.id}`;
          if (!seenFinal.has(key)) notifications.push({ type: 'success', key, msg: `🏁 ຄຳຂໍ${label} ຂອງທ່ານ ໄດ້ຮັບການອະນຸມັດຂັ້ນສຸດທ້າຍແລ້ວ`, page: 'myFwRequests' });
        } else if (r.rejected) {
          const key = `fwrej_${r.id}`;
          if (!seenFinal.has(key)) notifications.push({ type: 'danger', key, msg: `❌ ຄຳຂໍ${label} ຂອງທ່ານ ຖືກປະຕິເສດ${r.rejected_reason ? ' — ' + esc(r.rejected_reason) : ''}`, page: 'myFwRequests' });
        }
      });
    }
  }

  const badge = document.getElementById('notifCount');
  if (notifications.length > 0) {
    badge.style.display = 'inline-flex';
    badge.textContent = notifications.length;
  } else {
    badge.style.display = 'none';
  }
}

function dismissDocExpiry(key) {
  const seen = new Set(JSON.parse(sessionStorage.getItem('seenDocExpiry') || '[]'));
  seen.add(key);
  sessionStorage.setItem('seenDocExpiry', JSON.stringify([...seen]));
  checkNotifications();
}

// Navigate to company from notification click
function goToCompanyFromNotif(companyId, page) {
  if (currentUser.role !== 'admin') { loadPage(page || 'myCompany'); return; }
  if(!companyId) { loadPage(page || 'companies'); return; }
  if(page === 'fnNew' || page === 'fwRequestsAdmin') { loadPage(page); return; }
  // Go to companies page and highlight the company
  loadPage('companies');
  setTimeout(async () => {
    await loadCompanyTable();
    // Find and scroll to the company row
    const c = allCompanies.find(x => x.id === companyId);
    if(c) {
      // Open search with company
      if(page === 'searchCompany') {
        loadPage('searchCompany');
        setTimeout(() => selectCompany(companyId), 300);
      } else {
        // Highlight in table
        const rows = document.querySelectorAll('#companyTableBody tr');
        rows.forEach(row => {
          if(row.textContent.includes(c.username)) {
            row.style.background = '#fff3cd';
            row.style.transition = 'background 1s';
            row.scrollIntoView({ behavior:'smooth', block:'center' });
            setTimeout(() => row.style.background = '', 3000);
          }
        });
      }
    }
  }, 200);
}

function showNotifications() {
  const list = document.getElementById('notifList');
  if (notifications.length === 0) {
    list.innerHTML = '<p style="text-align:center;color:#27ae60;">✅ ບໍ່ມີການແຈ້ງເຕືອນ</p>';
  } else {
    list.innerHTML = notifications.map(n => `
      <div class="alert alert-${n.type}" style="margin-bottom:8px;position:relative;">
        <div style="font-size:13px;cursor:pointer;padding-right:${n.key ? '60px' : '0'}"
             onclick="closeModal('notifModal');goToCompanyFromNotif('${n.companyId||''}','${n.page||'companies'}')">${n.msg}</div>
        ${n.companyId ? `<div style="font-size:11px;margin-top:3px;color:#2980b9;cursor:pointer;"
             onclick="closeModal('notifModal');goToCompanyFromNotif('${n.companyId||''}','${n.page||'companies'}')">🔍 ກົດເພື່ອໄປ →</div>` : ''}
        ${n.key ? `<button onclick="dismissDocExpiry('${n.key}')" 
             style="position:absolute;top:6px;right:8px;background:rgba(0,0,0,.12);border:none;border-radius:6px;padding:2px 8px;cursor:pointer;font-size:11px;">ຮັບຊາບ</button>` : ''}
      </div>`).join('');
  }
  document.getElementById('notifModal').classList.add('show');
}

// ============================================================
// PAGE LOADER
// ============================================================
function loadPage(page, pushState=true) {
  document.querySelectorAll('.sidebar-menu a').forEach(a => a.classList.remove('active'));
  const active = document.querySelector(`.sidebar-menu a[onclick="loadPage('${page}')"]`);
  if (active) active.classList.add('active');

  const content = document.getElementById('mainContent');
  switch(page) {
    case 'dashboard': content.innerHTML = pageDashboard(); break;
    case 'companies': content.innerHTML = pageCompanies(); loadCompanyTable(); break;
    case 'manageUsers': content.innerHTML = pageManageUsers(); loadManageUsers(); break;
    case 'summary51': content.innerHTML = pageSummary51(); loadSummary51(); break;
    case 'summary52': content.innerHTML = pageSummary52(); loadSummary52(); break;
    case 'monthlyReport': content.innerHTML = pageMonthly(); loadMonthly(); break;
    case 'printReport': content.innerHTML = pagePrint(); break;
    case 'searchCompany': content.innerHTML = pageSearch(); break;
    case 'myCompany': content.innerHTML = pageMyCompany(); loadMyCompany(); break;
    case 'myRecord': content.innerHTML = pageMyCompany(); loadMyCompany(); break;
    case 'myHistory': content.innerHTML = pageMyHistory(); loadMyHistory(); break;
    case 'myEmployees': 
      content.innerHTML = pageBaseline(); 
      loadBaseline(); 
      break;
    case 'empMovement': content.innerHTML = pageBaselineAdmin(); loadBaselineAdmin(); break;
    case 'fnNew': content.innerHTML = pageFnNew(); loadFnNew(); break;
    case 'fnRenew': content.innerHTML = pageFnRenew(); loadFnRenewSearch(); break;
    case 'fwNewWorkers':   content.innerHTML = pageFwNewWorkers();  loadFwNewWorkers();  break;
    case 'fwRenewDocs':    content.innerHTML = pageFwRenewDocs();   loadFwRenewDocs();   break;
    case 'fwRequestCompany': loadPage('fwNewWorkers', pushState); return; // redirect legacy
    case 'myFwRequests': content.innerHTML = pageMyFwRequests(); loadMyFwRequests(); break;
    case 'myFwSummary': content.innerHTML = pageMyFwSummary(); loadMyFwSummary(); break;
    case 'laoWorkers': content.innerHTML = pageLaoWorkers(); loadLaoWorkers(); break;
    case 'fwRequestsAdmin': content.innerHTML = pageFwRequestsAdmin(); loadFwRequestsAdmin(); sessionStorage.setItem('seenFwReqAt', Date.now()); setTimeout(checkNotifications, 500); break;
    case 'laoWorkersAdmin': content.innerHTML = pageLaoWorkersAdmin(); loadLaoWorkersAdmin(); break;
    case 'resignationsAdmin': content.innerHTML = pageResignationsAdmin(); loadResignationsAdmin(); break;
    case 'resignationsCompany': content.innerHTML = pageResignationsCompany(); loadResignationsCompany(); break;
    case 'auditLog': content.innerHTML = pageAuditLog(); loadAuditLog(); dismissAuditBadge(); break;
  }

  // Record this page in browser history so the back/forward buttons can step through pages
  if (pushState) {
    try { history.pushState({ page }, '', '#' + page); } catch(e) {}
  }
}

// Let the browser's own back/forward arrows step through app pages
window.addEventListener('popstate', function(e) {
  const page = (e.state && e.state.page) || 'dashboard';
  loadPage(page, false);
});

