function toggleDashLang() {
  dashLang = (dashLang === 'la') ? 'en' : 'la';
  const root = document.getElementById('dashboardLangRoot');
  if (root) root.classList.toggle('lang-en', dashLang === 'en');
  document.body.classList.toggle('lang-en', dashLang === 'en'); // ໃຫ້ box ຂະຫຍາຍ (zoom, cloned) ນອກ #dashboardLangRoot ກໍ່ຮັບການສະຫຼັບພາສານຳ
  const btn = document.getElementById('dashLangBtnLabel');
  if (btn) btn.textContent = (dashLang === 'la') ? 'EN' : 'ລາວ';
  if (typeof loadDashboard === 'function') loadDashboard(); // refresh pie chart SVG text (center label) to match new language
}

// ຂະຫຍາຍບ່ອນທີ່ຄຣິກໃສ່ໃຫ້ເຕັມຈໍ (ສຳລັບ presentation — ຄຣິກໃສ່ບາຊາດ/ຕາຕະລາງ ຈະເຫັນສະເພາະສ່ວນນັ້ນຂະຫຍາຍໃຫຍ່)
// ສະແດງລາຍລະອຽດແຕ່ລະບໍລິສັດພາຍໃນເຂດໜຶ່ງ (ຄຣິກຈາກຕາຕະລາງ "ແຮງງານຕາມເຂດ" ໜ້າພາບລວມ)
// ສະແດງລາຍລະອຽດເຕັມຂອງບໍລິສັດໜຶ່ງ (ໜ້າ "ຂໍ້ມູນບໍລິສັດ") — ຂໍ້ມູນ + ເອກະສານຄັດຕິດ (ເບິ່ງ/ພິມໄດ້)
function showCompanyDetail(id) {
  const c = allCompanies.find(x => x.id === id);
  if (!c) return;

  const docRow = (label, no, date, file) => {
    const url = companyDocUrl(file);
    const viewLink = url ? `<a href="${escAttr(url)}" target="_blank" rel="noopener" style="color:#1769C2;font-weight:600;">📄 ເບິ່ງເອກະສານ</a>` : '<span style="color:#aaa;">- ບໍ່ມີໄຟລ໌ -</span>';
    return `<tr>
      <td style="font-weight:600;">${esc(label)}</td>
      <td>${esc(no || '-')}</td>
      <td>${esc(date || '-')}</td>
      <td>${viewLink}</td>
    </tr>`;
  };

  let docRows = '';
  docRows += docRow('ໃບທະບຽນວິສາຫະກິດ', c.biz_reg_no, c.biz_reg_date, c.biz_reg_file);
  docRows += docRow('ໃບອະນຸຍາດລົງທຶນ', c.invest_no, c.invest_date, c.invest_file);
  docRows += docRow('ໃບທະບຽນອາກອນ', c.tax_no, c.tax_date, c.tax_file);
  docRows += docRow('ໃບທະບຽນປະກັນສັງຄົມ', c.social_no, c.social_date, c.social_file);
  docRows += docRow('ໃບອະນຸຍາດນຳໃຊ້ກົດລະບຽບ', c.rule_no, c.rule_date, c.rule_file);
  docRows += docRow('ໃບຢັ້ງຢືນກວດສຸຂະພາບ', c.health_no, c.health_date, c.health_file);
  (c.extra_docs || []).forEach(d => { docRows += docRow(d.name || 'ເອກະສານອື່ນໆ', d.no, d.date, d.file); });

  const overlay = document.createElement('div');
  overlay.id = 'companyDetailOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.78);z-index:99999;display:flex;align-items:center;justify-content:center;padding:24px;cursor:zoom-out;';
  const closeFn = () => { overlay.remove(); document.removeEventListener('keydown', escHandler); };
  overlay.onclick = closeFn;
  const escHandler = (e) => { if (e.key === 'Escape') closeFn(); };
  document.addEventListener('keydown', escHandler);

  const panel = document.createElement('div');
  panel.id = 'companyDetailPanel';
  panel.style.cssText = 'background:#fff;border-radius:16px;width:min(780px,94vw);max-height:90vh;overflow:auto;padding:28px;position:relative;cursor:default;box-shadow:0 20px 60px rgba(0,0,0,0.4);';
  panel.onclick = (e) => e.stopPropagation();
  panel.innerHTML = `
    <div style="font-size:20px;font-weight:700;color:#154360;">${esc(c.name_lao || '')}</div>
    <div style="font-size:13px;color:#888;margin-bottom:16px;">${esc(c.name_eng || '')}</div>
    <table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:18px;">
      <tr><td style="padding:6px 10px;font-weight:600;width:35%;background:#f7f9fb;">Username</td><td style="padding:6px 10px;">${esc(c.username || '-')}</td></tr>
      <tr><td style="padding:6px 10px;font-weight:600;background:#f7f9fb;">ເຂດ</td><td style="padding:6px 10px;">ເຂດ ${esc(c.zone || '-')}</td></tr>
      <tr><td style="padding:6px 10px;font-weight:600;background:#f7f9fb;">ສະຖານະ</td><td style="padding:6px 10px;">${c.is_active !== false ? '🟢 ດຳເນີນງານປົກກະຕິ' : '🔴 ຍົກເລີກກິດຈະການ/ຢຸດຜະລິດຊົ່ວຄາວ'}</td></tr>
    </table>
    <div style="font-size:15px;font-weight:700;color:#154360;margin-bottom:8px;">ເອກະສານກ່ຽວຂ້ອງ</div>
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead><tr style="background:#1a5276;color:#fff;">
        <th style="padding:8px;text-align:left;">ເອກະສານ</th><th style="padding:8px;text-align:left;">ເລກທີ</th><th style="padding:8px;text-align:left;">ວັນທີ</th><th style="padding:8px;text-align:left;">ໄຟລ໌</th>
      </tr></thead>
      <tbody>${docRows}</tbody>
    </table>`;
  const closeBtn = document.createElement('button');
  closeBtn.textContent = '✕';
  closeBtn.title = 'ປິດ (Esc)';
  closeBtn.style.cssText = 'position:absolute;top:10px;right:10px;background:#f1f1f1;border:none;border-radius:50%;width:36px;height:36px;font-size:16px;cursor:pointer;line-height:1;';
  closeBtn.onclick = closeFn;
  const printBtn = document.createElement('button');
  printBtn.innerHTML = '🖨️ ພິມ';
  printBtn.className = 'btn btn-info btn-sm';
  printBtn.style.cssText = 'position:absolute;top:10px;right:56px;';
  printBtn.onclick = () => printCompanyDetail(panel.innerHTML, c.name_lao || '');
  panel.appendChild(closeBtn);
  panel.appendChild(printBtn);
  overlay.appendChild(panel);
  document.body.appendChild(overlay);
}

function printCompanyDetail(html, nameLao) {
  const w = window.open('', '_blank');
  w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${esc(nameLao)}</title>
    <style>body{font-family:'Noto Sans Lao',sans-serif;padding:24px;} table{width:100%;} button{display:none!important;}</style>
    </head><body>${html}</body></html>`);
  w.document.close();
  w.onload = () => w.print();
}

function showZoneCompanies(zone) {
  const companies = Object.values(dashZoneCompanyData)
    .filter(c => c.zone === zone)
    .map(c => ({ ...c, total: c.lao + c.foreign }))
    .sort((a,b) => b.total - a.total);

  const rows = companies.map(c => `
    <tr>
      <td>${esc(c.code)}</td>
      <td>${esc(c.name)}</td>
      <td style="text-align:center;color:#2980b9;">${c.lao}</td>
      <td style="text-align:center;color:#c0392b;">${c.foreign}</td>
      <td style="text-align:center;font-weight:700;color:#154360;">${c.total}</td>
    </tr>`).join('') || `<tr><td colspan="5" style="text-align:center;color:#aaa;padding:20px;">ບໍ່ມີບໍລິສັດຢູ່ໃນເຂດນີ້</td></tr>`;

  const grandTotal = companies.reduce((s,c)=>s+c.total,0);

  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.78);z-index:99999;display:flex;align-items:center;justify-content:center;padding:24px;cursor:zoom-out;';
  const closeFn = () => { overlay.remove(); document.removeEventListener('keydown', escHandler); };
  overlay.onclick = closeFn;
  const escHandler = (e) => { if (e.key === 'Escape') closeFn(); };
  document.addEventListener('keydown', escHandler);

  const panel = document.createElement('div');
  panel.style.cssText = 'background:#fff;border-radius:16px;width:min(700px,92vw);max-height:88vh;overflow:auto;padding:24px;position:relative;cursor:default;box-shadow:0 20px 60px rgba(0,0,0,0.4);';
  panel.onclick = (e) => e.stopPropagation();
  panel.innerHTML = `
    <div style="font-size:18px;font-weight:700;color:#154360;margin-bottom:2px;">ເຂດ ${esc(zone)} — ລາຍລະອຽດແຕ່ລະບໍລິສັດ</div>
    <div style="font-size:12px;color:#888;margin-bottom:14px;">${companies.length} ບໍລິສັດ, ລວມ ${grandTotal} ຄົນ</div>
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead>
        <tr style="background:#1a5276;color:#fff;">
          <th style="padding:8px;text-align:left;">ລະຫັດ</th>
          <th style="padding:8px;text-align:left;">ຊື່ບໍລິສັດ</th>
          <th style="padding:8px;text-align:center;">ລາວ</th>
          <th style="padding:8px;text-align:center;">ຕ່າງປະເທດ</th>
          <th style="padding:8px;text-align:center;">ລວມ</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>`;
  const closeBtn = document.createElement('button');
  closeBtn.textContent = '✕';
  closeBtn.title = 'ປິດ (Esc)';
  closeBtn.style.cssText = 'position:absolute;top:10px;right:10px;background:#f1f1f1;border:none;border-radius:50%;width:36px;height:36px;font-size:16px;cursor:pointer;line-height:1;';
  closeBtn.onclick = closeFn;
  panel.appendChild(closeBtn);
  overlay.appendChild(panel);
  document.body.appendChild(overlay);
}

function expandDashCard(el, ev) {
  if (ev) ev.stopPropagation();
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.78);z-index:99999;display:flex;align-items:center;justify-content:center;padding:24px;cursor:zoom-out;';
  overlay.onclick = () => closeFn();
  const panel = document.createElement('div');
  panel.style.cssText = 'background:#fff;border-radius:16px;width:95vw;max-width:1700px;height:90vh;overflow:auto;padding:32px;position:relative;cursor:default;box-shadow:0 20px 60px rgba(0,0,0,0.4);display:flex;align-items:center;justify-content:center;';
  panel.onclick = (e) => e.stopPropagation();
  const scaleWrap = document.createElement('div');
  scaleWrap.style.cssText = 'transform:scale(1);transform-origin:center center;';
  scaleWrap.innerHTML = el.innerHTML;
  panel.appendChild(scaleWrap);
  const closeFn = () => {
    overlay.remove();
    document.removeEventListener('keydown', escHandler);
  };
  const escHandler = (e) => { if (e.key === 'Escape') closeFn(); };
  document.addEventListener('keydown', escHandler);
  const closeBtn = document.createElement('button');
  closeBtn.textContent = '✕';
  closeBtn.title = 'ປິດ (Esc)';
  closeBtn.style.cssText = 'position:absolute;top:10px;right:10px;background:#f1f1f1;border:none;border-radius:50%;width:36px;height:36px;font-size:16px;cursor:pointer;line-height:1;';
  closeBtn.onclick = closeFn;
  panel.appendChild(closeBtn);
  overlay.appendChild(panel);
  document.body.appendChild(overlay);
  // ຄິດໄລ່ອັດຕາການຂະຫຍາຍໃຫ້ພໍດີກັບພື້ນທີ່ box ອັດຕະໂນມັດ (ບໍ່ໃຫ້ຫວ່າງເກີນໄປ ຫຼືລົ້ນອອກນອກ box)
  requestAnimationFrame(() => {
    const rect = scaleWrap.getBoundingClientRect();
    const availW = panel.clientWidth - 64;
    const availH = panel.clientHeight - 64;
    if (rect.width > 0 && rect.height > 0) {
      const scale = Math.min(availW / rect.width, availH / rect.height, 4.5);
      scaleWrap.style.transform = `scale(${scale})`;
    }
  });
}

async function loadDashboard() {
  const now = new Date();
  const month = now.getMonth() + 1;
  const year = now.getFullYear();
  const monthNames = ['','ມັງກອນ','ກຸມພາ','ມີນາ','ເມສາ','ພຶດສະພາ','ມິຖຸນາ','ກໍລະກົດ','ສິງຫາ','ກັນຍາ','ຕຸລາ','ພະຈິກ','ທັນວາ'];
  const hbd = document.getElementById('heroBannerDate');
  if(hbd) hbd.textContent = monthNames[month] + ' ' + year;

  // ອັບເດດ badge ເດືອນປັດຈຸບັນຢູ່ກຣາຟ "ສະຖິຕິແຮງງານຕາມປີ" ໃຫ້ອັດຕະໂນມັດຕາມເດືອນ-ປີປັດຈຸບັນ
  const monthNamesEn = ['','January','February','March','April','May','June','July','August','September','October','November','December'];
  const latestBadge = document.getElementById('dashLatestMonthBadge');
  if(latestBadge) latestBadge.innerHTML = `<span class="i18n-la">${monthNames[month]} ${year}</span><span class="i18n-en">${monthNamesEn[month]} ${year}</span>`;
  const latestAxisLabel = document.getElementById('dashLatestYearAxisLabel');
  if(latestAxisLabel) latestAxisLabel.textContent = month + '/' + year;

  // ດຶງ live data ຈາກ lao_workers + foreign_workers ໂດຍກົງ (ບໍ່ໃຊ້ embedded join — ໃຊ້ zone ຈາກ activeCompanies ແທນ)
  const [{ data: laoData, error: laoErr }, { data: fwData, error: fwErr }] = await Promise.all([
    sb.from('lao_workers').select('id,gender,company_id'),
    sb.from('foreign_workers').select('id,gender,nationality,company_id')
  ]);
  if (laoErr) console.error('Dashboard lao_workers load error:', laoErr.message);
  if (fwErr) console.error('Dashboard foreign_workers load error:', fwErr.message);

  const zoneByCompany = {};
  activeCompanies.forEach(c => { zoneByCompany[c.id] = c.zone; });

  const activeIds = new Set(activeCompanies.map(c => c.id));
  const laoRows = (laoData||[]).filter(r => activeIds.has(r.company_id));
  const fwRows  = (fwData||[]).filter(r => activeIds.has(r.company_id) && !String(r.reg_id||'').startsWith('ER-'));

  let totalLaoM=0, totalLaoF=0, totalForeignM=0, totalForeignF=0;
  const zones = {};
  ['A','B','B1','C','D','E'].forEach(z => zones[z] = {companies:0, laoM:0, laoF:0, foreignM:0, foreignF:0});
  activeCompanies.forEach(c => { if(zones[c.zone]) zones[c.zone].companies++; });

  // ຂໍ້ມູນແຍກຕາມບໍລິສັດ ພາຍໃນແຕ່ລະເຂດ (ສຳລັບການຄຣິກເບິ່ງລາຍລະອຽດຢູ່ຕາຕະລາງ)
  const companyStats = {};
  activeCompanies.forEach(c => { companyStats[c.id] = { name: c.name_lao || c.username, code: c.username, zone: c.zone, lao: 0, foreign: 0 }; });

  const natMap = {};
  const isFemale = g => { const s = String(g||'').trim().toUpperCase(); return s === 'ຍິງ' || s === 'FEMALE' || s === 'F'; };
  laoRows.forEach(r => {
    const z = zoneByCompany[r.company_id];
    if(isFemale(r.gender)) totalLaoF++; else totalLaoM++;
    if(z && zones[z]) { if(isFemale(r.gender)) zones[z].laoF++; else zones[z].laoM++; }
    if(companyStats[r.company_id]) companyStats[r.company_id].lao++;
  });
  fwRows.forEach(r => {
    const z = zoneByCompany[r.company_id];
    const nat = r.nationality || 'ບໍ່ລະບຸ';
    if(isFemale(r.gender)) totalForeignF++; else totalForeignM++;
    if(z && zones[z]) { if(isFemale(r.gender)) zones[z].foreignF++; else zones[z].foreignM++; }
    if(!natMap[nat]) natMap[nat] = 0;
    natMap[nat]++;
    if(companyStats[r.company_id]) companyStats[r.company_id].foreign++;
  });
  if((totalLaoM+totalLaoF) > 0) natMap['ລາວ'] = totalLaoM+totalLaoF;
  dashZoneCompanyData = companyStats; // ເກັບໄວ້ໃນຕົວແປ global ໃຫ້ showZoneCompanies() ໃຊ້ໄດ້

  const totalLao     = totalLaoM + totalLaoF;
  const totalForeign = totalForeignM + totalForeignF;

  // Update stat cards
  document.getElementById('dsTotalCompanies').textContent = activeCompanies.length;
  document.getElementById('dsTotalLao').textContent = totalLao;
  document.getElementById('dsTotalLaoM').textContent = totalLaoM;
  document.getElementById('dsTotalLaoF').textContent = totalLaoF;
  document.getElementById('dsTotalForeign').textContent = totalForeign;
  document.getElementById('dsTotalForeignM').textContent = totalForeignM;
  document.getElementById('dsTotalForeignF').textContent = totalForeignF;
  document.getElementById('dsTotal').textContent = totalLao + totalForeign;

  // ອັບເດດແທ່ງບາ "ປັດຈຸບັນ" ໃນກຣາຟ "ສະຖິຕິແຮງງານຕາມປີ" ດ້ວຍຂໍ້ມູນຈິງຈາກຖານຂໍ້ມູນ (ບໍ່ໃຊ້ຕົວເລກຕາຍຕົວອີກຕໍ່ໄປ)
  (function updateCurrentYearBar() {
    const plotBottom = 130, plotTop = 8, maxScale = 8000; // matches the compact chart's viewBox now embedded in the hero card
    const scale = (plotBottom - plotTop) / maxScale;
    const laoBar = document.getElementById('dashCurLaoBar');
    const forBar = document.getElementById('dashCurForBar');
    const laoLabel = document.getElementById('dashCurLaoLabel');
    const forLabel = document.getElementById('dashCurForLabel');
    if (laoBar) {
      const h = Math.max(totalLao * scale, totalLao > 0 ? 2 : 0);
      laoBar.setAttribute('y', plotBottom - h);
      laoBar.setAttribute('height', h);
    }
    if (forBar) {
      const h = Math.max(totalForeign * scale, totalForeign > 0 ? 2 : 0);
      forBar.setAttribute('y', plotBottom - h);
      forBar.setAttribute('height', h);
    }
    if (laoLabel) {
      const y = plotBottom - Math.max(totalLao * scale, 2) - 8;
      laoLabel.setAttribute('y', y < 30 ? 30 : y);
      laoLabel.textContent = totalLao;
    }
    if (forLabel) {
      const y = plotBottom - Math.max(totalForeign * scale, 2) - 6;
      forLabel.setAttribute('y', y);
      forLabel.textContent = totalForeign;
    }
  })();

  // Zone table
  const tbody = document.getElementById('dashZoneTable');
  let ftC=0,ftLT=0,ftLM=0,ftLF=0,ftFT=0,ftFM=0,ftFF=0;
  if(tbody) tbody.innerHTML = Object.entries(zones).map(([z,d]) => {
    const lt=d.laoM+d.laoF, ft=d.foreignM+d.foreignF, tot=lt+ft;
    ftC+=d.companies; ftLT+=lt; ftLM+=d.laoM; ftLF+=d.laoF; ftFT+=ft; ftFM+=d.foreignM; ftFF+=d.foreignF;
    return `<tr onclick="event.stopPropagation();showZoneCompanies('${z}')" style="cursor:pointer;" title="ຄຣິກເບິ່ງລາຍລະອຽດແຕ່ລະບໍລິສັດໃນເຂດນີ້" onmouseenter="this.style.background='#f0f6fb'" onmouseleave="this.style.background=''">
      <td><span style="display:inline-block;padding:2px 10px;border-radius:12px;background:#1a5276;color:#fff;font-weight:700;font-size:12px;">ເຂດ ${z} 🔍</span></td>
      <td style="text-align:center;">${d.companies}</td>
      <td style="text-align:center;font-weight:600;">${lt}</td>
      <td style="text-align:center;color:#2980b9;">${d.laoM}</td>
      <td style="text-align:center;color:#1abc9c;">${d.laoF}</td>
      <td style="text-align:center;font-weight:600;">${ft}</td>
      <td style="text-align:center;color:#c0392b;">${d.foreignM}</td>
      <td style="text-align:center;color:#e67e22;">${d.foreignF}</td>
      <td style="text-align:center;font-weight:700;color:#154360;">${tot}</td>
    </tr>`;
  }).join('');
  ['ftCompanies','ftLaoTotal','ftLaoM','ftLaoF','ftForeignTotal','ftForeignM','ftForeignF','ftTotal'].forEach((id,i) => {
    const vals=[ftC,ftLT,ftLM,ftLF,ftFT,ftFM,ftFF,ftLT+ftFT];
    const el=document.getElementById(id); if(el) el.textContent=vals[i];
  });

  // ==== Nationality Donut (side card, true 3D extruded) ====
  const natMonthBadge = document.getElementById('dashNatMonthBadge');
  if (natMonthBadge) natMonthBadge.innerHTML = `📅 <span class="i18n-la">${monthNames[month]} ${year}</span><span class="i18n-en">${monthNamesEn[month]} ${year}</span>`;

  const donutArea = document.getElementById('dashNatDonutArea');
  if (donutArea && Object.keys(natMap).length > 0) {
    const NAT_COLORS = {
      'ລາວ': '#145A86', 'FILIPINO': '#19A765', 'MALAYSIAN': '#F04438', 'CHINESE': '#F6A000',
      'MYANMAR': '#8E44AD', 'CHINA': '#2878C8', 'ຈີນ': '#20A89A', 'KOREAN': '#E67E22',
    };
    const FALLBACK_COLORS = ['#9CA3AF','#5C6BC0','#26A69A','#EC407A','#7E57C2','#66BB6A'];
    let fallbackIdx = 0;
    const colorFor = (nat) => NAT_COLORS[nat] || FALLBACK_COLORS[(fallbackIdx++) % FALLBACK_COLORS.length];
    const darken = (hex, f=0.62) => {
      const n = parseInt(hex.slice(1),16);
      const r = Math.round(((n>>16)&255)*f), g = Math.round(((n>>8)&255)*f), b = Math.round((n&255)*f);
      return '#' + [r,g,b].map(v=>v.toString(16).padStart(2,'0')).join('');
    };

    const entries = Object.entries(natMap).sort((a,b)=>b[1]-a[1]);
    const grandTotal = entries.reduce((s,[,v])=>s+v,0);

    // Elliptical "3D" donut: squashed ellipse (rx/ry, hollow center) + extruded side wall of height `depth`
    const cx=100, cy=68, rxOuter=88, ryOuter=52, rxInner=46, ryInner=27, depth=16;
    let angle = -Math.PI/2;
    let sideSlices = '', topSlices = '', legend = '';
    const outerPt = (a) => [cx + rxOuter*Math.cos(a), cy + ryOuter*Math.sin(a)];
    const innerPt = (a) => [cx + rxInner*Math.cos(a), cy + ryInner*Math.sin(a)];

    entries.forEach(([nat, val], i) => {
      const pct = val/grandTotal;
      const sweep = pct * 2 * Math.PI;
      const a1 = angle;
      angle += sweep;
      const a2 = angle;
      const large = sweep > Math.PI ? 1 : 0;
      const col = colorFor(nat);
      const darkCol = darken(col);
      const [ox1,oy1] = outerPt(a1), [ox2,oy2] = outerPt(a2);
      const [ix1,iy1] = innerPt(a2), [ix2,iy2] = innerPt(a1);
      // Side wall (donut ring extrusion), shifted down by `depth`, darker shade — peeks out below to fake 3D depth
      sideSlices += `<path d="M${ox1},${oy1+depth} A${rxOuter},${ryOuter} 0 ${large},1 ${ox2},${oy2+depth} L${ix1},${iy1+depth} A${rxInner},${ryInner} 0 ${large},0 ${ix2},${iy2+depth} Z" fill="${darkCol}"/>`;
      // Top lid (donut ring)
      const midA = a2 - sweep/2;
      const midRx = (rxOuter+rxInner)/2, midRy = (ryOuter+ryInner)/2;
      const lx = cx + midRx*Math.cos(midA), ly = cy + midRy*Math.sin(midA);
      topSlices += `<path d="M${ox1},${oy1} A${rxOuter},${ryOuter} 0 ${large},1 ${ox2},${oy2} L${ix1},${iy1} A${rxInner},${ryInner} 0 ${large},0 ${ix2},${iy2} Z" fill="${col}" stroke="#fff" stroke-width="1.5"/>`;
      if (pct > 0.04) topSlices += `<text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle" fill="#fff" font-size="9" font-weight="bold" style="pointer-events:none;">${Math.round(pct*100)}%</text>`;

      legend += `<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;font-size:12px;">
        <span style="display:inline-block;width:12px;height:12px;border-radius:3px;background:${col};flex-shrink:0;"></span>
        <span style="flex:1;"><span class="i18n-la">${nat}</span><span class="i18n-en" style="font-weight:600;">${NATIONALITY_EN[nat]||nat}</span></span>
        <span style="font-weight:700;color:#333;">${val}</span>
        <span style="color:#888;font-size:11px;">(${Math.round(pct*100)}%)</span>
      </div>`;
    });

    donutArea.innerHTML = `
      <div style="display:flex;flex-direction:column;gap:14px;width:100%;">
        <svg viewBox="0 0 200 160" style="width:100%;max-width:260px;height:auto;margin:0 auto;display:block;filter:drop-shadow(0 6px 10px rgba(22,58,99,0.25));">
          ${sideSlices}
          ${topSlices}
          <text x="${cx}" y="${cy-4}" text-anchor="middle" font-size="11" font-weight="700" fill="#163A63"><tspan class="i18n-la">ລວມ</tspan><tspan class="i18n-en">Total</tspan></text>
          <text x="${cx}" y="${cy+13}" text-anchor="middle" font-size="19" font-weight="800" fill="#163A63">${grandTotal}</text>
        </svg>
        <div style="max-height:170px;overflow-y:auto;padding-right:4px;">${legend}</div>
      </div>`;
  } else if (donutArea) {
    donutArea.innerHTML = '<div style="text-align:center;color:#aaa;padding:40px 0;">ຍັງບໍ່ມີຂໍ້ມູນ</div>';
  }



  // Notifications panel
  const notifEl = document.getElementById('dashNotifList');
  if(notifEl) {
    if(notifications.length === 0) {
      notifEl.innerHTML = '<div style="text-align:center;color:#27ae60;padding:20px 0;">✅ ບໍ່ມີການແຈ້ງເຕືອນ</div>';
    } else {
      notifEl.innerHTML = notifications.slice(0,6).map(n => {
        // Determine link target based on notification type
        let linkHtml = '';
        if(n.companyId) {
          linkHtml = `<div style="margin-top:4px;">
            <a href="#" onclick="goToCompanyFromNotif('${n.companyId||''}','${n.page||'companies'}')" 
               style="font-size:11px;color:#2980b9;text-decoration:underline;">
              🔍 ກົດເບິ່ງຂໍ້ມູນ →
            </a>
          </div>`;
        }
        return `<div class="alert alert-${n.type}" style="margin-bottom:8px;padding:8px 12px;font-size:12px;cursor:pointer;" 
                     onclick="goToCompanyFromNotif('${n.companyId||''}','${n.page||'companies'}')">
          <div>${n.msg}</div>
          ${linkHtml}
        </div>`;
      }).join('') + (notifications.length>6 ? 
        `<div style="font-size:11px;color:#888;text-align:center;margin-top:4px;">+ ອີກ ${notifications.length-6} ລາຍການ — 
          <a href="#" onclick="showNotifications()" style="color:#2980b9;">ເບິ່ງທັງໝົດ</a>
        </div>` : '');
    }
  }
}


// ============================================================
// COMPANIES PAGE (Admin)
// ============================================================
function pageCompanies() {
  return `
  <div class="card">
    <div class="card-header">
      <span class="card-title">🏭 ຂໍ້ມູນບໍລິສັດ</span>
      <div class="flex" style="gap:8px;flex-wrap:wrap;">
        <select id="filterZone" onchange="filterCompanyTable()" style="padding:6px 10px;border:1px solid #ddd;border-radius:8px;font-family:inherit;font-size:13px;">
          <option value="">ທຸກເຂດ</option>
          <option value="A">ເຂດ A</option><option value="B">ເຂດ B</option>
          <option value="B1">ເຂດ B1</option><option value="C">ເຂດ C</option>
          <option value="D">ເຂດ D</option><option value="E">ເຂດ E</option>
        </select>
        <input type="text" id="searchCompanyInline" oninput="filterCompanyTable()" placeholder="🔍 ຄົ້ນຫາ..." style="padding:6px 10px;border:1px solid #ddd;border-radius:8px;font-family:inherit;font-size:13px;width:160px;">
        <button class="btn btn-success btn-sm" onclick="openAddCompany()">+ ເພີ້ມບໍລິສັດ</button>
        <button class="btn btn-info btn-sm" onclick="window.print()">🖨️ ພິມ</button>
      </div>
    </div>
    <div class="card-body">
      <div class="table-wrap"><table><thead><tr>
        <th>Username</th><th>ຊື່ (ລາວ)</th><th>ຊື່ (English)</th><th>ເຂດ</th><th>ລະຫັດ</th><th>ສະຖານະເອກະສານ</th><th>ສະຖານະການດຳເນີນງານ<br><span style="font-size:9px;font-weight:400;opacity:0.8;">Operating Status</span></th><th>ຈັດການ</th>
      </tr></thead><tbody id="companyTableBody"></tbody></table></div>
    </div>
  </div>`;
}

function filterCompanyTable(){
  const zone = document.getElementById('filterZone')?.value || '';
  const q = (document.getElementById('searchCompanyInline')?.value || '').toLowerCase();
  const rows = document.querySelectorAll('#companyTableBody tr');
  rows.forEach(row => {
    const text = row.textContent.toLowerCase();
    // Zone cell is the 4th td: "ເຂດ X"
    const cells = row.querySelectorAll('td');
    const zoneCell = cells[3] ? cells[3].textContent.trim() : '';
    const matchZone = !zone || zoneCell === ('ເຂດ ' + zone);
    const matchQ = !q || text.includes(q);
    row.style.display = (matchZone && matchQ) ? '' : 'none';
  });
}

async function loadCompanyTable() {
  await loadCompanies();
  const tbody = document.getElementById('companyTableBody');
  if (!tbody) return;
  const realCompanies = allCompanies.filter(c => !c.is_admin && !c.is_viewer); // ບໍ່ສະແດງບັນຊີພິເສດ (admin/viewer) — ບັນຊີເຫຼົ່ານັ້ນສະແດງຢູ່ໜ້າ "ຈັດການ Users" ແລ້ວ
  tbody.innerHTML = realCompanies.map(c => {
    const ruleStatus = getDocStatus(c.rule_date, 2);
    const healthStatus = getDocStatus(c.health_date, 1);
    const isActive = c.is_active !== false;
    const opStatus = isActive
      ? `<span class="status-ok">🟢 ດຳເນີນງານປົກກະຕິ<br><span style="font-size:9px;font-weight:400;">Operating</span></span>`
      : `<span class="status-expired">🔴 ຍົກເລີກກິດຈະການ/ຢຸດຜະລິດຊົ່ວຄາວ<br><span style="font-size:9px;font-weight:400;">Closed / Suspended</span></span>`;
    const toggleBtn = isActive
      ? `<button class="btn btn-danger btn-sm" onclick="suspendCompany('${c.id}','${escAttr(c.name_lao||'')}')">⛔ ລະງັບ</button>`
      : `<button class="btn btn-success btn-sm" onclick="reactivateCompany('${c.id}','${escAttr(c.name_lao||'')}')">▶️ ຍົກເລີກການລະງັບ</button>`;
    const bulkBtn = c.fn_bulk_uploaded
      ? `<button class="btn btn-warning btn-sm" onclick="unlockFnBulk('${c.id}','${escAttr(c.name_lao||'')}')">🔓 Unlock FN</button>`
      : '';
    return `<tr style="${isActive ? '' : 'opacity:0.55;background:#f8f8f8;'}">
      <td><b>${esc(c.username)}</b></td>
      <td>${esc(c.name_lao)}</td>
      <td>${esc(c.name_eng)}</td>
      <td>ເຂດ ${c.zone}</td>
      <td>****</td>
      <td>
        <span class="${ruleStatus.class}">${ruleStatus.text} (ກົດ)</span> /
        <span class="${healthStatus.class}">${healthStatus.text} (ສຸຂະ)</span>
      </td>
      <td>${opStatus}</td>
      <td>
        <button class="btn btn-secondary btn-sm" onclick="showCompanyDetail('${c.id}')" title="ເບິ່ງລາຍລະອຽດ">👁️</button>
        <button class="btn btn-info btn-sm" onclick="openEditCompany('${c.id}')">✏️</button>
        <button class="btn btn-warning btn-sm" onclick="openChangePassword('${c.id}','${escAttr(c.name_lao)}')">🔑</button>
        ${toggleBtn}
        ${bulkBtn}
        <button class="btn btn-danger btn-sm" onclick="deleteCompanyPermanently('${c.id}','${escAttr(c.name_lao||'')}','${escAttr(c.username||'')}')">🗑️ ລຶບຖາວອນ</button>
      </td>
    </tr>`;
  }).join('');
}

async function suspendCompany(id, nameLao) {
  if (!confirm(`ລະງັບການເຄື່ອນໄຫວຂອງ "${nameLao}" ຍ້ອນການຍົກເລີກກິດຈະການ?\n\nຂໍ້ມູນຍັງຄົງຖືກເກັບໄວ້ໃນລະບົບ ແຕ່ຈະບໍ່ສະແດງໃນໜ້າພາບລວມ, ສະຫຼຸບ, ແລະ ບົດລາຍງານທຸກປະເພດ — ສາມາດຍົກເລີກການລະງັບໄດ້ທຸກເວລາ`)) return;
  const { error } = await sb.from('companies').update({ is_active: false, closed_at: new Date().toISOString() }).eq('id', id);
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  await logAudit('update', 'companies', id, { action_detail: 'ລະງັບບໍລິສັດ', name_lao: nameLao });
  alert('✅ ລະງັບການເຄື່ອນໄຫວສຳເລັດ');
  loadCompanyTable();
}

async function reactivateCompany(id, nameLao) {
  if (!confirm(`ຍົກເລີກການລະງັບ ແລະ ເລີ່ມສະແດງຂໍ້ມູນ "${nameLao}" ໃນລະບົບຄືນ?`)) return;
  const { error } = await sb.from('companies').update({ is_active: true, closed_at: null }).eq('id', id);
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  await logAudit('update', 'companies', id, { action_detail: 'ຍົກເລີກການລະງັບບໍລິສັດ', name_lao: nameLao });
  alert('✅ ຍົກເລີກການລະງັບສຳເລັດ');
  loadCompanyTable();
}

// ============================================================
// ລຶບບໍລິສັດຖາວອນ — ລຶບຂໍ້ມູນທີ່ກ່ຽວຂ້ອງທັງໝົດອອກຈາກທຸກຕາຕະລາງ (ບໍ່ສາມາດກູ້ຄືນໄດ້)
// ============================================================
async function deleteCompanyPermanently(id, nameLao, username) {
  const warning = `⚠️ ການລຶບຖາວອນ ⚠️\n\nບໍລິສັດ: "${nameLao}" (${username})\n\nຈະລຶບຂໍ້ມູນທັງໝົດຂອງບໍລິສັດນີ້ອອກຈາກລະບົບ ລວມທັງ:\n- ຂໍ້ມູນບໍລິສັດ\n- ແຮງງານຕ່າງປະເທດ ແລະ ແຮງງານລາວ\n- ປະຫວັດການລາອອກ\n- ຂໍ້ມູນສະຖິຕິ/ບົດລາຍງານປະຈຳເດືອນ\n- ຂໍ້ມູນອື່ນໆທີ່ກ່ຽວຂ້ອງທັງໝົດ\n\n❌ ບໍ່ສາມາດກູ້ຄືນໄດ້ອີກ! ❌\n\nຖ້າແນ່ໃຈ ໃຫ້ພິມຊື່ຢຸດເຊີ "${username}" ຂ້າງລຸ່ມນີ້ເພື່ອຢືນຢັນ:`;
  const confirmInput = prompt(warning);
  const normalize = s => (s || '').trim().toLowerCase();
  if (confirmInput === null) return; // ຜູ້ໃຊ້ກົດ Cancel
  if (normalize(confirmInput) !== normalize(username)) {
    alert(`ຊື່ຢຸດເຊີບໍ່ຕົງ — ຍົກເລີກການລຶບ\n\nທ່ານພິມ: "${confirmInput}"\nຄາດວ່າ: "${username}"`);
    return;
  }

  const tablesWithCompanyId = [
    'foreign_workers', 'lao_workers', 'resignations', 'foreign_worker_renewals',
    'fw_requests', 'emp_movements', 'records', 'baseline_workers', 'baseline_status'
  ];

  try {
    for (const t of tablesWithCompanyId) {
      await sb.from(t).delete().eq('company_id', id);
    }
    const { error } = await sb.from('companies').delete().eq('id', id);
    if (error) throw error;

    await logAudit('delete', 'companies', id, { action_detail: 'ລຶບບໍລິສັດຖາວອນ (ພ້ອມຂໍ້ມູນທີ່ກ່ຽວຂ້ອງທັງໝົດ)', name_lao: nameLao, username });
    alert(`✅ ລຶບບໍລິສັດ "${nameLao}" ແລະ ຂໍ້ມູນທີ່ກ່ຽວຂ້ອງທັງໝົດອອກຈາກລະບົບສຳເລັດແລ້ວ`);
    loadCompanyTable();
  } catch (e) {
    alert('ເກີດຂໍ້ຜິດພາດໃນການລຶບ: ' + e.message);
  }
}

function getDocStatus(dateStr, years) {
  if (!dateStr) return { text: '-', class: '' };
  const exp = new Date(dateStr);
  exp.setFullYear(exp.getFullYear() + years);
  const today = new Date();
  if (exp <= today) return { text: 'ໝົດອາຍຸ', class: 'status-expired' };
  return { text: 'ຍັງໃຊ້ໄດ້', class: 'status-ok' };
}

async function openAddCompany() {
  document.getElementById('editCompanyId').value = '';
  document.getElementById('companyModalTitle').textContent = 'ເພີ້ມບໍລິສັດໃໝ່';
  ['cNameLao','cNameEng','cPassword','cUsername','dBizNo','dBizFile','dInvNo','dInvFile',
   'dTaxNo','dTaxFile','dSocNo','dSocFile','dRuleNo','dRuleFile','dRuleStatus',
   'dHealthNo','dHealthFile','dHealthStatus'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ['cZone','dBizDate','dInvDate','dTaxDate','dSocDate','dRuleDate','dHealthDate'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  document.getElementById('cUsername').placeholder = 'ຈະສ້າງອັດຕະໂນມັດຫຼັງເລືອກເຂດ';
  document.getElementById('cPassword').value = generateRandomPassword();
  document.getElementById('cPasswordRow').style.display = '';
  extraDocCount = 0;
  document.getElementById('extraDocsContainer').innerHTML = '';
  document.getElementById('companyModal').classList.add('show');
}

async function openEditCompany(id) {
  const c = allCompanies.find(x => x.id === id);
  if (!c) return;
  document.getElementById('editCompanyId').value = id;
  document.getElementById('companyModalTitle').textContent = 'ແກ້ໄຂຂໍ້ມູນບໍລິສັດ';
  document.getElementById('cNameLao').value = c.name_lao || '';
  document.getElementById('cNameEng').value = c.name_eng || '';
  document.getElementById('cZone').value = c.zone || '';
  document.getElementById('cUsername').value = c.username || '';
  document.getElementById('cPasswordRow').style.display = 'none';
  document.getElementById('dBizNo').value = c.biz_reg_no || '';
  document.getElementById('dBizDate').value = c.biz_reg_date || '';
  document.getElementById('dBizFile').value = c.biz_reg_file || '';
  document.getElementById('dInvNo').value = c.invest_no || '';
  document.getElementById('dInvDate').value = c.invest_date || '';
  document.getElementById('dInvFile').value = c.invest_file || '';
  document.getElementById('dTaxNo').value = c.tax_no || '';
  document.getElementById('dTaxDate').value = c.tax_date || '';
  document.getElementById('dTaxFile').value = c.tax_file || '';
  document.getElementById('dSocNo').value = c.social_no || '';
  document.getElementById('dSocDate').value = c.social_date || '';
  document.getElementById('dSocFile').value = c.social_file || '';
  document.getElementById('dRuleNo').value = c.rule_no || '';
  document.getElementById('dRuleDate').value = c.rule_date || '';
  document.getElementById('dRuleFile').value = c.rule_file || '';
  document.getElementById('dHealthNo').value = c.health_no || '';
  document.getElementById('dHealthDate').value = c.health_date || '';
  document.getElementById('dHealthFile').value = c.health_file || '';
  updateRuleStatus(); updateHealthStatus();

  // Extra docs
  extraDocCount = 0;
  document.getElementById('extraDocsContainer').innerHTML = '';
  (c.extra_docs || []).forEach(d => addExtraDoc(d));
  document.getElementById('companyModal').classList.add('show');
}

function updateUsername() {
  const zone = document.getElementById('cZone').value;
  const editId = document.getElementById('editCompanyId').value;
  const el = document.getElementById('cUsername');
  if (!zone) { el.value = ''; el.placeholder = 'ຈະສ້າງອັດຕະໂນມັດຫຼັງເລືອກເຂດ'; return; }
  if (editId) {
    // ກຳລັງແກ້ໄຂບໍລິສັດເກົ່າ — ສະແດງ preview ຊື່ຢຸດເຊີໃໝ່ຖ້າປ່ຽນເຂດ
    const c = allCompanies.find(x => x.id === editId);
    if (c?.reg_no) el.value = `SSEZ@${zone}${c.reg_no}`;
  } else {
    el.value = '';
    el.placeholder = `ຈະສ້າງອັດຕະໂນມັດ: SSEZ@${zone}(ລຳດັບ)`;
  }
}

function updateRuleStatus() {
  const d = document.getElementById('dRuleDate').value;
  const el = document.getElementById('dRuleStatus');
  if (!d) { el.value = ''; return; }
  const exp = new Date(d); exp.setFullYear(exp.getFullYear() + 2);
  el.value = exp <= new Date() ? 'ໝົດອາຍຸ' : 'ຍັງໃຊ້ໄດ້';
}

function updateHealthStatus() {
  const d = document.getElementById('dHealthDate').value;
  const el = document.getElementById('dHealthStatus');
  if (!d) { el.value = ''; return; }
  const exp = new Date(d); exp.setFullYear(exp.getFullYear() + 1);
  const warn = new Date(exp); warn.setMonth(warn.getMonth() - 1);
  const today = new Date();
  if (exp <= today) el.value = 'ໝົດອາຍຸ';
  else if (warn <= today) el.value = 'ຮອດກຳນົດ';
  else el.value = 'ຍັງໃຊ້ໄດ້';
}

// ອັບໂຫລດເອກະສານບໍລິສັດ (PDF/ຮູບ) ໄປ Supabase Storage bucket 'company-docs'
function triggerCompanyDocUpload(targetFieldId) {
  const picker = document.getElementById('companyDocFilePicker');
  picker.dataset.target = targetFieldId;
  picker.value = '';
  picker.click();
}

async function handleCompanyDocFileSelected(ev) {
  const file = ev.target.files[0];
  if (!file) return;
  const targetFieldId = ev.target.dataset.target;
  const targetInput = document.getElementById(targetFieldId);
  if (!targetInput) return;
  const ext = file.name.split('.').pop();
  const path = `companydocs/${targetFieldId}_${Date.now()}.${ext}`;
  targetInput.value = 'ກຳລັງອັບໂຫລດ...';
  const { error } = await supabaseRetry(() => sb.storage.from('company-docs').upload(path, file, { upsert: true }));
  if (error) { alert('ອັບໂຫລດຜິດພາດ: ' + error.message + '\n\n(ອາດຍ້ອນຍັງບໍ່ໄດ້ສ້າງ storage bucket "company-docs" — ຕິດຕໍ່ຜູ້ພັດທະນາ)'); targetInput.value = ''; return; }
  targetInput.value = path;
  alert('✅ ອັບໂຫລດສຳເລັດ — ກົດ "ບັນທຶກຂໍ້ມູນ" ເພື່ອບັນທຶກຄູ່ກັບບໍລິສັດ');
}

// ແປງຄ່າໃນຊ່ອງ "ໄຟລ" (path ທີ່ອັບໂຫລດ ຫຼື URL ພາຍນອກທີ່ພິມເອງ) ໃຫ້ເປັນ URL ທີ່ເປີດເບິ່ງໄດ້
function companyDocUrl(val) {
  if (!val) return null;
  if (/^https?:\/\//i.test(val)) return val; // ລິ້ງພາຍນອກທີ່ພິມເອງ (ຮູບແບບເກົ່າ)
  try { return sb.storage.from('company-docs').getPublicUrl(val).data.publicUrl; } catch(e) { return null; }
}

// ລະບົບແທຣັກກິງເອກະສານ — ໃຊ້ຮ່ວມກັນທັງ FN (ຂໍເຂົ້າໃໝ່) ແລະ FNR (ຂໍຕໍ່ບັດ)
// ຂັ້ນຕອນ: 1) ສົ່ງຄຳຮ້ອງ → 2) ແອັດມິນກວດເອກະສານ → 3) ອະນຸມັດຂັ້ນສຸດທ້າຍ (ຫຼື ❌ ຖືກປະຕິເສດ)
function buildFwTrackerHtml(r) {
  const step1Done = true; // ມີ record ແປວ່າສົ່ງຄຳຮ້ອງແລ້ວສະເໝີ
  const step2Done = r.status === 'reviewed' || r.final_approved;
  const step3Done = !!r.final_approved;
  const isRejected = !!r.rejected;

  const stepHtml = (label, done, active, dateStr) => `
    <div style="display:flex;flex-direction:column;align-items:center;flex:1;position:relative;">
      <div style="width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;
        background:${done ? '#2e9d67' : active ? '#f39c12' : '#dcdfe3'};color:${done||active?'#fff':'#888'};">
        ${done ? '✓' : active ? '⏳' : ''}
      </div>
      <div style="font-size:11px;text-align:center;margin-top:4px;color:${done?'#2e9d67':active?'#e67e22':'#999'};font-weight:${done||active?'700':'400'};max-width:90px;">${label}</div>
      ${dateStr ? `<div style="font-size:9px;color:#aaa;margin-top:1px;">${dateStr}</div>` : ''}
    </div>`;
  const lineHtml = (done) => `<div style="flex:0.5;height:3px;background:${done ? '#2e9d67' : '#dcdfe3'};margin-top:15px;"></div>`;

  if (isRejected) {
    return `
    <div style="background:#fdecea;border:1px solid #e74c3c;border-radius:10px;padding:14px 16px;margin-bottom:16px;">
      <div style="font-size:13px;font-weight:700;color:#c0392b;">❌ ຄຳຮ້ອງນີ້ຖືກປະຕິເສດ</div>
      ${r.rejected_reason ? `<div style="font-size:12px;color:#922b21;margin-top:4px;">ເຫດຜົນ: ${esc(r.rejected_reason)}</div>` : ''}
    </div>`;
  }

  return `
    <div style="background:#fff;border:1px solid #e1e8f0;border-radius:10px;padding:16px 20px;margin-bottom:16px;">
      <div style="display:flex;align-items:flex-start;">
        ${stepHtml('ສົ່ງຄຳຮ້ອງ', step1Done, false, laoDate(r.created_at))}
        ${lineHtml(step2Done)}
        ${stepHtml('ແອັດມິນກວດເອກະສານ', step2Done, !step2Done, r.reviewed_at ? laoDate(r.reviewed_at) : '')}
        ${lineHtml(step3Done)}
        ${stepHtml('ອະນຸມັດຂັ້ນສຸດທ້າຍ', step3Done, step2Done && !step3Done, r.final_approved_at ? laoDate(r.final_approved_at) : '')}
      </div>
      ${step2Done && !step3Done ? '<div style="text-align:center;font-size:12px;color:#e67e22;font-weight:600;margin-top:10px;">⏳ ລໍຖ້າອະນຸມັດຂັ້ນສຸດທ້າຍ</div>' : ''}
      ${step3Done ? `<div style="text-align:center;font-size:13px;color:#2e9d67;font-weight:700;margin-top:10px;">✅ ເອກະສານອະນຸມັດແລ້ວ${companyDocUrl(r.approved_file) ? ` — <a href="${escAttr(companyDocUrl(r.approved_file))}" target="_blank" rel="noopener" style="color:#1769C2;">📄 ເບິ່ງ/ດາວໂຫລດເອກະສານທີ່ເຊັນອະນຸມັດ</a>` : ''}</div>` : ''}
    </div>`;
}

function addExtraDoc(data = null) {
  if (extraDocCount >= 5) { alert('ສາມາດເພີ້ມໄດ້ສູງສຸດ 5 ເອກະສານ'); return; }
  extraDocCount++;
  const div = document.createElement('div');
  div.className = 'form-row';
  div.id = `extraDoc${extraDocCount}`;
  div.innerHTML = `
    <div class="form-field"><label>ຊື່ເອກະສານ ${extraDocCount}</label><input type="text" id="exName${extraDocCount}" value="${esc(data?.name || '')}"></div>
    <div class="form-field"><label>ເລກທີ</label><input type="text" id="exNo${extraDocCount}" value="${data?.no || ''}"></div>
    <div class="form-field"><label>ວັນທີ</label><input type="date" id="exDate${extraDocCount}" value="${data?.date || ''}"></div>
    <div class="form-field"><label>ໄຟລ</label><div style="display:flex;gap:4px;"><input type="text" id="exFile${extraDocCount}" value="${esc(data?.file || '')}" style="flex:1;"><button type="button" class="btn btn-secondary btn-sm" onclick="triggerCompanyDocUpload('exFile${extraDocCount}')" title="ອັບໂຫລດໄຟລ໌">📎</button></div></div>
    <div class="form-field" style="justify-content:flex-end;"><button class="btn btn-danger btn-sm" onclick="removeExtraDoc(${extraDocCount})">✕</button></div>
  `;
  document.getElementById('extraDocsContainer').appendChild(div);
  if (extraDocCount >= 5) document.getElementById('addExtraDocBtn').style.display = 'none';
}

function removeExtraDoc(n) {
  document.getElementById(`extraDoc${n}`)?.remove();
  extraDocCount--;
  document.getElementById('addExtraDocBtn').style.display = 'inline-flex';
}

async function saveCompany() {
  const id = document.getElementById('editCompanyId').value;
  const zone = document.getElementById('cZone').value;
  const nameLao = document.getElementById('cNameLao').value.trim();
  const nameEng = document.getElementById('cNameEng').value.trim();

  if (!nameLao || !nameEng || !zone) { alert('ກະລຸນາໃສ່ຂໍ້ມູນທີ່ຈຳເປັນ (*)'); return; }

  // Extra docs
  const extraDocs = [];
  for (let i = 1; i <= 5; i++) {
    const name = document.getElementById(`exName${i}`)?.value;
    if (name) extraDocs.push({ name, no: document.getElementById(`exNo${i}`)?.value || '', date: document.getElementById(`exDate${i}`)?.value || '', file: document.getElementById(`exFile${i}`)?.value || '' });
  }

  const payload = {
    name_lao: nameLao, name_eng: nameEng, zone,
    zone_number: allCompanies.filter(c => c.zone === zone).length + (id ? 0 : 1),
    biz_reg_no: document.getElementById('dBizNo').value, biz_reg_date: document.getElementById('dBizDate').value || null, biz_reg_file: document.getElementById('dBizFile').value,
    invest_no: document.getElementById('dInvNo').value, invest_date: document.getElementById('dInvDate').value || null, invest_file: document.getElementById('dInvFile').value,
    tax_no: document.getElementById('dTaxNo').value, tax_date: document.getElementById('dTaxDate').value || null, tax_file: document.getElementById('dTaxFile').value,
    social_no: document.getElementById('dSocNo').value, social_date: document.getElementById('dSocDate').value || null, social_file: document.getElementById('dSocFile').value,
    rule_no: document.getElementById('dRuleNo').value, rule_date: document.getElementById('dRuleDate').value || null, rule_file: document.getElementById('dRuleFile').value,
    health_no: document.getElementById('dHealthNo').value, health_date: document.getElementById('dHealthDate').value || null, health_file: document.getElementById('dHealthFile').value,
    extra_docs: extraDocs, updated_at: new Date().toISOString()
  };

  let error;
  let generatedPassword = null;
  let finalUsername = null;

  if (id) {
    // ແກ້ໄຂບໍລິສັດເກົ່າ — ອັບເດດຊື່ຢຸດເຊີໃຫ້ກົງກັບເຂດປັດຈຸບັນສະເໝີ (ໃຊ້ reg_no ເປັນລຳດັບ — ຄົງທີ່ຕະຫຼອດ)
    const c = allCompanies.find(x => x.id === id);
    const regNo = c?.reg_no;
    if (!regNo) { alert('ຂໍ້ຜິດພາດ: ບໍລິສັດນີ້ຍັງບໍ່ມີເລກລຳດັບ (reg_no) — ກະລຸນາແຈ້ງຜູ້ພັດທະນາ'); return; }
    finalUsername = `SSEZ@${zone}${regNo}`;
    payload.username = finalUsername;
    ({ error } = await sb.from('companies').update(payload).eq('id', id));
    if (!error) await logAudit('update', 'companies', id, { name_lao: nameLao, zone, username: finalUsername });
  } else {
    // ບໍລິສັດໃໝ່ — ສ້າງລະຫັດຜ່ານແບບສຸ່ມ ແລະ username ຊົ່ວຄາວ, ຈາກນັ້ນອັບເດດເປັນ SSEZ@ເຂດ+reg_no ຫຼັງໄດ້ຮັບ reg_no ຈິງ (auto ຈາກ Supabase)
    generatedPassword = document.getElementById('cPassword').value || generateRandomPassword();
    payload.password = bc.hashSync(generatedPassword, 10);
    payload.password_changed_at = new Date().toISOString();
    payload.username = `TEMP-${Date.now()}-${Math.floor(Math.random()*10000)}`;
    const { data: inserted, error: insErr } = await sb.from('companies').insert(payload).select().single();
    error = insErr;
    if (!error && inserted) {
      finalUsername = `SSEZ@${zone}${inserted.reg_no}`;
      const { error: updErr } = await sb.from('companies').update({ username: finalUsername }).eq('id', inserted.id);
      if (updErr) error = updErr;
      else await logAudit('create', 'companies', inserted.id, { name_lao: nameLao, zone, username: finalUsername });
    }
  }
  if (error) { alert('ເກີດຂໍ້ຜິດພາດ: ' + error.message); return; }
  closeModal('companyModal');
  await loadCompanies();
  loadCompanyTable();
  if (generatedPassword) {
    alert(`✅ ບັນທຶກຂໍ້ມູນສຳເລັດ\n\nUsername: ${finalUsername}\nລະຫັດຜ່ານ: ${generatedPassword}\n\n⚠️ ກະລຸນາຄັດລອກ/ຈົດໄວ້ດຽວນີ້ — ລະຫັດຜ່ານນີ້ຈະບໍ່ສະແດງອີກ!`);
  } else {
    alert(`✅ ບັນທຶກຂໍ້ມູນສຳເລັດ${finalUsername ? `\n\nUsername: ${finalUsername}` : ''}`);
  }
}

function openChangePassword(id, name) {
  document.getElementById('pwCompanyId').value = id;
  document.getElementById('pwCompanyName').value = name;
  document.getElementById('pwNew').value = generateRandomPassword();
  document.getElementById('pwModal').classList.add('show');
}

async function savePassword() {
  const id = document.getElementById('pwCompanyId').value;
  const pw = document.getElementById('pwNew').value.trim();
  if (!pw) { alert('ກະລຸນາໃສ່ລະຫັດຜ່ານໃໝ່'); return; }
  const { error } = await sb.from('companies').update({ password: bc.hashSync(pw, 10), password_changed_at: new Date().toISOString() }).eq('id', id);
  if (error) { alert('ເກີດຂໍ້ຜິດພາດ'); return; }
  await logAudit('update', 'companies', id, { action_detail: 'ແອັດມິນປ່ຽນລະຫັດຜ່ານໃຫ້ບໍລິສັດ' });
  closeModal('pwModal');
  await loadCompanies();
  alert(`✅ ປ່ຽນລະຫັດຜ່ານສຳເລັດ\n\nລະຫັດຜ່ານໃໝ່: ${pw}\n\n⚠️ ກະລຸນາຄັດລອກ/ຈົດໄວ້ດຽວນີ້ — ຈະບໍ່ສະແດງອີກ!`);
}

