// MY RECORD (Company monthly update)
// ============================================================
function pageMyRecord() {
  return `
  <div class="card">
    <div class="card-header">
      <span class="card-title">📊 ອັບເດດສະຖິຕິແຮງງານ</span>
      <button class="btn btn-success btn-sm" onclick="openAddRecord()">+ ເພີ້ມ/ອັບເດດ</button>
    </div>
    <div class="card-body">
      <div id="latestRecord"></div>
    </div>
  </div>`;
}

async function loadMyRecord() {
  const el = document.getElementById('latestRecord');
  if (!el) return;

  // Fetch monthly record, live FN workers, and live Lao workers in parallel
  const [recResult, fnResult, lwResult] = await Promise.all([
    sb.from('records').select('*').eq('company_id', currentUser.companyId)
      .order('year', { ascending: false }).order('month', { ascending: false }).limit(1),
    sb.from('foreign_workers').select('nationality,gender').eq('company_id', currentUser.companyId)
      .then(r => r).catch(() => ({ data: [] })),
    sb.from('lao_workers').select('gender').eq('company_id', currentUser.companyId)
      .then(r => r).catch(() => ({ data: [] }))
  ]);

  const r = recResult.data?.[0] || null;
  const fnWorkers = fnResult.data || [];
  const lwWorkers = lwResult.data || [];

  // FN breakdown (live)
  const fnNatMap = {};
  fnWorkers.forEach(w => {
    const nat = (w.nationality || 'ອື່ນໆ').trim() || 'ອື່ນໆ';
    if (!fnNatMap[nat]) fnNatMap[nat] = { nationality: nat, male: 0, female: 0 };
    if (w.gender === 'ຍິງ') fnNatMap[nat].female++; else fnNatMap[nat].male++;
  });
  const fnRows = Object.values(fnNatMap);
  const fnTotal = fnWorkers.length;
  const fnMale = fnWorkers.filter(w => w.gender !== 'ຍິງ').length;
  const fnFemale = fnWorkers.filter(w => w.gender === 'ຍິງ').length;

  // Lao counts — always from live lao_workers (C.3)
  const laoMale   = lwWorkers.filter(w => w.gender !== 'ຍິງ').length;
  const laoFemale = lwWorkers.filter(w => w.gender === 'ຍິງ').length;
  const laoTotal  = laoMale + laoFemale;
  const grandTotal = laoTotal + fnTotal;

  el.innerHTML = `
    ${r ? `<div class="alert alert-success">ອັບເດດລ້າສຸດ: <b>${MONTHS_LAO[r.month]} ${r.year}</b>
      <button class="btn btn-sm" style="margin-left:12px;background:#e8f4ff;color:#1a5276;border:1px solid #aed6f1;" onclick="openAddRecord()">✏️ ແກ້ໄຂ</button>
    </div>` : `<div class="alert alert-info">ຍັງບໍ່ມີຂໍ້ມູນ — ກົດ "+ ເພີ້ມ/ອັບເດດ" ເພື່ອໃສ່ຂໍ້ມູນ</div>`}
    <div class="stats-grid">
      <div class="stat-card lao"><div class="stat-label">ລາວລວມ<br><span style="font-size:9px;color:#888;">(ຈາກ C.3)</span></div><div class="stat-value">${laoTotal}</div></div>
      <div class="stat-card lao"><div class="stat-label">ລາວຊາຍ</div><div class="stat-value">${laoMale}</div></div>
      <div class="stat-card lao"><div class="stat-label">ລາວຍິງ</div><div class="stat-value">${laoFemale}</div></div>
      <div class="stat-card foreign"><div class="stat-label">ຕ່າງປະເທດ<br><span style="font-size:10px;color:#888;">(ຈາກ Section C)</span></div><div class="stat-value">${fnTotal}</div></div>
      <div class="stat-card total"><div class="stat-label">ລວມທັງໝົດ</div><div class="stat-value">${grandTotal}</div></div>
    </div>
    ${fnRows.length > 0 ? `
    <div class="section-title">ລາຍລະອຽດຕ່າງປະເທດ (ຈາກລົງທະບຽນ Section C)</div>
    <div class="table-wrap"><table><thead><tr><th>ສັນຊາດ</th><th>ຊາຍ</th><th>ຍິງ</th><th>ລວມ</th></tr></thead><tbody>
      ${fnRows.map(f=>`<tr><td>${esc(f.nationality)}</td><td>${f.male}</td><td>${f.female}</td><td>${f.male+f.female}</td></tr>`).join('')}
      <tr style="font-weight:700;background:#f0f4f8;"><td>ລວມ</td><td>${fnMale}</td><td>${fnFemale}</td><td>${fnTotal}</td></tr>
    </tbody></table></div>` : `<div style="color:#aaa;font-size:12px;margin-top:8px;">ຍັງບໍ່ມີຂໍ້ມູນ ຕປທ ຈາກ Section C</div>`}`;
}

async function openAddRecord() {
  document.getElementById('editRecordId').value = '';
  document.getElementById('editRecordCompanyId').value = currentUser.companyId;
  const now = new Date();
  document.getElementById('rMonth').value = now.getMonth() + 1;
  document.getElementById('rYear').value = now.getFullYear();
  document.getElementById('rDataDate').value = now.toISOString().split('T')[0];
  document.getElementById('rLaoMale').value = 0;
  document.getElementById('rLaoFemale').value = 0;
  document.getElementById('rLaoTotal').value = 0;
  document.getElementById('rForeignMaleTotal').value = 0;
  document.getElementById('rForeignFemaleTotal').value = 0;
  document.getElementById('rForeignTotal').value = 0;
  document.getElementById('foreignWorkerRows').innerHTML = '';

  // Load previous contact info
  const { data: prev } = await sb.from('records').select('*').eq('company_id', currentUser.companyId).order('created_at', { ascending: false }).limit(3);
  if (prev && prev.length > 0) {
    const p = prev[0];
    document.getElementById('rPrefix').value = p.contact_prefix || 'ທ້າວ';
    document.getElementById('rFirstname').value = p.contact_firstname || '';
    document.getElementById('rLastname').value = p.contact_lastname || '';
    document.getElementById('rRole').value = p.contact_role || 'ຝ່າຍບຸກຄະລາກອນ';
    // Datalists
    const fnames = [...new Set(prev.map(x => x.contact_firstname).filter(Boolean))];
    const lnames = [...new Set(prev.map(x => x.contact_lastname).filter(Boolean))];
    document.getElementById('prevFirstnames').innerHTML = fnames.map(n => `<option value="${n}">`).join('');
    document.getElementById('prevLastnames').innerHTML = lnames.map(n => `<option value="${n}">`).join('');
  }
  addForeignRow();
  document.getElementById('recordModal').classList.add('show');
}

function toggleRoleOther() {
  document.getElementById('roleOtherField').style.display = document.getElementById('rRole').value === 'ອື່ນໆ' ? 'flex' : 'none';
}

function calcLaoTotal() {
  const m = parseInt(document.getElementById('rLaoMale').value) || 0;
  const f = parseInt(document.getElementById('rLaoFemale').value) || 0;
  document.getElementById('rLaoTotal').value = m + f;
}

let foreignRowCount = 0;
function addForeignRow() {
  foreignRowCount++;
  const id = foreignRowCount;
  const div = document.createElement('div');
  div.className = 'form-row';
  div.id = `frow${id}`;
  div.innerHTML = `
    <div class="form-field">
      <label>ສັນຊາດ</label>
      <select id="fNat${id}" onchange="calcForeignTotal()">
        ${NATIONALITIES.map(n => `<option value="${n}">${n}</option>`).join('')}
      </select>
    </div>
    <div class="form-field"><label>ຊາຍ</label><input type="number" id="fMale${id}" value="0" min="0" oninput="calcForeignTotal()"></div>
    <div class="form-field"><label>ຍິງ</label><input type="number" id="fFemale${id}" value="0" min="0" oninput="calcForeignTotal()"></div>
    <div class="form-field" style="justify-content:flex-end;">
      <button class="btn btn-danger btn-sm" onclick="removeForeignRow(${id})" style="margin-top:22px;">✕</button>
    </div>`;
  document.getElementById('foreignWorkerRows').appendChild(div);
}

function removeForeignRow(id) {
  document.getElementById(`frow${id}`)?.remove();
  calcForeignTotal();
}

function calcForeignTotal() {
  let totalM = 0, totalF = 0;
  document.querySelectorAll('[id^="frow"]').forEach(row => {
    const id = row.id.replace('frow', '');
    totalM += parseInt(document.getElementById(`fMale${id}`)?.value) || 0;
    totalF += parseInt(document.getElementById(`fFemale${id}`)?.value) || 0;
  });
  document.getElementById('rForeignMaleTotal').value = totalM;
  document.getElementById('rForeignFemaleTotal').value = totalF;
  document.getElementById('rForeignTotal').value = totalM + totalF;
}

async function saveRecord() {
  const companyId = document.getElementById('editRecordCompanyId').value;
  const month = parseInt(document.getElementById('rMonth').value);
  const year = parseInt(document.getElementById('rYear').value);
  const role = document.getElementById('rRole').value;

  const fw = [];
  document.querySelectorAll('[id^="frow"]').forEach(row => {
    const id = row.id.replace('frow', '');
    const nat = document.getElementById(`fNat${id}`)?.value;
    const male = parseInt(document.getElementById(`fMale${id}`)?.value) || 0;
    const female = parseInt(document.getElementById(`fFemale${id}`)?.value) || 0;
    if (nat && (male > 0 || female > 0)) fw.push({ nationality: nat, male, female });
  });

  const payload = {
    company_id: companyId, year, month,
    contact_prefix: document.getElementById('rPrefix').value,
    contact_firstname: document.getElementById('rFirstname').value,
    contact_lastname: document.getElementById('rLastname').value,
    contact_role: role,
    contact_role_other: role === 'ອື່ນໆ' ? document.getElementById('rRoleOther').value : null,
    data_date: document.getElementById('rDataDate').value,
    lao_male: parseInt(document.getElementById('rLaoMale').value) || 0,
    lao_female: parseInt(document.getElementById('rLaoFemale').value) || 0,
    foreign_workers: fw,
    updated_at: new Date().toISOString()
  };

  const { error } = await sb.from('records').upsert(payload, { onConflict: 'company_id,year,month' });
  if (error) { alert('ເກີດຂໍ້ຜິດພາດ: ' + error.message); return; }
  closeModal('recordModal');
  loadMyRecord();
  alert('ບັນທຶກຂໍ້ມູນສຳເລັດ ✅');
}

