async function loadMyHistory() {
  const cid = currentUser.companyId;
  const loading = document.getElementById('historyLoading');

  const [
    { data: fnData },
    { data: fnrData },
    { data: laoData },
    { data: resignData }
  ] = await Promise.all([
    sb.from('foreign_workers').select('reg_id,prefix,firstname,lastname,nationality,gender,position,created_at')
      .eq('company_id', cid).not('reg_id', 'like', 'ER-%').order('created_at', { ascending: false }),
    sb.from('foreign_workers').select('reg_id,prefix,firstname,lastname,nationality,gender,position,updated_at')
      .eq('company_id', cid).like('reg_id', 'FNR-%').order('updated_at', { ascending: false }),
    sb.from('lao_workers').select('reg_id,firstname,lastname,gender,position,province,created_at')
      .eq('company_id', cid).order('created_at', { ascending: false }),
    sb.from('resignations').select('er_id,prefix,firstname,lastname,worker_type,resign_reason,resign_category,resign_date')
      .eq('company_id', cid).order('resign_date', { ascending: false })
  ]);

  if (loading) loading.style.display = 'none';

  // FN
  const fnBody = document.getElementById('histFnBody');
  if (fnBody) {
    const fnRows = (fnData || []).filter(w => !String(w.reg_id||'').startsWith('FNR'));
    fnBody.innerHTML = fnRows.length === 0
      ? '<tr><td colspan="6" style="text-align:center;color:#aaa;">ຍັງບໍ່ມີຂໍ້ມູນ</td></tr>'
      : fnRows.map(w => `<tr>
          <td><b>${esc(w.reg_id||'-')}</b></td>
          <td>${esc(w.prefix||'')} ${esc(w.firstname||'')} ${esc(w.lastname||'')}</td>
          <td>${esc(w.nationality||'-')}</td>
          <td>${w.gender||'-'}</td>
          <td>${esc(w.position||'-')}</td>
          <td>${laoDate(w.created_at)}</td>
        </tr>`).join('');
  }

  // FNR
  const fnrBody = document.getElementById('histFnrBody');
  if (fnrBody) {
    fnrBody.innerHTML = (fnrData||[]).length === 0
      ? '<tr><td colspan="6" style="text-align:center;color:#aaa;">ຍັງບໍ່ມີຂໍ້ມູນ</td></tr>'
      : (fnrData||[]).map(w => `<tr>
          <td><b>${esc(w.reg_id||'-')}</b></td>
          <td>${esc(w.prefix||'')} ${esc(w.firstname||'')} ${esc(w.lastname||'')}</td>
          <td>${esc(w.nationality||'-')}</td>
          <td>${w.gender||'-'}</td>
          <td>${esc(w.position||'-')}</td>
          <td>${laoDate(w.updated_at)}</td>
        </tr>`).join('');
  }

  // LAO
  const laoBody = document.getElementById('histLaoBody');
  if (laoBody) {
    laoBody.innerHTML = (laoData||[]).length === 0
      ? '<tr><td colspan="6" style="text-align:center;color:#aaa;">ຍັງບໍ່ມີຂໍ້ມູນ</td></tr>'
      : (laoData||[]).map(w => `<tr>
          <td><b>${esc(w.reg_id||'-')}</b></td>
          <td>${esc(w.firstname||'')} ${esc(w.lastname||'')}</td>
          <td>${w.gender||'-'}</td>
          <td>${esc(w.position||'-')}</td>
          <td>${esc(w.province||'-')}</td>
          <td>${laoDate(w.created_at)}</td>
        </tr>`).join('');
  }

  // RESIGN
  const resignBody = document.getElementById('histResignBody');
  if (resignBody) {
    resignBody.innerHTML = (resignData||[]).length === 0
      ? '<tr><td colspan="6" style="text-align:center;color:#aaa;">ຍັງບໍ່ມີຂໍ້ມູນ</td></tr>'
      : (resignData||[]).map(r => `<tr>
          <td><b>${esc(r.er_id||'-')}</b></td>
          <td>${esc(r.prefix||'')} ${esc(r.firstname||'')} ${esc(r.lastname||'')}</td>
          <td>${r.worker_type==='lao'?'🇱🇦 ລາວ':'🌏 ຕ.ປ.'}</td>
          <td>${esc(r.resign_reason||'-')}</td>
          <td>${r.resign_category||'-'}</td>
          <td>${laoDate(r.resign_date)}</td>
        </tr>`).join('');
  }
}

