function pageSummary51() {
  return `
  <div class="card">
    <div class="card-header">
      <span class="card-title">📋 ສະຫຼຸບ 5.1 — ແຮງງານລາວ + ຕ່າງປະເທດ ທຸກບໍລິສັດ</span>
      <div class="flex no-print">
        <select id="s51Zone" style="padding:6px 10px;border:1px solid #ddd;border-radius:8px;font-family:inherit;font-size:13px;">
          <option value="">ທຸກເຂດ</option>
          <option value="A">A</option><option value="B">B</option>
          <option value="B1">B1</option><option value="C">C</option>
          <option value="D">D</option><option value="E">E</option>
        </select>
        <button class="btn btn-primary btn-sm" onclick="loadSummary51()">🔍 ສະແດງ</button>
        <button class="btn btn-success btn-sm" onclick="exportSummary51()">📥 Excel</button>
        <button class="btn btn-info btn-sm" onclick="window.print()">🖨️ ພິມ</button>
      </div>
    </div>
    <div class="card-body"><div class="table-wrap" id="summary51Table"></div></div>
  </div>`;
}

async function loadSummary51() {
  // ດຶງຂໍ້ມູນຈາກ lao_workers + foreign_workers ໂດຍກົງ (ຄືກັບ Dashboard)
  // ເພື່ອໃຫ້ຕົວເລກກົງກັນກັບໜ້າພາບລວມ (FN + LA ເທົ່ານັ້ນ, ບໍ່ລວມ FNR)
  const activeIds = new Set(activeCompanies.map(c => c.id));
  const [{ data: laoData }, { data: fwData }] = await Promise.all([
    sb.from('lao_workers').select('id,gender,company_id'),
    sb.from('foreign_workers').select('id,gender,nationality,company_id,reg_id')
  ]);

  // สร้าง per-company maps
  const laoMap = {}; // company_id -> {male, female}
  const fwMap  = {}; // company_id -> {male, female}
  activeCompanies.forEach(c => { laoMap[c.id] = {male:0,female:0}; fwMap[c.id] = {male:0,female:0}; });

  (laoData||[]).filter(r => activeIds.has(r.company_id)).forEach(r => {
    if (!laoMap[r.company_id]) return;
    if (r.gender === 'ຍິງ') laoMap[r.company_id].female++;
    else laoMap[r.company_id].male++;
  });

  (fwData||[]).filter(r => activeIds.has(r.company_id) && !String(r.reg_id||'').startsWith('ER-')).forEach(r => {
    if (!fwMap[r.company_id]) return;
    if (r.gender === 'ຍິງ') fwMap[r.company_id].female++;
    else fwMap[r.company_id].male++;
  });

  const zoneFilter = document.getElementById('s51Zone')?.value || '';
  const filteredCompanies = zoneFilter ? activeCompanies.filter(c => c.zone === zoneFilter) : activeCompanies;

  let totalLaoM=0, totalLaoF=0, totalFM=0, totalFF=0;
  const rows = filteredCompanies.map(c => {
    const lM = laoMap[c.id]?.male||0, lF = laoMap[c.id]?.female||0;
    const fM = fwMap[c.id]?.male||0,  fF = fwMap[c.id]?.female||0;
    totalLaoM+=lM; totalLaoF+=lF; totalFM+=fM; totalFF+=fF;
    return `<tr>
      <td>${esc(c.username)}</td><td>${esc(c.name_lao)}</td>
      <td>ເຂດ ${c.zone}</td><td>${lM+lF}</td><td>${lM}</td><td>${lF}</td>
      <td>${fM+fF}</td><td>${fM}</td><td>${fF}</td><td><b>${lM+lF+fM+fF}</b></td>
    </tr>`;
  }).join('');

  document.getElementById('summary51Table').innerHTML = `
    <table><thead><tr>
      <th>ລະຫັດ</th><th>ຊື່ບໍລິສັດ</th><th>ເຂດ</th>
      <th>ລາວລວມ</th><th>ລາວຊາຍ</th><th>ລາວຍິງ</th>
      <th>ຕ່າງປະເທດ</th><th>ຕ.ປ.ຊາຍ</th><th>ຕ.ປ.ຍິງ</th><th>ລວມ</th>
    </tr></thead><tbody>
      ${rows}
      <tr style="background:#eaf4ff;font-weight:bold;">
        <td colspan="3">ລວມທັງໝົດ</td>
        <td>${totalLaoM+totalLaoF}</td><td>${totalLaoM}</td><td>${totalLaoF}</td>
        <td>${totalFM+totalFF}</td><td>${totalFM}</td><td>${totalFF}</td>
        <td>${totalLaoM+totalLaoF+totalFM+totalFF}</td>
      </tr>
    </tbody></table>`;
}

async function exportSummary51() {
  const table = document.querySelector('#summary51Table table');
  if (!table) return;
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.table_to_sheet(table);
  XLSX.utils.book_append_sheet(wb, ws, 'Summary 5.1');
  XLSX.writeFile(wb, 'SVKSEZ_Summary51.xlsx');
}

