function pageSummary52() {
  return `
  <div class="card">
    <div class="card-header">
      <span class="card-title">🌏 ສະຫຼຸບ 5.2 — ແຮງງານຕ່າງປະເທດ ແຍກສັນຊາດ</span>
      <div class="flex no-print" style="flex-wrap:wrap;gap:6px;">
        <select id="s52Zone" style="padding:8px;border:1px solid #ddd;border-radius:8px;font-family:inherit;">
          <option value="">ທຸກເຂດ</option>
          <option value="A">ເຂດ A</option><option value="B">ເຂດ B</option>
          <option value="B1">ເຂດ B1</option><option value="C">ເຂດ C</option>
          <option value="D">ເຂດ D</option><option value="E">ເຂດ E</option>
        </select>
        <button class="btn btn-primary btn-sm" onclick="loadSummary52()">🔍 ສະແດງ</button>
        <button class="btn btn-success btn-sm" onclick="exportSummary52()">📥 Excel</button>
        <button class="btn btn-info btn-sm" onclick="window.print()">🖨️ ພິມ</button>
      </div>
    </div>
    <div class="card-body"><div class="table-wrap" id="summary52Table"></div></div>
  </div>`;
}

async function loadSummary52() {
  const zoneFilter = document.getElementById('s52Zone')?.value || '';
  const filteredCompanies = zoneFilter ? activeCompanies.filter(c => c.zone === zoneFilter) : activeCompanies;
  const activeIds = new Set(filteredCompanies.map(c => c.id));

  // ດຶງຈາກ foreign_workers ໂດຍກົງ (ຄືກັບ Dashboard, filter ER- ອອກ)
  const { data: fwData } = await sb.from('foreign_workers')
    .select('id,gender,nationality,company_id,reg_id');

  // per-company, per-nationality map
  const coNatMap = {};
  filteredCompanies.forEach(c => { coNatMap[c.id] = {}; });

  (fwData||[])
    .filter(r => activeIds.has(r.company_id) && !String(r.reg_id||'').startsWith('ER-'))
    .forEach(r => {
      const nat = r.nationality || 'ບໍ່ລະບຸ';
      if (!coNatMap[r.company_id][nat]) coNatMap[r.company_id][nat] = {male:0, female:0};
      if (r.gender === 'ຍິງ') coNatMap[r.company_id][nat].female++;
      else coNatMap[r.company_id][nat].male++;
    });

  // Collect nationalities with total > 0
  const natGrandTotals = {};
  filteredCompanies.forEach(c => {
    Object.entries(coNatMap[c.id]).forEach(([nat,v]) => {
      if (!natGrandTotals[nat]) natGrandTotals[nat] = {male:0, female:0};
      natGrandTotals[nat].male += v.male;
      natGrandTotals[nat].female += v.female;
    });
  });
  const nats = Object.keys(natGrandTotals).filter(n => (natGrandTotals[n].male+natGrandTotals[n].female) > 0);

  const natColTotals = {};
  nats.forEach(n => natColTotals[n] = {male:0, female:0});
  let grandTotal = 0;

  const rows = filteredCompanies.map(c => {
    const natCols = nats.map(n => {
      const v = coNatMap[c.id][n] || {male:0, female:0};
      natColTotals[n].male += v.male; natColTotals[n].female += v.female;
      const tot = v.male + v.female;
      return `<td>${tot||''}</td><td>${v.male||''}</td><td>${v.female||''}</td>`;
    }).join('');
    const total = Object.values(coNatMap[c.id]).reduce((s,v)=>s+v.male+v.female, 0);
    grandTotal += total;
    return `<tr><td>${esc(c.username)}</td><td>${esc(c.name_lao)}</td><td>ເຂດ ${c.zone}</td>${natCols}<td><b>${total||''}</b></td></tr>`;
  }).join('');

  const natHeaders = nats.map(n => `<th colspan="3">${n}</th>`).join('');
  const natSubHeaders = nats.map(() => '<th>ລວມ</th><th>ຊາຍ</th><th>ຍິງ</th>').join('');
  const totalCols = nats.map(n => `<td>${natColTotals[n].male+natColTotals[n].female}</td><td>${natColTotals[n].male}</td><td>${natColTotals[n].female}</td>`).join('');

  document.getElementById('summary52Table').innerHTML = `
    <table><thead>
      <tr><th rowspan="2">ລະຫັດ</th><th rowspan="2">ຊື່ບໍລິສັດ</th><th rowspan="2">ເຂດ</th>${natHeaders}<th rowspan="2">ລວມ</th></tr>
      <tr>${natSubHeaders}</tr>
    </thead><tbody>
      ${rows}
      <tr style="background:#eaf4ff;font-weight:bold;">
        <td colspan="3">ລວມທັງໝົດ</td>${totalCols}<td>${grandTotal}</td>
      </tr>
    </tbody></table>`;
}

async function exportSummary52() {
  const table = document.querySelector('#summary52Table table');
  if (!table) return;
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.table_to_sheet(table);
  XLSX.utils.book_append_sheet(wb, ws, 'Summary 5.2');
  XLSX.writeFile(wb, 'SVKSEZ_Summary52.xlsx');
}

