// MONTHLY REPORT
// ============================================================
function pageMonthly() {
  const now = new Date();
  return `
  <div class="card">
    <div class="card-header">
      <span class="card-title">📊 ສະຖິຕິປະຈຳປີ<br><span style="font-size:11px;color:#888;font-weight:400;">Annual Labour Statistics</span></span>
      <div class="flex no-print" style="flex-wrap:wrap;gap:6px;">
        <select id="mrYear">${[2023,2024,2025,2026,2027].map(y=>`<option value="${y}" ${y===now.getFullYear()?'selected':''}>${y}</option>`).join('')}</select>
        <select id="mrZone" style="padding:8px;border:1px solid #ddd;border-radius:8px;font-family:inherit;">
          <option value="">ທຸກເຂດ</option>
          <option value="A">ເຂດ A</option><option value="B">ເຂດ B</option>
          <option value="B1">ເຂດ B1</option><option value="C">ເຂດ C</option>
          <option value="D">ເຂດ D</option><option value="E">ເຂດ E</option>
        </select>
        <button class="btn btn-primary btn-sm" onclick="loadMonthly()">🔍 ສະແດງ</button>
        <button class="btn btn-success btn-sm" onclick="exportMonthly()">📥 Excel</button>
        <button class="btn btn-info btn-sm" onclick="window.print()">🖨️ ພິມ</button>
      </div>
    </div>
    <div class="card-body">
      <div class="table-wrap" id="monthlyTable"></div>
    </div>
  </div>`;
}



async function loadMonthly() {
  const year = parseInt(document.getElementById('mrYear')?.value || new Date().getFullYear());
  const zoneFilter = document.getElementById('mrZone')?.value || '';

  // Fetch records + lao_workers in parallel
  const [recsRes, lwRes] = await Promise.all([
    sb.from('records').select('*, companies(id,username,name_lao,zone)').eq('year', year).order('month'),
    sb.from('lao_workers').select('company_id,gender')
  ]);

  const activeIds = new Set(activeCompanies.map(c => c.id));
  const filteredCompanies = zoneFilter
    ? activeCompanies.filter(c => c.zone === zoneFilter)
    : activeCompanies;
  const filteredIds = new Set(filteredCompanies.map(c => c.id));

  // Lao counts per company (live)
  const lwMap = {};
  (lwRes.data || []).filter(w => filteredIds.has(w.company_id)).forEach(w => {
    if (!lwMap[w.company_id]) lwMap[w.company_id] = { male: 0, female: 0 };
    if (w.gender === 'ຍິງ') lwMap[w.company_id].female++; else lwMap[w.company_id].male++;
  });

  // Records indexed by company+month
  const recMap = {};
  (recsRes.data || []).filter(r => filteredIds.has(r.company_id)).forEach(r => {
    if (!recMap[r.company_id]) recMap[r.company_id] = {};
    recMap[r.company_id][r.month] = r;
  });

  // Per-month aggregate totals for charts
  const chartLaoTotal = [], chartLaoM = [], chartLaoF = [];
  const chartFnTotal = [], chartFnM = [], chartFnF = [];

  for (let mo = 1; mo <= 12; mo++) {
    let laoM=0, laoF=0, fnM=0, fnF=0;
    filteredCompanies.forEach(c => {
      // Lao: use live lao_workers for current month logic
      // For historical months we use records; for latest we use lao_workers live
      const r = recMap[c.id]?.[mo];
      if (r) {
        // Use lao_workers live count for companies (best approximation per month from records)
        laoM += r.lao_male || 0;
        laoF += r.lao_female || 0;
        const fw = r.foreign_workers || [];
        fnM += fw.reduce((s,f)=>s+(f.male||0),0);
        fnF += fw.reduce((s,f)=>s+(f.female||0),0);
      }
    });
    chartLaoTotal.push(laoM+laoF); chartLaoM.push(laoM); chartLaoF.push(laoF);
    chartFnTotal.push(fnM+fnF); chartFnM.push(fnM); chartFnF.push(fnF);
  }

  // Build table rows — one row per company, 12 months each with 2 sub-columns
  const subCols = ['ລວມລາວ','ລວມຕ.ປ'];
  const headerMonths = MONTHS_LAO.slice(1).map(m =>
    `<th colspan="2" style="text-align:center;">${m}</th>`
  ).join('');
  const headerSub = Array.from({length:12}, () =>
    subCols.map(s=>`<th style="font-size:9px;min-width:42px;">${s}</th>`).join('')
  ).join('');

  const rows = filteredCompanies.map(c => {
    const monthCells = Array.from({length:12}, (_,i) => {
      const mo = i+1;
      const r = recMap[c.id]?.[mo];
      if (!r) return '<td>-</td><td>-</td>';
      const rLaoM = r.lao_male||0, rLaoF = r.lao_female||0;
      const fw = r.foreign_workers||[];
      const fT = fw.reduce((s,f)=>s+(f.male||0)+(f.female||0),0);
      return `<td>${rLaoM+rLaoF}</td><td>${fT}</td>`;
    }).join('');
    return `<tr>
      <td style="white-space:nowrap;font-weight:600;">${esc(c.username)}</td>
      <td style="white-space:nowrap;">${esc(c.name_lao)}</td>
      <td>ເຂດ ${c.zone}</td>
      ${monthCells}
    </tr>`;
  }).join('');

  // Grand total row
  const totalCells = Array.from({length:12}, (_,i) => {
    return `<td>${chartLaoTotal[i]||0}</td><td>${chartFnTotal[i]||0}</td>`;
  }).join('');

  document.getElementById('monthlyTable').innerHTML = `
    <div style="overflow-x:auto;">
    <table style="font-size:11px;border-collapse:collapse;min-width:100%;">
      <thead>
        <tr style="background:#1a5276;color:#fff;">
          <th rowspan="2" style="padding:6px 8px;min-width:70px;">ລະຫັດ</th>
          <th rowspan="2" style="padding:6px 8px;min-width:120px;">ຊື່ບໍລິສັດ</th>
          <th rowspan="2" style="padding:6px 8px;">ເຂດ</th>
          ${headerMonths}
        </tr>
        <tr style="background:#1a3a5c;color:#dde;">
          ${headerSub}
        </tr>
      </thead>
      <tbody>${rows || '<tr><td colspan="27" style="text-align:center;padding:20px;color:#aaa;">ບໍ່ມີຂໍ້ມູນ</td></tr>'}</tbody>
      <tfoot>
        <tr style="background:#2980b9;color:#fff;font-weight:700;">
          <td colspan="3" style="padding:6px 8px;">ລວມທຸກບໍລິສັດ</td>
          ${totalCells}
        </tr>
      </tfoot>
    </table>
    </div>`;

  // (charts removed)
}

async function exportMonthly() {
  const table = document.querySelector('#monthlyTable table');
  if (!table) return;
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.table_to_sheet(table);
  XLSX.utils.book_append_sheet(wb, ws, 'Monthly');
  XLSX.writeFile(wb, 'SVKSEZ_Monthly.xlsx');
}

