// SEARCH (Admin)
// ============================================================
function pageSearch() {
  return `
  <div class="card">
    <div class="card-header"><span class="card-title">🔍 ຄົ້ນຫາ</span></div>
    <div class="card-body">
      <!-- Tabs -->
      <div style="display:flex;gap:8px;margin-bottom:18px;border-bottom:2px solid #e0e8f0;padding-bottom:0;">
        <button id="sTab1" onclick="switchSearchTab(1)"
          style="padding:8px 20px;border:none;border-bottom:3px solid #1a3a5c;background:none;font-family:inherit;font-size:13px;font-weight:600;color:#1a3a5c;cursor:pointer;">
          🏭 ຄົ້ນຫາບໍລິສັດ
        </button>
        <button id="sTab2" onclick="switchSearchTab(2)"
          style="padding:8px 20px;border:none;border-bottom:3px solid transparent;background:none;font-family:inherit;font-size:13px;font-weight:400;color:#888;cursor:pointer;">
          👤 ຄົ້ນຫາພະນັກງານ ຕປທ
        </button>
      </div>

      <!-- Tab 1: Company search -->
      <div id="sTabPanel1">
        <div class="search-box mb-4" style="max-width:440px;position:relative;">
          <input type="text" id="searchInput" placeholder="ພິມຊື່ ຫຼື ລະຫັດບໍລິສັດ..."
            oninput="doSearch()"
            style="padding:10px 10px 10px 36px;width:100%;border:1px solid #ddd;border-radius:8px;font-family:inherit;font-size:13px;">
          <div id="autocompleteList" class="autocomplete-list" style="display:none;"></div>
        </div>
        <div id="searchResult"></div>
      </div>

      <!-- Tab 2: Employee search -->
      <div id="sTabPanel2" style="display:none;">
        <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px;">
          <input type="text" id="adminEmpSearchQ"
            placeholder="ພິມຊື່, ID ທະບຽນ, ຫຼື ເລກ Passport..."
            style="flex:1;min-width:240px;padding:10px 14px;border:1px solid #ddd;border-radius:8px;font-family:inherit;font-size:13px;"
            onkeydown="if(event.key==='Enter') adminSearchEmployee()">
          <button class="btn btn-primary" onclick="adminSearchEmployee()">🔍 ຄົ້ນຫາ</button>
          <button class="btn btn-secondary" onclick="document.getElementById('adminEmpSearchQ').value='';document.getElementById('adminEmpResult').innerHTML=''">✕ ລ້າງ</button>
        </div>
        <div id="adminEmpResult"></div>
      </div>
    </div>
  </div>`;
}

function switchSearchTab(t) {
  document.getElementById('sTabPanel1').style.display = t===1?'block':'none';
  document.getElementById('sTabPanel2').style.display = t===2?'block':'none';
  document.getElementById('sTab1').style.cssText = `padding:8px 20px;border:none;border-bottom:3px solid ${t===1?'#1a3a5c':'transparent'};background:none;font-family:inherit;font-size:13px;font-weight:${t===1?'600':'400'};color:${t===1?'#1a3a5c':'#888'};cursor:pointer;`;
  document.getElementById('sTab2').style.cssText = `padding:8px 20px;border:none;border-bottom:3px solid ${t===2?'#1a3a5c':'transparent'};background:none;font-family:inherit;font-size:13px;font-weight:${t===2?'600':'400'};color:${t===2?'#1a3a5c':'#888'};cursor:pointer;`;
}

async function adminSearchEmployee() {
  const q = (document.getElementById('adminEmpSearchQ')?.value || '').trim().toLowerCase();
  const el = document.getElementById('adminEmpResult');
  if (!el) return;
  if (!q) { el.innerHTML = ''; return; }
  el.innerHTML = '<div style="color:#aaa;padding:10px;">ກຳລັງຄົ້ນຫາ...</div>';

  const { data, error } = await sb.from('foreign_workers')
    .select('*, companies(id,username,name_lao,zone)');
  if (error) { el.innerHTML = `<div class="alert alert-danger">❌ ${error.message}</div>`; return; }

  const found = (data||[]).filter(w =>
    (`${esc(w.firstname||'')} ${esc(w.lastname||'')}`).toLowerCase().includes(q) ||
    (w.reg_id||'').toLowerCase().includes(q) ||
    (w.passport_no||'').toLowerCase().includes(q)
  );

  if (!found.length) {
    el.innerHTML = '<div style="color:#888;padding:10px;font-size:13px;">ບໍ່ພົບຂໍ້ມູນ — ກວດຊື່, ID ທະບຽນ ຫຼື ເລກ Passport ຄືນ</div>';
    return;
  }
  el.innerHTML = `<div style="font-size:12px;color:#888;margin-bottom:10px;">ພົບ ${found.length} ຄົນ</div>` +
    found.map(w => adminEmpCard(w)).join('');
}

function adminEmpCard(w) {
  const thumb = w.photo_path
    ? `<img src="${sb.storage.from('foreign-worker-docs').getPublicUrl(w.photo_path).data.publicUrl}" style="width:54px;height:72px;object-fit:cover;border-radius:6px;border:1px solid #ddd;flex-shrink:0;">`
    : `<div style="width:54px;height:72px;border:1px dashed #ccc;border-radius:6px;display:flex;align-items:center;justify-content:center;color:#ccc;font-size:22px;flex-shrink:0;">👤</div>`;
  const f = (label, val) => (!val||val==='-') ? '' :
    `<div style="display:flex;gap:6px;padding:4px 0;border-bottom:1px solid #f0f0f0;font-size:12px;">
      <span style="min-width:165px;color:#666;font-weight:600;">${esc(label)}</span>
      <span style="color:#111;">${esc(val)}</span>
    </div>`;
  const docExpiry = (label, expDate) => {
    if (!expDate) return f(label, '-');
    const exp = new Date(expDate);
    const today = new Date();
    const daysLeft = Math.ceil((exp - today) / 86400000);
    const cls = daysLeft < 0 ? 'color:#e74c3c;font-weight:700;' : daysLeft <= 21 ? 'color:#f39c12;font-weight:700;' : 'color:#111;';
    const tag = daysLeft < 0 ? ' ⚠️ ໝົດແລ້ວ' : daysLeft <= 21 ? ` ⚠️ ໝົດໃນ ${daysLeft} ວັນ` : '';
    return `<div style="display:flex;gap:6px;padding:4px 0;border-bottom:1px solid #f0f0f0;font-size:12px;">
      <span style="min-width:165px;color:#666;font-weight:600;">${label}</span>
      <span style="${cls}">${expDate}${tag}</span>
    </div>`;
  };
  const coName = w.companies ? `${esc(w.companies.username)} — ${esc(w.companies.name_lao)} (ເຂດ ${w.companies.zone})` : '-';
  return `
  <div style="background:#fff;border:1px solid #d0e8f8;border-radius:10px;padding:16px;margin-bottom:14px;">
    <div style="display:flex;gap:14px;">
      ${thumb}
      <div style="flex:1;">
        <div style="font-size:14px;font-weight:700;color:#1a3a5c;margin-bottom:2px;">${esc(w.prefix||'')} ${esc(w.firstname||'')} ${esc(w.lastname||'')}</div>
        <div style="font-size:12px;color:#2980b9;margin-bottom:6px;font-weight:600;">ID: ${esc(w.reg_id||'-')}</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;column-gap:20px;">
          <div>
            ${f('🏭 ບໍລິສັດ', coName)}
            ${f('ສັນຊາດ', w.nationality)}
            ${f('ເພດ', w.gender)}
            ${f('ວັນເດືອນປີເກີດ', w.dob ? laoDate(w.dob) : '')}
            ${f('ຕຳແໜ່ງ', w.position)}
            ${f('ເງິນເດືອນ', w.salary ? Number(w.salary).toLocaleString() + ' ກີບ' : '')}
            ${f('ກຳນົດຢູ່ລາວ', w.stay_duration ? w.stay_duration + ' ເດືອນ' : '')}
          </div>
          <div>
            ${f('ເລກ Passport', w.passport_no)}
            ${docExpiry('ໝົດ Passport', w.passport_expiry)}
            ${f('ເລກບັດແຮງງານ', w.labour_card_no)}
            ${docExpiry('ໝົດບັດແຮງງານ', w.labour_card_expiry)}
            ${f('ເລກບັດພັກເຊົາ', w.residence_card_no)}
            ${docExpiry('ໝົດບັດພັກເຊົາ', w.residence_card_expiry)}
            ${f('ເລກວີຊ່າ', w.visa_no)}
            ${docExpiry('ໝົດວີຊ່າ', w.visa_expiry)}
          </div>
        </div>
      </div>
    </div>
    <div style="font-size:11px;color:#aaa;margin-top:8px;text-align:right;">ລົງທະບຽນ: ${laoDate(w.created_at)}</div>
  </div>`;
}

function doSearch() {
  const q = document.getElementById('searchInput').value.toLowerCase();
  const list = document.getElementById('autocompleteList');
  if (!q) { list.style.display = 'none'; return; }
  const matches = allCompanies.filter(c => c.username.toLowerCase().includes(q) || c.name_lao.toLowerCase().includes(q) || c.name_eng.toLowerCase().includes(q));
  if (matches.length === 0) { list.style.display = 'none'; return; }
  list.style.display = 'block';
  list.innerHTML = matches.slice(0, 10).map(c => `
    <div class="autocomplete-item" onclick="selectCompany('${c.id}')">
      <b>${esc(c.username)}</b> — ${esc(c.name_lao)} ${c.is_active === false ? '<span style="color:#c0392b;font-size:11px;">🔴 ຍົກເລີກກິດຈະການ</span>' : ''}
    </div>`).join('');
}

async function selectCompany(id) {
  document.getElementById('autocompleteList').style.display = 'none';
  const c = allCompanies.find(x => x.id === id);
  if (!c) return;
  document.getElementById('searchInput').value = c.username + ' — ' + c.name_lao;

  // Get latest record
  const { data: recs } = await sb.from('records').select('*').eq('company_id', id).order('year', { ascending: false }).order('month', { ascending: false }).limit(1);
  const r = recs?.[0];
  const fw = r?.foreign_workers || [];
  const fM = fw.reduce((s,f)=>s+(f.male||0),0);
  const fF = fw.reduce((s,f)=>s+(f.female||0),0);
  const laoTotal = (r?.lao_male||0) + (r?.lao_female||0);

  const ruleStatus = getDocStatus(c.rule_date, 2);
  const healthStatus = getDocStatus(c.health_date, 1);

  document.getElementById('searchResult').innerHTML = `
    <div class="card" style="margin-top:16px;">
      <div class="card-header">
        <span class="card-title">${esc(c.username)} — ${esc(c.name_lao)}</span>
        <label><input type="checkbox" id="selectForPrint"> ເລືອກພິມ</label>
      </div>
      <div class="card-body">
        ${c.is_active === false ? `<div class="alert alert-danger" style="margin-bottom:12px;">🔴 ບໍລິສັດນີ້ຖືກລະງັບການເຄື່ອນໄຫວ (ຍົກເລີກກິດຈະການ/ຢຸດຜະລິດຊົ່ວຄາວ) — ນີ້ແມ່ນຂໍ້ມູນເກົ່າທີ່ເກັບໄວ້ ບໍ່ໄດ້ນັບໃນສະຫຼຸບ/ບົດລາຍງານ</div>` : ''}
        <div class="stats-grid">
          <div class="stat-card total"><div class="stat-label">ລວມທັງໝົດ</div><div class="stat-value">${laoTotal+fM+fF}</div></div>
          <div class="stat-card lao"><div class="stat-label">ລາວລວມ</div><div class="stat-value">${laoTotal}</div></div>
          <div class="stat-card lao"><div class="stat-label">ລາວຍິງ</div><div class="stat-value">${r?.lao_female||0}</div></div>
          <div class="stat-card lao"><div class="stat-label">ລາວຊາຍ</div><div class="stat-value">${r?.lao_male||0}</div></div>
          <div class="stat-card foreign"><div class="stat-label">ຕ່າງປະເທດ</div><div class="stat-value">${fM+fF}</div></div>
          <div class="stat-card foreign"><div class="stat-label">ຕ.ປ.ຊາຍ</div><div class="stat-value">${fM}</div></div>
          <div class="stat-card foreign"><div class="stat-label">ຕ.ປ.ຍິງ</div><div class="stat-value">${fF}</div></div>
        </div>
        ${r ? `<div class="alert alert-info">ຂໍ້ມູນ ≥ ${MONTHS_LAO[r.month]} ${r.year}</div>` : '<div class="alert alert-warning">ຍັງບໍ່ມີຂໍ້ມູນແຮງງານ</div>'}
        <div class="section-title">ເອກະສານ</div>
        <p>ໃບອະນຸຍາດນຳໃຊ້ກົດລະບຽບ: <span class="${ruleStatus.class}">${ruleStatus.text}</span></p>
        <p>ໃບຢັ້ງຢືນກວດສຸຂະພາບ: <span class="${healthStatus.class}">${healthStatus.text}</span></p>
        <div style="margin-top:12px;">
          <button class="btn btn-info btn-sm" onclick="openEditCompany('${c.id}')">✏️ ແກ້ໄຂ</button>
          <button class="btn btn-success btn-sm" onclick="exportSearchResult()">📥 Excel</button>
        </div>
      </div>
    </div>`;
}

function exportSearchResult() {
  const table = document.querySelector('#searchResult table');
  if (!table) { alert('ບໍ່ມີຕາຕະລາງ'); return; }
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.table_to_sheet(table);
  XLSX.utils.book_append_sheet(wb, ws, 'Result');
  XLSX.writeFile(wb, 'SVKSEZ_Search.xlsx');
}

