function pageBaseline() {
  return `
  <div class="card">
    <div class="card-header"><span class="card-title">🆕 ຂໍ້ມູນສະຖິຕິເລີ່ມຕົ້ນ<br><span style="font-size:11px;color:#888;font-weight:400;">Initial Baseline Workforce Data</span></span></div>
    <div class="card-body" id="baselineContent">
      <div style="text-align:center;color:#aaa;padding:20px;">ກຳລັງໂຫຼດ...</div>
    </div>
  </div>`;
}

function baselineSummaryCardsHtml(workers) {
  let laoM=0, laoF=0, forM=0, forF=0;
  workers.forEach(w => {
    const isLao = (w.nationality||'').trim() === 'ລາວ' || !w.nationality;
    const isF = w.gender === 'ຍິງ';
    if (isLao) { if(isF) laoF++; else laoM++; }
    else { if(isF) forF++; else forM++; }
  });
  const laoT = laoM+laoF, forT = forM+forF, grandT = laoT+forT, grandM = laoM+forM, grandF = laoF+forF;
  const cards = [
    ['🇱🇦 ແຮງງານລາວທັງໝົດ','Lao Total',laoT,'#1a5276'],
    ['♂ ແຮງງານລາວຊາຍ','Lao Male',laoM,'#2980b9'],
    ['♀ ແຮງງານລາວຍິງ','Lao Female',laoF,'#1abc9c'],
    ['🌏 ແຮງງານຕ່າງປະເທດທັງໝົດ','Foreign Total',forT,'#e67e22'],
    ['♂ ແຮງງານຕ່າງປະເທດຊາຍ','Foreign Male',forM,'#c0392b'],
    ['♀ ແຮງງານຕ່າງປະເທດຍິງ','Foreign Female',forF,'#e67e22'],
    ['👥 ແຮງງານລວມທັງໝົດ','Grand Total',grandT,'#8e44ad'],
    ['♂ ລວມຊາຍທັງໝົດ','Grand Total Male',grandM,'#2980b9'],
    ['♀ ລວມຍິງທັງໝົດ','Grand Total Female',grandF,'#1abc9c'],
  ];
  return `<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px;">
    ${cards.map(([lao,en,val,col]) => `
      <div class="stat-card" style="border-color:${col};padding:14px 16px;">
        <div class="stat-label">${lao}<br><span style="font-size:9px;color:#aaa;font-weight:400;">${en}</span></div>
        <div class="stat-value" style="font-size:24px;color:${col};">${val}</div>
      </div>`).join('')}
  </div>`;
}

function baselineWorkerTableHtml(workers) {
  return `<div class="table-wrap"><table><thead><tr>
    <th>ຊື່<br><span style="font-size:9px;font-weight:400;opacity:0.8;">First Name</span></th>
    <th>ນາມສະກຸນ<br><span style="font-size:9px;font-weight:400;opacity:0.8;">Last Name</span></th>
    <th>ເພດ<br><span style="font-size:9px;font-weight:400;opacity:0.8;">Gender</span></th>
    <th>ສັນຊາດ<br><span style="font-size:9px;font-weight:400;opacity:0.8;">Nationality</span></th>
    <th>ວຸດທິ<br><span style="font-size:9px;font-weight:400;opacity:0.8;">Education</span></th>
    <th>ຕຳແໜ່ງ<br><span style="font-size:9px;font-weight:400;opacity:0.8;">Position</span></th>
  </tr></thead><tbody>
    ${workers.map(w => `<tr>
      <td>${esc(w.firstname||'-')}</td><td>${esc(w.lastname||'-')}</td>
      <td>${w.gender||'-'}</td><td>${esc(w.nationality||'ລາວ')}</td>
      <td>${esc(w.education||'-')}</td><td>${esc(w.position||'-')}</td>
    </tr>`).join('')}
  </tbody></table></div>`;
}

async function loadBaseline() {
  const el = document.getElementById('baselineContent');
  if (!el) return;
  const companyId = currentUser.companyId;
  const [{ data: status }, { data: workers, error }] = await Promise.all([
    sb.from('baseline_status').select('*').eq('company_id', companyId).maybeSingle(),
    sb.from('baseline_workers').select('*').eq('company_id', companyId).order('created_at')
  ]);
  if (error) { el.innerHTML = `<div class="alert alert-danger">❌ ${error.message}<br><span style="font-size:11px;">ກວດສອບວ່າໄດ້ສ້າງຕາຕະລາງ baseline_workers / baseline_status ໃນ Supabase ແລ້ວບໍ່</span></div>`; return; }

  const confirmed = status?.confirmed;
  const hasData = (workers || []).length > 0;

  if (confirmed) {
    el.innerHTML = `
      <div class="alert alert-warning" style="margin-bottom:16px;">
        🔒 ຂໍ້ມູນສະຖິຕິເລີ່ມຕົ້ນຖືກຢືນຢັນແລ້ວ ບໍ່ສາມາດແກ້ໄຂໄດ້ — ຖ້າຕ້ອງການແກ້ໄຂ ກະລຸນາຕິດຕໍ່ແອັດມິນ
        <br><span style="font-size:11px;color:#888;">Confirmed and locked. Contact the admin if changes are needed.</span>
      </div>
      ${baselineSummaryCardsHtml(workers)}
      <div class="mb-4">
        <button class="btn btn-secondary btn-sm" onclick="resyncBaselineNow()">🔄 ອັບເດດຈຳນວນໄປໜ້າ "ແຮງງານທັງໝົດ" ຄືນ</button>
        <span style="font-size:11px;color:#888;"> — ກົດອັນນີ້ຖ້າຕົວເລກບໍ່ຂຶ້ນໃນໜ້າສະຫຼຸບ 5.1/5.2</span>
      </div>
      ${baselineWorkerTableHtml(workers)}`;
    return;
  }

  if (hasData) {
    el.innerHTML = `
      <div class="alert alert-info" style="margin-bottom:16px;">
        ✏️ ນີ້ແມ່ນຮ່າງຂໍ້ມູນທີ່ຍັງບໍ່ໄດ້ຢືນຢັນ — ກວດສອບຄວາມຖືກຕ້ອງ ຫຼື ອັບໂຫລດໄຟລ໌ໃໝ່ແທນອັນເກົ່າ ກ່ອນຢືນຢັນ
        <br><span style="font-size:11px;color:#888;">Draft — not yet confirmed. Review or re-upload before confirming.</span>
      </div>
      ${baselineSummaryCardsHtml(workers)}
      ${baselineWorkerTableHtml(workers)}
      <div class="flex mt-4" style="gap:8px;flex-wrap:wrap;">
        <button class="btn btn-success btn-sm" onclick="downloadBaselineTemplate()">📥 ດາວໂຫຼດແບບຟອມ</button>
        <label class="btn btn-primary btn-sm" style="cursor:pointer;">
          📤 ອັບໂຫລດໄຟລ໌ໃໝ່ (ແທນອັນເກົ່າ)
          <input type="file" accept=".xlsx,.xls" style="display:none;" onchange="uploadBaselineExcel(this)">
        </label>
        <button class="btn btn-warning btn-sm" onclick="confirmBaseline()">✅ ຢືນຢັນຄວາມຖືກຕ້ອງ</button>
      </div>
      <div id="baselinePreviewArea" class="mt-4"></div>`;
    return;
  }

  el.innerHTML = `
    <div class="alert alert-info" style="margin-bottom:12px;">
      📥 ດາວໂຫລດແບບຟອມ Excel ກ່ອນ ຕື່ມຂໍ້ມູນພະນັກງານທຸກຄົນທີ່ມີຢູ່ປະຈຸບັນ ແລ້ວອັບໂຫລດຄືນ — ນີ້ແມ່ນຂໍ້ມູນເລີ່ມຕົ້ນຄັ້ງທຳອິດ
      <br><span style="font-size:11px;color:#888;">Download the Excel template, fill in every current employee, then upload it back. This is your one-time starting baseline.</span>
    </div>
    <div class="flex mb-4" style="gap:8px;flex-wrap:wrap;">
      <button class="btn btn-success btn-sm" onclick="downloadBaselineTemplate()">📥 ດາວໂຫຼດແບບຟອມ</button>
      <label class="btn btn-primary btn-sm" style="cursor:pointer;">
        📤 ອັບໂຫລດໄຟລ Excel
        <input type="file" accept=".xlsx,.xls" style="display:none;" onchange="uploadBaselineExcel(this)">
      </label>
    </div>
    <div id="baselinePreviewArea"></div>`;
}

function downloadBaselineTemplate() {
  const wb = XLSX.utils.book_new();
  const headers = [['ຊື່','ນາມສະກຸນ','ເພດ (ຊາຍ/ຍິງ)','ສັນຊາດ (ລາວ=ລາວ)','ວຸດທິການສຶກສາ','ຕຳແໜ່ງ/ໜ້າທີ່']];
  headers.push(['ສົມສີ','ສີລາ','ຊາຍ','ລາວ','ປະລິຍາຕີ','ຫົວໜ້າຝ່າຍຜະລິດ']);
  headers.push(['ສີດາ','ວົງສະຫວັນ','ຍິງ','ລາວ','ມສ7','ພະນັກງານຝ່າຍຜະລິດ']);
  headers.push(['WANG','WEI','ຊາຍ','ຈີນ','ປະລິຍາຕີ','ວິສະວະກອນ']);
  const ws = XLSX.utils.aoa_to_sheet(headers);
  ws['!cols'] = headers[0].map(()=>({wch:22}));
  XLSX.utils.book_append_sheet(wb, ws, 'ຂໍ້ມູນເລີ່ມຕົ້ນ');
  XLSX.writeFile(wb, `SVKSEZ_ຂໍ້ມູນເລີ່ມຕົ້ນ.xlsx`);
}

async function uploadBaselineExcel(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = async (e) => {
    try {
      const wb = XLSX.read(e.target.result, { type:'binary', cellDates:true });
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(ws, { header:1, defval:'' });
      if (rows.length < 2) { alert('ໄຟລຫວ່າງ ຫຼື ບໍ່ມີຂໍ້ມູນ'); return; }
      const dataRows = rows.slice(1).filter(r => r.some(c => c !== ''));
      if (dataRows.length === 0) { alert('ບໍ່ມີຂໍ້ມູນໃນໄຟລ'); return; }

      const parsed = dataRows.map(r => ({
        firstname: r[0] || '', lastname: r[1] || '', gender: r[2] || '',
        nationality: (r[3] || 'ລາວ').toString().trim() || 'ລາວ',
        education: r[4] || '', position: r[5] || ''
      }));

      const previewEl = document.getElementById('baselinePreviewArea');
      previewEl.innerHTML = `<div class="alert alert-success">✅ ພົບຂໍ້ມູນ ${parsed.length} ລາຍການ — ກວດສອບກ່ອນບັນທຶກ</div>
        ${baselineSummaryCardsHtml(parsed)}
        ${baselineWorkerTableHtml(parsed)}
        <div class="mt-4"><button class="btn btn-primary" onclick="saveBaselineFromStore()">💾 ບັນທຶກຮ່າງຂໍ້ມູນ</button></div>`;
      window._baselinePreviewStore = parsed;
    } catch (err) {
      alert('ເກີດຂໍ້ຜິດພາດ: ' + err.message);
    }
  };
  reader.readAsBinaryString(file);
}

// Roll up baseline workers into the same shape used by the regular monthly
// "records" table (lao_male/lao_female/foreign_workers per nationality) so the
// numeric totals automatically appear in "ແຮງງານທັງໝົດ" (Summary 5.1) and
// "ແຮງງານຕ່າງປະເທດ" (Summary 5.2) without a separate manual entry.
function baselineToRecordsAggregate(workers) {
  const natMap = {};
  let laoM = 0, laoF = 0;
  workers.forEach(w => {
    const nat = (w.nationality || 'ລາວ').trim() || 'ລາວ';
    const isF = w.gender === 'ຍິງ';
    if (nat === 'ລາວ') {
      if (isF) laoF++; else laoM++;
    } else {
      if (!natMap[nat]) natMap[nat] = { nationality: nat, male: 0, female: 0 };
      if (isF) natMap[nat].female++; else natMap[nat].male++;
    }
  });
  return { lao_male: laoM, lao_female: laoF, foreign_workers: Object.values(natMap) };
}

async function syncBaselineToRecords(companyId, workers) {
  const agg = baselineToRecordsAggregate(workers);
  const now = new Date();
  const payload = {
    company_id: companyId,
    year: now.getFullYear(),
    month: now.getMonth() + 1,
    lao_male: agg.lao_male,
    lao_female: agg.lao_female,
    foreign_workers: agg.foreign_workers,
    data_date: now.toISOString().split('T')[0],
    updated_at: now.toISOString()
  };
  return await sb.from('records').upsert(payload, { onConflict: 'company_id,year,month' });
}

async function saveBaselineFromStore() {
  const parsed = window._baselinePreviewStore;
  if (!parsed || parsed.length === 0) { alert('ບໍ່ພົບຂໍ້ມູນທີ່ກຽມໄວ້ ກະລຸນາອັບໂຫລດໄຟລ໌ໃໝ່'); return; }
  if (!confirm(`ບັນທຶກຮ່າງຂໍ້ມູນ ${parsed.length} ລາຍການ? (ຍັງສາມາດອັບໂຫລດໄຟລ໌ໃໝ່ແທນໄດ້ ກ່ອນຢືນຢັນ)`)) return;
  const companyId = currentUser.companyId;
  // Replace any previous unconfirmed draft
  await supabaseRetry(() => sb.from('baseline_workers').delete().eq('company_id', companyId));
  const records = parsed.map(w => ({ company_id: companyId, ...w }));
  const { error } = await supabaseRetry(() => sb.from('baseline_workers').insert(records));
  if (error) { alert('ຜິດພາດ: ' + error.message + '\n\nກະລຸນາລອງໃໝ່ອີກຄັ້ງ (ອາດຍ້ອນມີຄົນໃຊ້ລະບົບພ້ອມກັນຫຼາຍ)'); return; }

  // Auto-populate the numeric totals into "ແຮງງານທັງໝົດ" (records table)
  const { error: recErr } = await supabaseRetry(() => syncBaselineToRecords(companyId, parsed));
  if (recErr) {
    alert('✅ ບັນທຶກຮ່າງສຳເລັດ ແຕ່ບໍ່ສາມາດສະແດງຜົນໃນໜ້າ "ແຮງງານທັງໝົດ" ໄດ້: ' + recErr.message);
  } else {
    alert('✅ ບັນທຶກຮ່າງສຳເລັດ ແລະ ອັບເດດຈຳນວນຕົວເລກໄປໜ້າ "ແຮງງານທັງໝົດ" ແລ້ວ');
  }
  delete window._baselinePreviewStore;
  loadBaseline();
}

async function resyncBaselineNow() {
  const companyId = currentUser.companyId;
  const { data: workers, error } = await sb.from('baseline_workers').select('*').eq('company_id', companyId);
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  if (!workers || workers.length === 0) { alert('ບໍ່ພົບຂໍ້ມູນພະນັກງານທີ່ບັນທຶກໄວ້'); return; }
  const { error: recErr } = await syncBaselineToRecords(companyId, workers);
  if (recErr) { alert('ຜິດພາດ: ' + recErr.message); return; }
  alert('✅ ອັບເດດຈຳນວນໄປໜ້າ "ແຮງງານທັງໝົດ" ສຳເລັດແລ້ວ');
}

async function confirmBaseline() {
  if (!confirm('ທ່ານແນ່ໃຈບໍວ່າຂໍ້ມູນຖືກຕ້ອງ? ຫຼັງຈາກຢືນຢັນແລ້ວ ຈະບໍ່ສາມາດແກ້ໄຂໄດ້ອີກ (ນອກຈາກແອັດມິນປົດລັອກໃຫ້)')) return;
  const companyId = currentUser.companyId;
  const { error } = await sb.from('baseline_status').upsert({ company_id: companyId, confirmed: true, confirmed_at: new Date().toISOString() });
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  alert('✅ ຢືນຢັນສຳເລັດ — ຂໍ້ມູນຖືກລັອກໄວ້ແລ້ວ');
  loadBaseline();
}

// ---- ADMIN: Baseline overview across all companies ----
