// ---- Shared FN/FNR summary helpers ----

// Build the summary card HTML (date-range filter + stat cards + nat/gender table).
// companyId = null means ALL companies (admin view).
function fnSummaryCardHtml(idPrefix, companyId) {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const fromDefault = `${y}-${m}-01`;
  const toDefault = now.toISOString().split('T')[0];
  const hiddenCo = companyId ? `<input type="hidden" id="${idPrefix}CoId" value="${companyId}">` : `<input type="hidden" id="${idPrefix}CoId" value="">`;
  return `
  <div class="card" style="margin-top:0;">
    <div class="card-header" style="background:linear-gradient(135deg,#1a3a5c,#215a86);border-radius:12px 12px 0 0;border-bottom:none;">
      <span class="card-title" style="color:#fff;font-size:14px;">📊 ສະຫຼຸບການລົງທະບຽນ ຕປທ (FN + FNR)<br>
        <span style="font-size:11px;color:#cfe0ec;font-weight:400;">Section C Summary — ເລືອກຊ່ວງເວລາ</span></span>
    </div>
    <div class="card-body">
      ${hiddenCo}
      <div class="form-row" style="max-width:600px;">
        <div class="form-group"><label>ຕັ້ງແຕ່ວັນທີ</label><input type="date" id="${idPrefix}From" value="${fromDefault}"></div>
        <div class="form-group"><label>ຫາວັນທີ</label><input type="date" id="${idPrefix}To" value="${toDefault}"></div>
        <div class="form-group" style="align-self:flex-end;">
          <button class="btn btn-primary btn-sm" onclick="loadFnSummary('${idPrefix}')">🔍 ສະແດງ</button>
        </div>
      </div>
      <div id="${idPrefix}SummaryResult" style="margin-top:12px;"></div>
    </div>
  </div>`;
}

async function loadFnSummary(idPrefix, viewMode) {
  const el = document.getElementById(`${idPrefix}SummaryResult`);
  if (!el) return;
  el.innerHTML = '<div style="color:#aaa;padding:10px;">ກຳລັງໂຫຼດ...</div>';
  const from = document.getElementById(`${idPrefix}From`).value;
  const to = document.getElementById(`${idPrefix}To`).value;
  const coId = document.getElementById(`${idPrefix}CoId`).value;
  const mode = viewMode || 'brief';

  let fnQuery = sb.from('foreign_workers').select('*');
  let fnrQuery = sb.from('foreign_worker_renewals').select('*');
  if (from) { fnQuery = fnQuery.gte('created_at', from); fnrQuery = fnrQuery.gte('created_at', from); }
  if (to) { const toEnd = to + 'T23:59:59'; fnQuery = fnQuery.lte('created_at', toEnd); fnrQuery = fnrQuery.lte('created_at', toEnd); }
  if (coId) { fnQuery = fnQuery.eq('company_id', coId); fnrQuery = fnrQuery.eq('company_id', coId); }

  const [{ data: fnDataRaw }, { data: fnrDataRaw }] = await Promise.all([fnQuery, fnrQuery]);
  const [fnData, fnrData] = await Promise.all([attachCompanyInfo(fnDataRaw), attachCompanyInfo(fnrDataRaw)]);
  // Exclude workers converted to FNR from FN list
  const fn = (fnData || []).filter(w => !String(w.reg_id||'').startsWith('FNR'));
  const fnr = fnrData || [];

  const buildNatTable = (rows) => {
    const natMap = {};
    rows.forEach(r => {
      const nat = r.nationality || 'ອື່ນໆ';
      if (!natMap[nat]) natMap[nat] = { m: 0, f: 0 };
      if (r.gender === 'ຍິງ') natMap[nat].f++; else natMap[nat].m++;
    });
    if (!Object.keys(natMap).length) return '<div style="color:#aaa;font-size:12px;">ບໍ່ມີຂໍ້ມູນໃນຊ່ວງເວລານີ້</div>';
    const rows2 = Object.entries(natMap).map(([nat, v]) =>
      `<tr><td>${nat}</td><td style="text-align:center;">${v.m}</td><td style="text-align:center;">${v.f}</td><td style="text-align:center;font-weight:600;">${v.m+v.f}</td></tr>`
    ).join('');
    const totM = rows.filter(r=>r.gender!=='ຍິງ').length, totF = rows.filter(r=>r.gender==='ຍິງ').length;
    return `<table style="font-size:12px;"><thead><tr><th>ສັນຊາດ</th><th>ຊາຍ</th><th>ຍິງ</th><th>ລວມ</th></tr></thead>
      <tbody>${rows2}</tbody>
      <tfoot><tr style="background:#f0f4f8;font-weight:700;"><td>ລວມ</td><td style="text-align:center;">${totM}</td><td style="text-align:center;">${totF}</td><td style="text-align:center;">${rows.length}</td></tr></tfoot>
    </table>`;
  };

  const buildDetailTable = (rows, isFnr) => {
    if (!rows.length) return '<div style="color:#aaa;font-size:12px;">ບໍ່ມີຂໍ້ມູນ</div>';
    return `<div class="table-wrap" style="overflow-x:auto;"><table style="font-size:11px;min-width:1000px;">
      <thead><tr>
        <th>ID</th><th>ບໍລິສັດ</th><th>ຊື່-ນາມສະກຸນ</th><th>ສັນຊາດ</th><th>ເພດ</th><th>ຕຳແໜ່ງ</th>
        <th>ເລກ Passport</th><th>ໝົດ Passport</th><th>ເລກບັດແຮງງານ</th><th>ໝົດບັດ</th>
        ${isFnr ? '<th>ຄັ້ງທີ</th>' : ''}<th>ກຳນົດຢູ່</th><th>ວັນທີລົງທະບຽນ</th>
      </tr></thead><tbody>
      ${rows.map(w=>`<tr>
        <td><b>${esc(w.reg_id)}</b></td>
        <td>${esc(w.companies?.username || '-')}</td>
        <td>${esc(w.prefix||'')} ${esc(w.firstname)} ${esc(w.lastname)}</td>
        <td>${esc(w.nationality||'-')}</td><td>${w.gender||'-'}</td>
        <td>${esc(w.position||'-')}</td>
        <td>${esc(w.passport_no||'-')}</td>
        <td>${w.passport_expiry||'-'}</td>
        <td>${esc(w.labour_card_no||'-')}</td>
        <td>${w.labour_card_expiry||'-'}</td>
        ${isFnr ? `<td>${w.labour_card_count||'-'}</td>` : ''}
        <td>${w.stay_duration||'-'} ດ.</td>
        <td>${laoDate(w.created_at)}</td>
      </tr>`).join('')}
      </tbody></table></div>`;
  };

  const modeToggle = `
    <div style="margin-bottom:12px;display:flex;gap:8px;">
      <button class="btn btn-sm ${mode==='brief'?'btn-primary':'btn-secondary'}" onclick="loadFnSummary('${idPrefix}','brief')">📊 ສະຫຼຸບຫຍໍ້</button>
      <button class="btn btn-sm ${mode==='detail'?'btn-primary':'btn-secondary'}" onclick="loadFnSummary('${idPrefix}','detail')">📋 ລາຍລະອຽດທັງໝົດ</button>
    </div>`;

  if (mode === 'brief') {
    el.innerHTML = modeToggle + `
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;">
        <div class="stat-card foreign" style="padding:14px;">
          <div class="stat-label">🆕 ລົງທະບຽນໃໝ່ (FN)<br><span style="font-size:10px;color:#888;">New Registrations</span></div>
          <div class="stat-value" style="font-size:32px;">${fn.length}</div>
          <div style="font-size:11px;color:#888;">ຊາຍ ${fn.filter(r=>r.gender!=='ຍິງ').length} / ຍິງ ${fn.filter(r=>r.gender==='ຍິງ').length}</div>
        </div>
        <div class="stat-card total" style="padding:14px;">
          <div class="stat-label">🔄 ຕໍ່ອາຍຸ (FNR)<br><span style="font-size:10px;color:#888;">Renewals</span></div>
          <div class="stat-value" style="font-size:32px;">${fnr.length}</div>
          <div style="font-size:11px;color:#888;">ຊາຍ ${fnr.filter(r=>r.gender!=='ຍິງ').length} / ຍິງ ${fnr.filter(r=>r.gender==='ຍິງ').length}</div>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
        <div><div class="section-title" style="font-size:12px;">ແຍກຕາມສັນຊາດ — FN</div><div class="table-wrap">${buildNatTable(fn)}</div></div>
        <div><div class="section-title" style="font-size:12px;">ແຍກຕາມສັນຊາດ — FNR</div><div class="table-wrap">${buildNatTable(fnr)}</div></div>
      </div>`;
  } else {
    el.innerHTML = modeToggle + `
      <div class="section-title" style="font-size:12px;">ລາຍລະອຽດ FN — ລົງທະບຽນໃໝ່ (${fn.length} ຄົນ)</div>
      ${buildDetailTable(fn, false)}
      <div class="section-title mt-4" style="font-size:12px;">ລາຍລະອຽດ FNR — ຕໍ່ອາຍຸ (${fnr.length} ຄັ້ງ)</div>
      ${buildDetailTable(fnr, true)}`;
  }
}

// End of shared FN/FNR summary helpers

function docExpiryStatus(dateStr, warnDays = 15) {
  if (!dateStr) return { text: '-', class: '' };
  const exp = new Date(dateStr);
  const today = new Date();
  const diffDays = Math.ceil((exp - today) / 86400000);
  if (diffDays < 0) return { text: 'ໝົດອາຍຸແລ້ວ', class: 'status-expired' };
  if (diffDays <= warnDays) return { text: `ໃກ້ໝົດ (${diffDays}ມ)`, class: 'status-expired' };
  return { text: 'ຍັງໃຊ້ໄດ້', class: 'status-ok' };
}

async function getCompanyCode(companyId) {
  const { data } = await sb.from('companies').select('username').eq('id', companyId).single();
  const u = data?.username || '';
  const at = u.indexOf('@');
  const code = (at >= 0 ? u.slice(at + 1) : u).toUpperCase().replace(/[^A-Z0-9]/g, '');
  return code;
}

async function generateRegId(prefix, table, companyId, companyCode) {
  const year = new Date().getFullYear();
  const month = String(new Date().getMonth() + 1).padStart(2, '0');
  const yy = String(year).slice(-2);
  const code = String(companyCode || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const idPrefix = `${prefix}${code}`;
  // ຄົ້ນຫາ ID ທັງໝົດຂອງບໍລິສັດນີ້ທີ່ຂຶ້ນຕົ້ນດ້ວຍ prefix+ລະຫັດບໍລິສັດ ແລ້ວເອົາເລກສູງສຸດ+1
  // (ໜັກແໜ້ນກວ່າການອີງໃສ່ reg_year — ບໍ່ຕົກຫຼົ່ນເຖິງແມ່ນ reg_year ຈະຄາດເຄື່ອນ)
  const { data: existing } = await sb.from(table).select('reg_id').eq('company_id', companyId).like('reg_id', `${idPrefix}%`);
  const usedIds = new Set((existing || []).map(r => r.reg_id));
  let maxSeq = 0;
  (existing || []).forEach(r => {
    const tail = String(r.reg_id || '').slice(idPrefix.length);
    const n = parseInt(tail.slice(-3), 10);
    if (!isNaN(n) && n > maxSeq) maxSeq = n;
  });
  let seq = maxSeq + 1;
  let regId;
  do {
    regId = `${idPrefix}${month}${yy}${String(seq).padStart(3, '0')}`;
    seq++;
  } while (usedIds.has(regId));
  return { regId, regYear: year };
}

async function uploadFwFile(file, regId, tag) {
  if (!file) return null;
  const ext = file.name.split('.').pop();
  const path = `${regId}/${tag}_${Date.now()}.${ext}`;
  const { error } = await sb.storage.from('foreign-worker-docs').upload(path, file, { upsert: true });
  if (error) { alert(`ອັບໂຫລດໄຟລ໌ (${tag}) ບໍ່ສຳເລັດ: ` + error.message); return null; }
  const { data } = sb.storage.from('foreign-worker-docs').getPublicUrl(path);
  return { type: tag, path, filename: file.name, url: data.publicUrl };
}

const FW_POSITIONS = [
  'ຜູ້ຈັດການທົ່ວໄປ','ຜູ້ຈັດການຝ່າຍຜະລິດ','ຜູ້ຈັດການຝ່າຍບຸກຄົນ',
  'ຜູ້ຈັດການຝ່າຍບໍລິຫານ','ຜູ້ຈັດການຝ່າຍການເງິນ-ການບັນຊີ','ຜູ້ຈັດການຝ່າຍການຕະຫຼາດ',
  'ວິຊາການຝ່າຍຜະລິດ','ວິຊາການດ້ານຄວາມປອດໄພ','ວິຊາການຝ່າຍຂົນສົ່ງ',
  'ວິສາວະກອນໄອທີ','ວິສາວະກອນໂຍທາ','ວິສາວະກອນໄຟຟ້າ',
  'ວິສາວະກອນກົນຈັກ','ວິສາວະກອນກໍ່ສ້າງ',
  'ຫົວໜ້າສາຍຜະລິດ','ວິຊາການຝຶກສອນ(ຄູຝຶກ)','ອື່ນໆ'
];

function positionFieldHtml(selId, txtId, currentVal) {
  const isOther = currentVal && !FW_POSITIONS.slice(0, -1).includes(currentVal);
  const selVal  = isOther ? 'ອື່ນໆ' : (currentVal || '');
  const txtVal  = isOther ? currentVal : '';
  const style   = 'width:100%;padding:10px 14px;border:1px solid #ddd;border-radius:8px;font-family:inherit;';
  return `
    <select id="${selId}" style="${style}" onchange="togglePositionOther('${selId}','${txtId}')">
      <option value="">— ເລືອກຕຳແໜ່ງ —</option>
      ${FW_POSITIONS.map(p=>`<option value="${p}" ${selVal===p?'selected':''}>${p}</option>`).join('')}
    </select>
    <input type="text" id="${txtId}" placeholder="ລະບຸຕຳແໜ່ງ/ໜ້າທີ່..."
      style="width:100%;margin-top:6px;padding:10px 14px;border:1px solid #ddd;border-radius:8px;font-family:inherit;${selVal==='ອື່ນໆ'?'':'display:none;'}"
      value="${esc(txtVal)}">`;
}

function togglePositionOther(selId, txtId) {
  const sel = document.getElementById(selId);
  const txt = document.getElementById(txtId);
  if (!sel || !txt) return;
  txt.style.display = sel.value === 'ອື່ນໆ' ? 'block' : 'none';
  if (sel.value !== 'ອື່ນໆ') txt.value = '';
}

function getPositionValue(selId, txtId) {
  const sel = document.getElementById(selId);
  return sel?.value === 'ອື່ນໆ'
    ? (document.getElementById(txtId)?.value?.trim() || 'ອື່ນໆ')
    : (sel?.value || '');
}

function setPositionField(selId, txtId, val) {
  const sel = document.getElementById(selId);
  const txt = document.getElementById(txtId);
  if (!sel || !txt) return;
  if (val && !FW_POSITIONS.slice(0, -1).includes(val)) {
    sel.value = 'ອື່ນໆ'; txt.value = val; txt.style.display = 'block';
  } else {
    sel.value = val || ''; txt.value = ''; txt.style.display = 'none';
  }
}

function fwSelectStyle() { return 'width:100%;padding:10px 14px;border:1px solid #ddd;border-radius:8px;font-family:inherit;'; }

// The native date picker's displayed format depends on the OS/browser locale, which
// ============================================================
// CUSTOM DATE PICKER — DD/MM/YYYY with year selector
// ============================================================
// Replaces all <input type="date"> with a custom 3-field picker
// showing DD / MM / YYYY and a clickable year that opens a year list.

function initCustomDatePickers(containerEl) {
  if (!containerEl) return;
  containerEl.querySelectorAll('input[type="date"]').forEach(inp => {
    if (inp.dataset.cdpDone) return;
    inp.dataset.cdpDone = '1';
    _buildCDP(inp);
  });
}

function _buildCDP(inp) {
  // Hide the native input but keep it in the DOM so existing code still reads .value
  inp.style.cssText = 'position:absolute;opacity:0;pointer-events:none;width:1px;height:1px;';

  const wrapper = document.createElement('div');
  wrapper.className = 'cdp-wrap';
  wrapper.style.cssText = 'display:inline-flex;align-items:center;gap:2px;border:1px solid #ddd;border-radius:8px;padding:6px 10px;background:#fff;font-family:inherit;font-size:13px;cursor:text;min-width:150px;position:relative;';

  // Three editable fields: DD / MM / YYYY
  const mkField = (placeholder, maxLen, min, max) => {
    const f = document.createElement('input');
    f.type = 'text'; f.placeholder = placeholder;
    f.maxLength = maxLen;
    f.style.cssText = `border:none;outline:none;width:${maxLen===4?'38px':'24px'};text-align:center;font-family:inherit;font-size:13px;padding:0;background:transparent;`;
    f.dataset.min = min; f.dataset.max = max;
    return f;
  };

  const fDay = mkField('DD', 2, 1, 31);
  const fMon = mkField('MM', 2, 1, 12);
  const fYr  = mkField('YYYY', 4, 1900, 2100);

  const sep1 = document.createElement('span'); sep1.textContent = '/'; sep1.style.cssText = 'color:#aaa;font-weight:600;';
  const sep2 = document.createElement('span'); sep2.textContent = '/'; sep2.style.cssText = 'color:#aaa;font-weight:600;';

  // Year dropdown button
  const yrBtn = document.createElement('button');
  yrBtn.type = 'button';
  yrBtn.textContent = '▾';
  yrBtn.title = 'ເລືອກປີ';
  yrBtn.style.cssText = 'border:none;background:none;cursor:pointer;color:#2980b9;font-size:13px;padding:0 2px;line-height:1;';

  // Year dropdown list
  const yrList = document.createElement('div');
  yrList.style.cssText = 'display:none;position:absolute;top:calc(100% + 4px);right:0;background:#fff;border:1px solid #ddd;border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.15);z-index:9999;max-height:200px;overflow-y:auto;min-width:90px;';
  const currentYear = new Date().getFullYear();
  for (let y = currentYear + 5; y >= 1990; y--) {
    const item = document.createElement('div');
    item.textContent = y;
    item.dataset.y = y;
    item.style.cssText = 'padding:7px 16px;cursor:pointer;font-size:13px;text-align:center;';
    item.addEventListener('mouseenter', () => item.style.background = '#e8f4ff');
    item.addEventListener('mouseleave', () => item.style.background = '');
    item.addEventListener('mousedown', e => {
      e.preventDefault();
      fYr.value = y;
      yrList.style.display = 'none';
      _cdpSync(inp, fDay, fMon, fYr);
      fYr.focus();
    });
    yrList.appendChild(item);
  }

  yrBtn.addEventListener('click', e => {
    e.stopPropagation();
    const open = yrList.style.display !== 'none';
    yrList.style.display = open ? 'none' : 'block';
    if (!open) {
      // Scroll to current year
      const cur = fYr.value || currentYear;
      const item = yrList.querySelector(`[data-y="${cur}"]`);
      if (item) item.scrollIntoView({ block: 'center' });
    }
  });

  document.addEventListener('click', () => { yrList.style.display = 'none'; });

  wrapper.appendChild(fDay); wrapper.appendChild(sep1);
  wrapper.appendChild(fMon); wrapper.appendChild(sep2);
  wrapper.appendChild(fYr);  wrapper.appendChild(yrBtn);
  wrapper.appendChild(yrList);

  inp.insertAdjacentElement('afterend', wrapper);

  // If native input already has a value, populate fields
  if (inp.value) {
    const [y,m,d] = inp.value.split('-');
    fDay.value = d || ''; fMon.value = m || ''; fYr.value = y || '';
  }

  // Handle focus styles
  wrapper.addEventListener('click', e => {
    if (!e.target.closest('.cdp-wrap>div')) fDay.focus();
    wrapper.style.borderColor = '#2980b9';
  });
  [fDay, fMon, fYr].forEach(f => {
    f.addEventListener('blur', () => {
      setTimeout(() => {
        if (!wrapper.contains(document.activeElement)) wrapper.style.borderColor = '#ddd';
      }, 100);
    });
  });

  // Numeric-only input with auto-advance
  fDay.addEventListener('input', () => {
    fDay.value = fDay.value.replace(/\D/g,'').slice(0,2);
    if (fDay.value.length === 2) fMon.focus();
    _cdpSync(inp, fDay, fMon, fYr);
  });
  fMon.addEventListener('input', () => {
    fMon.value = fMon.value.replace(/\D/g,'').slice(0,2);
    if (fMon.value.length === 2) fYr.focus();
    _cdpSync(inp, fDay, fMon, fYr);
  });
  fYr.addEventListener('input', () => {
    fYr.value = fYr.value.replace(/\D/g,'').slice(0,4);
    _cdpSync(inp, fDay, fMon, fYr);
  });

  // Backspace across fields
  fMon.addEventListener('keydown', e => { if (e.key==='Backspace' && !fMon.value) fDay.focus(); });
  fYr.addEventListener('keydown',  e => { if (e.key==='Backspace' && !fYr.value)  fMon.focus(); });
}

function _cdpSync(inp, fDay, fMon, fYr) {
  const dv = parseInt(fDay.value)||0;
  const mv = parseInt(fMon.value)||0;
  const yv = fYr.value;
  if (dv < 1 || dv > 31 || mv < 1 || mv > 12 || yv.length !== 4) return;
  const d = String(dv).padStart(2,'0');
  const m = String(mv).padStart(2,'0');
  const dateStr = `${yv}-${m}-${d}`;
  const dt = new Date(dateStr + 'T00:00:00');
  if (!isNaN(dt.getTime())) {
    inp.value = dateStr;
    inp.dispatchEvent(new Event('change', { bubbles: true }));
  }
}

// Legacy compatibility shim — any code calling attachDateFormatDisplays just runs initCustomDatePickers
function attachDateFormatDisplays(containerEl) {
  initCustomDatePickers(containerEl);
}

// Instantly preview a chosen photo file (before it's uploaded/saved) so the
// person always gets visual confirmation that their selection worked.
function previewFwPhoto(input, previewElId) {
  const el = document.getElementById(previewElId);
  if (!el) return;
  const file = input.files[0];
  if (!file) return;
  if (!file.type.startsWith('image/')) {
    alert('ກະລຸນາເລືອກໄຟລ໌ຮູບພາບ (JPG, PNG, ...) ເທົ່ານັ້ນ');
    input.value = '';
    return;
  }
  if (file.size > 8 * 1024 * 1024) {
    alert('ໄຟລ໌ຮູບໃຫຍ່ເກີນໄປ (ສູງສຸດ 8MB) ກະລຸນາເລືອກຮູບອື່ນ');
    input.value = '';
    return;
  }
  const reader = new FileReader();
  reader.onload = (e) => {
    el.innerHTML = `<img src="${e.target.result}" style="width:90px;height:120px;object-fit:cover;border-radius:8px;border:2px solid var(--secondary);">
      <div style="font-size:10px;color:#27ae60;margin-top:4px;">✅ ເລືອກຮູບແລ້ວ — ຈະອັບໂຫລດເມື່ອກົດ "ບັນທຶກຂໍ້ມູນ"</div>`;
  };
  reader.readAsDataURL(file);
}

// Standard photo-upload box markup: preview area + styled file picker, shared by
// both the new-registration and renewal forms for a consistent, trustworthy look.
function fwPhotoBoxHtml(fileInputId, previewId, currentPhotoUrl) {
  const initial = currentPhotoUrl
    ? `<img src="${currentPhotoUrl}" style="width:90px;height:120px;object-fit:cover;border-radius:8px;border:1px solid #ddd;">`
    : `<div style="width:90px;height:120px;border:2px dashed #ccc;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#bbb;font-size:28px;">👤</div>`;
  return `
    <div style="display:flex;gap:14px;align-items:flex-start;">
      <div id="${previewId}">${initial}</div>
      <div style="flex:1;">
        <input type="file" id="${fileInputId}" accept="image/*" onchange="previewFwPhoto(this,'${previewId}')" style="width:100%;">
        <div style="font-size:11px;color:#888;margin-top:4px;">ຮູບຖ່າຍຂະໜາດ 3x4, ໄຟລ໌ JPG/PNG, ບໍ່ເກີນ 8MB</div>
      </div>
    </div>`;
}
function fnPrefixOptions() { return ['MR','MRS','MISS','MS'].map(p => `<option value="${p}">${p}</option>`).join(''); }
function fwGenderOptions() { return ['ຊາຍ','ຍິງ'].map(g => `<option value="${g}">${g}</option>`).join(''); }
function fwStayOptions() { return [1,3,6,12].map(m => `<option value="${m}">${m} ເດືອນ</option>`).join(''); }
// ຈຳກັດ "ກຳນົດຢູ່" ສູງສຸດ 12 ເດືອນ (ຄືກັນກັບ dropdown ການລົງທະບຽນທີລະຄົນ) — ໃຊ້ຕອນອ່ານຄ່າຈາກ Excel bulk upload ເພື່ອບໍ່ໃຫ້ຄ່າເກີນຫຼຸດຜ່ານໄດ້
function capStayDuration(v) {
  const n = parseInt(v);
  if (!n || isNaN(n)) return null;
  return n > 12 ? 12 : n;
}

function toggleNatCustom(selectId, customId) {
  const sel = document.getElementById(selectId);
  const custom = document.getElementById(customId);
  if (!sel || !custom) return;
  custom.style.display = (sel.value === 'ອື່ນໆ') ? 'block' : 'none';
  if (sel.value !== 'ອື່ນໆ') custom.value = '';
}
function getNatValue(selectId, customId) {
  const sel = document.getElementById(selectId);
  const custom = document.getElementById(customId);
  if (sel && sel.value === 'ອື່ນໆ' && custom && custom.value.trim()) return custom.value.trim();
  return sel ? sel.value : '';
}

function autoFillGender(prefixId, genderId) {
  const p = document.getElementById(prefixId);
  const g = document.getElementById(genderId);
  if (!p || !g) return;
  g.value = (p.value === 'MR') ? 'ຊາຍ' : 'ຍິງ';
}
function fwNatOptions() { return NATIONALITIES.map(n => `<option value="${n}">${n}</option>`).join(''); }

// Recompute this company's foreign-worker headcount (by nationality/gender) from the
// Section C master registry and push it into the current month's "records" row so it
// automatically appears in "ແຮງງານຕ່າງປະເທດ" (Summary 5.2, Section B).
async function syncForeignWorkersToRecords(companyId) {
  const now = new Date();
  const yr = now.getFullYear(), mo = now.getMonth() + 1;

  // 1. Pull all FN-registered workers for this company from Section C
  const { data: workers } = await sb.from('foreign_workers').select('nationality,gender').eq('company_id', companyId);
  const fnMap = {};
  (workers || []).forEach(w => {
    const nat = (w.nationality || 'ອື່ນໆ').trim() || 'ອື່ນໆ';
    if (!fnMap[nat]) fnMap[nat] = { nationality: nat, male: 0, female: 0 };
    if (w.gender === 'ຍິງ') fnMap[nat].female++; else fnMap[nat].male++;
  });
  const fnRows = Object.values(fnMap);

  // 2. Fetch existing record (avoid maybeSingle — use limit(1) array check instead)
  const { data: existingArr } = await sb.from('records')
    .select('id,foreign_workers,lao_male,lao_female')
    .eq('company_id', companyId).eq('year', yr).eq('month', mo)
    .limit(1);

  const existing = existingArr && existingArr.length > 0 ? existingArr[0] : null;

  // 3. Merge: keep existing manual entries that are NOT covered by FN nationality keys,
  //    then append the FN rows. This avoids overwriting Lao-worker fields.
  const manualFw = (existing?.foreign_workers || []).filter(e => !fnMap.hasOwnProperty(e.nationality));
  const merged = [...manualFw, ...fnRows];

  if (existing?.id) {
    // Record exists — only patch foreign_workers, never touch lao_male/lao_female
    return await sb.from('records').update({ foreign_workers: merged, updated_at: now.toISOString() }).eq('id', existing.id);
  } else {
    // No record yet — create minimal one (company can fill Lao workers later)
    return await sb.from('records').insert({
      company_id: companyId, year: yr, month: mo,
      lao_male: 0, lao_female: 0,
      foreign_workers: merged,
      updated_at: now.toISOString()
    });
  }
}

// Manual resync triggered from the stats display button
async function resyncFnToRecord() {
  const btn = event.target;
  btn.disabled = true; btn.textContent = '⏳ ກຳລັງ Sync...';
  await syncForeignWorkersToRecords(currentUser.companyId);
  btn.disabled = false; btn.textContent = '🔄 Sync ຂໍ້ມູນ ຕປທ';
  loadMyRecord();
}

