async function loadFnNew() {
  const el = document.getElementById('fnNewTable');
  if (!el) return;
  renderFnNewBulkSection();
  loadFnSummary('fnNewSum');  // auto-load summary for current month
  const { data: rawData, error } = await sb.from('foreign_workers').select('*').order('created_at', { ascending: false });
  const data = await attachCompanyInfo(rawData);
  if (error) { el.innerHTML = `<div class="alert alert-danger">❌ ${error.message}<br><span style="font-size:11px;">ກວດສອບວ່າໄດ້ Run section_c_schema.sql ໃນ Supabase ແລ້ວບໍ່</span></div>`; return; }
  if (!data || data.length === 0) { el.innerHTML = '<div style="text-align:center;color:#aaa;padding:30px;">ຍັງບໍ່ມີຂໍ້ມູນ — ກົດ "+ ລົງທະບຽນໃໝ່" ເພື່ອເລີ່ມ</div>'; return; }
  el.innerHTML = `<table><thead><tr>
    <th>ຮູບ</th><th>ID ທະບຽນ</th><th>ຊື່-ນາມສະກຸນ</th><th>ບໍລິສັດ</th><th>ສັນຊາດ</th><th>ເພດ</th>
    <th>ບັດແຮງງານ</th><th>ໜັງສືເດີນທາງ</th><th>ກຳນົດຢູ່</th><th>ຈັດການ</th>
  </tr></thead><tbody>
    ${data.map(w => {
      const laborStatus = docExpiryStatus(w.labour_card_expiry);
      const passportStatus = docExpiryStatus(w.passport_expiry, 0);
      const thumb = w.photo_path
        ? `<img src="${sb.storage.from('foreign-worker-docs').getPublicUrl(w.photo_path).data.publicUrl}" style="width:36px;height:48px;object-fit:cover;border-radius:4px;border:1px solid #ddd;">`
        : `<div style="width:36px;height:48px;border:1px dashed #ccc;border-radius:4px;display:flex;align-items:center;justify-content:center;color:#ccc;font-size:14px;">👤</div>`;
      return `<tr>
        <td>${thumb}</td>
        <td><b>${esc(w.reg_id)}</b></td>
        <td>${esc(w.prefix || '')} ${esc(w.firstname)} ${esc(w.lastname)}</td>
        <td>${esc(w.companies?.username || '-')}</td>
        <td>${esc(w.nationality || '-')}</td>
        <td>${w.gender || '-'}</td>
        <td><span class="${laborStatus.class}">${laborStatus.text}</span></td>
        <td><span class="${passportStatus.class}">${passportStatus.text}</span></td>
        <td>${w.stay_duration || '-'} ເດືອນ</td>
        <td><button class="btn btn-info btn-sm" onclick="openFnNewModal('${w.id}')">✏️ ແກ້ໄຂ</button></td>
      </tr>`;
    }).join('')}
  </tbody></table>`;
}

async function openFnNewModal(id) {
  document.getElementById('fnId').value = id || '';
  document.getElementById('fnPhotoPreview').innerHTML = `<div style="width:90px;height:120px;border:2px dashed #ccc;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#bbb;font-size:28px;">👤</div>`;
  const fields = ['fnFirstname','fnLastname','fnPositionTxt','fnSalary','fnDob','fnStartDate','fnQuotaNo','fnQuotaDate','fnQuotaFile',
    'fnPassportNo','fnPassportIssue','fnPassportExpiry','fnLaborNo','fnLaborIssue','fnLaborExpiry',
    'fnResidenceNo','fnResidenceIssue','fnResidenceExpiry','fnVisaNo','fnVisaIssue','fnVisaExpiry',
    'fnPhotoFile','fnPassportFile','fnLaborFile','fnResidenceFile','fnVisaFile'];
  fields.forEach(elId => { const e = document.getElementById(elId); if (e) e.value = ''; });
  const sel = document.getElementById('fnPositionSel');
  if (sel) { sel.value = ''; }
  const ptxt = document.getElementById('fnPositionTxt');
  if (ptxt) ptxt.style.display = 'none';
  document.getElementById('fnLaborCount').value = 1;
  document.getElementById('fnPrefix').value = 'MR';
  document.getElementById('fnGender').value = 'ຊາຍ';
  document.getElementById('fnStayDuration').value = 1;
  document.getElementById('fnNationality').value = NATIONALITIES[0];
  document.getElementById('fnNationalityCustom').style.display = 'none';
  document.getElementById('fnNationalityCustom').value = '';

  if (id) {
    const { data: w, error } = await sb.from('foreign_workers').select('*').eq('id', id).single();
    if (error || !w) { alert('ບໍ່ພົບຂໍ້ມູນ'); return; }
    document.getElementById('fnNewModalTitle').textContent = 'ແກ້ໄຂຂໍ້ມູນແຮງງານຕ່າງປະເທດ';
    document.getElementById('fnRegIdDisplay').textContent = 'ID ທະບຽນ: ' + w.reg_id;
    document.getElementById('fnCompany').value = w.company_id;
    document.getElementById('fnPrefix').value = w.prefix || 'MR';
    document.getElementById('fnFirstname').value = w.firstname || '';
    document.getElementById('fnLastname').value = w.lastname || '';
    const natSel = document.getElementById('fnNationality');
    const natVal = w.nationality || NATIONALITIES[0];
    if (NATIONALITIES.includes(natVal)) { natSel.value = natVal; }
    else { natSel.value = 'ອື່ນໆ'; document.getElementById('fnNationalityCustom').value = natVal; }
    toggleNatCustom('fnNationality','fnNationalityCustom');
    if (natSel.value === 'ອື່ນໆ') document.getElementById('fnNationalityCustom').value = natVal;
    document.getElementById('fnGender').value = w.gender || 'ຊາຍ';
    document.getElementById('fnStayDuration').value = w.stay_duration || 1;
    
    document.getElementById('fnSalary').value = w.salary || '';
    document.getElementById('fnDob').value = w.dob || '';
    document.getElementById('fnStartDate').value = w.start_date || '';
    document.getElementById('fnQuotaNo').value = w.quota_no || '';
    document.getElementById('fnQuotaDate').value = w.quota_date || '';
    setPositionField('fnPositionSel', 'fnPositionTxt', w.position || '');
    document.getElementById('fnPassportNo').value = w.passport_no || '';
    document.getElementById('fnPassportIssue').value = w.passport_issue || '';
    document.getElementById('fnPassportExpiry').value = w.passport_expiry || '';
    document.getElementById('fnLaborNo').value = w.labour_card_no || '';
    document.getElementById('fnLaborIssue').value = w.labour_card_issue || '';
    document.getElementById('fnLaborExpiry').value = w.labour_card_expiry || '';
    document.getElementById('fnLaborCount').value = w.labour_card_count || 1;
    document.getElementById('fnResidenceNo').value = w.residence_card_no || '';
    document.getElementById('fnResidenceIssue').value = w.residence_card_issue || '';
    document.getElementById('fnResidenceExpiry').value = w.residence_card_expiry || '';
    document.getElementById('fnVisaNo').value = w.visa_no || '';
    document.getElementById('fnVisaIssue').value = w.visa_issue || '';
    document.getElementById('fnVisaExpiry').value = w.visa_expiry || '';
    if (w.photo_path) {
      const { data: pd } = sb.storage.from('foreign-worker-docs').getPublicUrl(w.photo_path);
      document.getElementById('fnPhotoPreview').innerHTML = `<img src="${pd.publicUrl}" style="width:90px;height:120px;object-fit:cover;border-radius:8px;border:1px solid #ddd;">`;
    }
  } else {
    document.getElementById('fnNewModalTitle').textContent = 'ລົງທະບຽນແຮງງານຕ່າງປະເທດໃໝ່';
    document.getElementById('fnRegIdDisplay').textContent = 'ID ທະບຽນ: ຈະອອກໃຫ້ອັດຕະໂນມັດເມື່ອບັນທຶກ';
    if (activeCompanies[0]) document.getElementById('fnCompany').value = activeCompanies[0].id;
  }
  // Show/hide company field based on role
  if (currentUser.role === 'company') {
    document.getElementById('fnCompany').style.display = 'none';
    const disp = document.getElementById('fnCompanyDisplay');
    if (disp) { disp.style.display = 'block'; disp.textContent = `${currentUser.companyData?.username || ''} — ${currentUser.companyName || ''} (ເຂດ ${currentUser.zone || ''})`; }
    document.getElementById('fnCompany').value = currentUser.companyId;
  } else {
    document.getElementById('fnCompany').style.display = 'block';
    const disp = document.getElementById('fnCompanyDisplay');
    if (disp) disp.style.display = 'none';
  }
  document.getElementById('fnNewModal').classList.add('show');
  attachDateFormatDisplays(document.getElementById('fnNewModal'));
}

async function saveFnWorker() {
  const id = document.getElementById('fnId').value;
  const firstname = document.getElementById('fnFirstname').value.trim();
  const lastname = document.getElementById('fnLastname').value.trim();
  if (!firstname || !lastname) { alert('ກະລຸນາໃສ່ຊື່ ແລະ ນາມສະກຸນ'); return; }
  const saveBtn = document.querySelector('#fnNewModal .btn-primary');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = '⏳ ກຳລັງບັນທຶກ...'; }
  try {

  // Use currentUser.companyId for company role (the hidden select may have wrong value from activeCompanies[0])
  const companyId = (currentUser.role === 'company') ? currentUser.companyId : document.getElementById('fnCompany').value;
  if (!companyId) { alert('ຜິດພາດ: ບໍ່ພົບ company ID — ກະລຸນາລອງ login ໃໝ່'); return; }

  let regId, regYear;
  if (id) {
    const { data: existing } = await sb.from('foreign_workers').select('reg_id,reg_year').eq('id', id).single();
    regId = existing.reg_id; regYear = existing.reg_year;
  } else {
    const companyCode = await getCompanyCode(companyId);
    const gen = await generateRegId('FN', 'foreign_workers', companyId, companyCode);
    regId = gen.regId; regYear = gen.regYear;
  }

  const payload = {
    company_id: companyId, reg_id: regId, reg_year: regYear,
    prefix: document.getElementById('fnPrefix').value,
    firstname, lastname,
    nationality: getNatValue('fnNationality','fnNationalityCustom'),
    gender: document.getElementById('fnGender').value,
    position: getPositionValue('fnPositionSel','fnPositionTxt'),
    salary: parseFloat(document.getElementById('fnSalary').value) || null,
    dob: document.getElementById('fnDob').value || null,
    start_date: document.getElementById('fnStartDate').value || null,
    quota_no: document.getElementById('fnQuotaNo').value,
    quota_date: document.getElementById('fnQuotaDate').value || null,
    passport_no: document.getElementById('fnPassportNo').value,
    passport_issue: document.getElementById('fnPassportIssue').value || null,
    passport_expiry: document.getElementById('fnPassportExpiry').value || null,
    labour_card_no: document.getElementById('fnLaborNo').value,
    labour_card_issue: document.getElementById('fnLaborIssue').value || null,
    labour_card_expiry: document.getElementById('fnLaborExpiry').value || null,
    labour_card_count: parseInt(document.getElementById('fnLaborCount').value) || 1,
    residence_card_no: document.getElementById('fnResidenceNo').value,
    residence_card_issue: document.getElementById('fnResidenceIssue').value || null,
    residence_card_expiry: document.getElementById('fnResidenceExpiry').value || null,
    visa_no: document.getElementById('fnVisaNo').value,
    visa_issue: document.getElementById('fnVisaIssue').value || null,
    visa_expiry: document.getElementById('fnVisaExpiry').value || null,
    stay_duration: parseInt(document.getElementById('fnStayDuration').value) || null,
    updated_at: new Date().toISOString()
  };

  const photoFile = document.getElementById('fnPhotoFile').files[0];
  if (photoFile) {
    const up = await uploadFwFile(photoFile, regId, 'photo');
    if (up) payload.photo_path = up.path;
  }
  let docFiles = [];
  if (id) {
    const { data: existing } = await sb.from('foreign_workers').select('doc_files').eq('id', id).single();
    docFiles = existing?.doc_files || [];
  }
  const docDefs = [['fnQuotaFile','quota'], ['fnPassportFile','passport'], ['fnLaborFile','labour_card'], ['fnResidenceFile','residence_card'], ['fnVisaFile','visa']];
  for (const [elId, tag] of docDefs) {
    const f = document.getElementById(elId).files[0];
    if (f) {
      const up = await uploadFwFile(f, regId, tag);
      if (up) { docFiles = docFiles.filter(d => d.type !== tag); docFiles.push(up); }
    }
  }
  payload.doc_files = docFiles;

  let error, insertedRegId = regId;
  if (id) { ({ error } = await sb.from('foreign_workers').update(payload).eq('id', id)); if (!error) await logAudit('update', 'foreign_workers', id, { regId }); }
  else {
    // ລອງບັນທຶກ, ຖ້າເລກ ID ຊ້ຳກັນ (race condition) ໃຫ້ຄິດເລກໃໝ່ ແລະ ລອງອີກ
    let attempt = 0;
    while (attempt < 5) {
      ({ error } = await sb.from('foreign_workers').insert(payload));
      if (!error) break;
      const isDupRegId = String(error.message||'').includes('foreign_workers_reg_id_key') || String(error.code) === '23505';
      if (!isDupRegId) break;
      attempt++;
      const companyCode = await getCompanyCode(companyId);
      const gen2 = await generateRegId('FN', 'foreign_workers', companyId, companyCode);
      payload.reg_id = gen2.regId; payload.reg_year = gen2.regYear;
      insertedRegId = gen2.regId;
    }
    if (!error) await logAudit('create', 'foreign_workers', insertedRegId, {});
  }
  regId = insertedRegId;
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }

  const { error: syncErr } = await syncForeignWorkersToRecords(companyId) || {};
  if (syncErr) {
    console.error('Sync error:', syncErr);
    alert(`⚠️ ບັນທຶກສຳເລັດ (ID: ${regId}) — ແຕ່ Sync ສະຖິຕິ ຕປທ ມີບັນຫາ: ${syncErr.message}\nກົດ "🔄 Sync" ໃນໜ້າ "ຂໍ້ມູນ ແລະ ສະຖິຕິ" ດ້ວຍຕົນເອງ`);
  } else {
    alert(`✅ ບັນທຶກສຳເລັດ — ID ທະບຽນ: ${regId}\nຂໍ້ມູນ ຕປທ ໄດ້ Sync ໄປໃນ "ອັບເດດສະຖິຕິ" ທັນທີ`);
  }
  closeModal('fnNewModal');
  if (document.getElementById('companyFnTable')) {
    await loadFwNewWorkers();
  } else {
    loadFnNew();
  }
  } catch(e) { alert('ເກີດຂໍ້ຜິດພາດ: ' + e.message); }
  finally { if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = '💾 ບັນທຶກຂໍ້ມູນ'; } }
}

// ---- C.1.2 — Document Renewal (FNR-) ----
let _fnAllWorkersCache = [];

function fnrModalHtml() {
  return `
  <div class="modal-overlay" id="fnrModal">
    <div class="modal" style="max-width:920px;">
      <div class="modal-header">
        <span class="modal-title">🔄 ຕໍ່ອາຍຸເອກະສານແຮງງານຕ່າງປະເທດ</span>
        <button class="close-btn" onclick="closeModal('fnrModal')">✕</button>
      </div>
      <div class="modal-body">
        <div id="fnrModalBody"></div>
      </div>
    </div>
  </div>`;
}

function pageFnRenew() {
  return `
  <div class="card">
    <div class="card-header" style="background:linear-gradient(135deg,#0f2942,#1a5276);border-radius:12px 12px 0 0;border-bottom:none;">
      <span class="card-title" style="color:#fff;">🔄 ລົງທະບຽນຕໍ່ອາຍຸເອກະສານແຮງງານ ຕປທ<br><span style="font-size:11px;color:#cfe0ec;font-weight:400;">Foreign Worker Document Renewal (FNR)</span></span>
    </div>
    <div class="card-body">
      <div class="form-group" style="max-width:520px;position:relative;">
        <label>ຄົ້ນຫາແຮງງານທີ່ຈະຕໍ່ອາຍຸ (ຊື່ / ID ທະບຽນ / ເລກໜັງສືເດີນທາງ)</label>
        <input type="text" id="fnrSearchInput" placeholder="ພິມຄົ້ນຫາ..." oninput="doFnrSearch()" autocomplete="off">
        <div id="fnrSearchList" class="autocomplete-list" style="display:none;position:absolute;z-index:50;background:#fff;width:100%;border:1px solid #ddd;border-radius:8px;max-height:240px;overflow-y:auto;"></div>
      </div>
      <div class="section-title mt-4">ປະຫວັດການຕໍ່ອາຍຸທີ່ຜ່ານມາ</div>
      <div class="table-wrap" id="fnrHistoryTable"><div style="text-align:center;color:#aaa;padding:20px;">ກຳລັງໂຫຼດ...</div></div>
    </div>
  </div>
  ${fnSummaryCardHtml('fnrSum', null)}
  ${fnrModalHtml()}`;
}

async function loadFnRenewSearch() {
  let q = sb.from('foreign_workers').select('*').order('firstname');
  if (currentUser.role === 'company') q = q.eq('company_id', currentUser.companyId);
  const { data: rawData, error } = await q;
  if (error) { document.getElementById('fnrHistoryTable').innerHTML = `<div class="alert alert-danger">❌ ${error.message}</div>`; return; }
  _fnAllWorkersCache = await attachCompanyInfo(rawData || []);
  loadFnrHistory();
  loadFnSummary('fnrSum');  // auto-load summary for current month
}

function doFnrSearch() {
  const q = document.getElementById('fnrSearchInput').value.trim().toLowerCase();
  const list = document.getElementById('fnrSearchList');
  if (!q) { list.style.display = 'none'; return; }
  const matches = _fnAllWorkersCache.filter(w =>
    (w.firstname || '').toLowerCase().includes(q) ||
    (w.lastname || '').toLowerCase().includes(q) ||
    (w.reg_id || '').toLowerCase().includes(q) ||
    (w.passport_no || '').toLowerCase().includes(q)
  );
  if (matches.length === 0) { list.innerHTML = '<div style="padding:10px;color:#aaa;">ບໍ່ພົບຂໍ້ມູນ</div>'; list.style.display = 'block'; return; }
  list.style.display = 'block';
  list.innerHTML = matches.slice(0, 15).map(w => `
    <div class="autocomplete-item" onclick="selectFnForRenewal('${w.id}')">
      <b>${esc(w.reg_id)}</b> — ${esc(w.prefix || '')} ${esc(w.firstname)} ${esc(w.lastname)} (${esc(w.companies?.username || '-')})
    </div>`).join('');
}

async function selectFnForRenewal(workerId) {
  document.getElementById('fnrSearchList').style.display = 'none';
  const w = _fnAllWorkersCache.find(x => x.id === workerId);
  if (!w) return;
  document.getElementById('fnrSearchInput').value = `${w.reg_id} — ${w.firstname} ${w.lastname}`;

  const nextCount = Math.min(Math.max((w.labour_card_count || 1) + 1, 2), 5);
  const countOptions = [2,3,4,5].map(n => `<option value="${n}" ${n===nextCount?'selected':''}>ຄັ້ງທີ ${n}</option>`).join('');

  const { count: priorRenewals } = await sb.from('foreign_worker_renewals').select('id', { count: 'exact', head: true }).eq('worker_id', workerId);
  const upcomingRenewalNo = (priorRenewals || 0) + 1;

  document.getElementById('fnrModalBody').innerHTML = `
    <div class="alert" style="background:#fff3cd;border-left:4px solid #f39c12;border-radius:8px;padding:12px 16px;margin-top:16px;">
      <div style="font-weight:600;color:#784212;">🔁 ກຳລັງຕໍ່ອາຍຸ: <b>${esc(w.firstname)} ${esc(w.lastname)}</b></div>
      <div style="font-size:12px;margin-top:4px;color:#555;">
        ID ທະບຽນ: <b style="color:#27ae60;">${esc(w.reg_id)}</b> (ຄົງທີ່ ບໍ່ປ່ຽນ) — ນີ້ແມ່ນການຕໍ່ອາຍຸ <b style="color:#e67e22;">ຄັ້ງທີ ${upcomingRenewalNo}</b>
      </div>
    </div>
    <input type="hidden" id="fnrWorkerId" value="${w.id}">
    <input type="hidden" id="fnrCompanyId" value="${w.company_id}">

    <div class="form-row">
      <div class="form-group"><label>ຊື່ບໍລິສັດ</label><input type="text" value="${esc(w.companies?.username || '')} — ${esc(w.companies?.name_lao || '')}" readonly style="background:#f5f5f5;"></div>
      <div class="form-group"><label>ຮູບຖ່າຍ 3x4 (ກົດເລືອກໄຟລ໌ໃໝ່ ຖ້າຕ້ອງການປ່ຽນ)</label>
        ${fwPhotoBoxHtml('fnrPhotoFile', 'fnrPhotoPreview', w.photo_path ? sb.storage.from('foreign-worker-docs').getPublicUrl(w.photo_path).data.publicUrl : null)}
      </div>
    </div>

    <div class="form-row">
      <div class="form-group" style="max-width:120px;"><label>ຄຳນຳໜ້າ</label><select id="fnrPrefix" style="${fwSelectStyle()}" onchange="autoFillGender('fnrPrefix','fnrGender')">${fnPrefixOptions()}</select></div>
      <div class="form-group"><label>ຊື່</label><input type="text" id="fnrFirstname" value="${esc(w.firstname || '')}"></div>
      <div class="form-group"><label>ນາມສະກຸນ</label><input type="text" id="fnrLastname" value="${esc(w.lastname || '')}"></div>
    </div>

    <div class="form-row">
      <div class="form-group"><label>ສັນຊາດ</label><select id="fnrNationality" style="${fwSelectStyle()}" onchange="toggleNatCustom('fnrNationality','fnrNationalityCustom')">${fwNatOptions()}</select>
        <input type="text" id="fnrNationalityCustom" placeholder="ພິມລະບຸສັນຊາດ..." style="${fwSelectStyle()};display:none;margin-top:6px;"></div>
      <div class="form-group"><label>ເພດ</label><select id="fnrGender" style="${fwSelectStyle()}">${fwGenderOptions()}</select></div>
      <div class="form-group"><label>ກຳນົດຢູ່ລາວ</label><select id="fnrStayDuration" style="${fwSelectStyle()}">${fwStayOptions()}</select></div>
    </div>

    <div class="form-row">
      <div class="form-group"><label>ຕຳແໜ່ງງານ</label>
        ${positionFieldHtml('fnrPositionSel','fnrPositionTxt', w.position||'')}
      </div>
      <div class="form-group"><label>ເງິນເດືອນ (ກີບ)</label><input type="number" id="fnrSalary" value="${w.salary || ''}"></div>
      <div class="form-group"><label>ວັນເດືອນປີເກີດ</label><input type="date" id="fnrDob" value="${w.dob || ''}"></div>
    </div>

    <div class="section-title">ໃບອະນຸມັດໂຄຕາປະຈຳປີ</div>
    <div class="form-row">
      <div class="form-group"><label>ເລກທີ</label><input type="text" id="fnrQuotaNo" value="${w.quota_no || ''}"></div>
      <div class="form-group"><label>ວັນທີ</label><input type="date" id="fnrQuotaDate" value="${w.quota_date || ''}"></div>
      <div class="form-group"><label>ສຳເນົາ (PDF/ຮູບ)</label><input type="file" id="fnrQuotaFile" accept=".pdf,image/*"></div>
    </div>

    <div class="section-title">ໜັງສືເດີນທາງ</div>
    <div class="form-row">
      <div class="form-group"><label>ເລກທີ</label><input type="text" id="fnrPassportNo" value="${esc(w.passport_no || '')}"></div>
      <div class="form-group"><label>ວັນທີອອກ</label><input type="date" id="fnrPassportIssue" value="${w.passport_issue || ''}"></div>
      <div class="form-group"><label>ວັນທີໝົດກຳນົດ</label><input type="date" id="fnrPassportExpiry" value="${w.passport_expiry || ''}"></div>
      <div class="form-group"><label>ສຳເນົາ (PDF/ຮູບ)</label><input type="file" id="fnrPassportFile" accept=".pdf,image/*"></div>
    </div>

    <div class="section-title">ບັດແຮງງານ (ຕໍ່ອາຍຸ)</div>
    <div class="form-row">
      <div class="form-group"><label>ເລກທີ</label><input type="text" id="fnrLaborNo" value="${esc(w.labour_card_no || '')}"></div>
      <div class="form-group"><label>ວັນທີອອກ</label><input type="date" id="fnrLaborIssue"></div>
      <div class="form-group"><label>ວັນທີໝົດກຳນົດ</label><input type="date" id="fnrLaborExpiry"></div>
      <div class="form-group" style="max-width:140px;"><label>ອອກຄັ້ງທີ</label><select id="fnrLaborCount" style="${fwSelectStyle()}">${countOptions}</select></div>
      <div class="form-group"><label>ສຳເນົາ (PDF/ຮູບ)</label><input type="file" id="fnrLaborFile" accept=".pdf,image/*"></div>
    </div>

    <div class="section-title">ບັດພັກເຊົາ</div>
    <div class="form-row">
      <div class="form-group"><label>ເລກທີ</label><input type="text" id="fnrResidenceNo" value="${esc(w.residence_card_no || '')}"></div>
      <div class="form-group"><label>ວັນທີອອກ</label><input type="date" id="fnrResidenceIssue"></div>
      <div class="form-group"><label>ວັນທີໝົດກຳນົດ</label><input type="date" id="fnrResidenceExpiry"></div>
      <div class="form-group"><label>ສຳເນົາ (PDF/ຮູບ)</label><input type="file" id="fnrResidenceFile" accept=".pdf,image/*"></div>
    </div>

    <div class="section-title">ວີຊ່າ</div>
    <div class="form-row">
      <div class="form-group"><label>ເລກທີ</label><input type="text" id="fnrVisaNo" value="${w.visa_no || ''}"></div>
      <div class="form-group"><label>ວັນທີອອກ</label><input type="date" id="fnrVisaIssue"></div>
      <div class="form-group"><label>ວັນທີໝົດກຳນົດ</label><input type="date" id="fnrVisaExpiry"></div>
      <div class="form-group"><label>ສຳເນົາວີຊ່າເຂົ້າ-ອອກຫຼາຍເທື່ອ</label><input type="file" id="fnrVisaFile" accept=".pdf,image/*"></div>
    </div>

    <div class="mt-4" style="text-align:right;">
      <button class="btn btn-secondary btn-sm" onclick="closeModal('fnrModal')">ຍົກເລີກ</button>
      <button class="btn btn-primary" onclick="saveFnRenewal()">💾 ບັນທຶກຂໍ້ມູນ</button>
    </div>
  `;
  document.getElementById('fnrModal').classList.add('show');
  document.getElementById('fnrPrefix').value = w.prefix || 'MR';
  document.getElementById('fnrGender').value = w.gender || 'ຊາຍ';
  const fnrNatSel = document.getElementById('fnrNationality');
  const fnrNatVal = w.nationality || NATIONALITIES[0];
  if (NATIONALITIES.includes(fnrNatVal)) { fnrNatSel.value = fnrNatVal; }
  else { fnrNatSel.value = 'ອື່ນໆ'; }
  toggleNatCustom('fnrNationality','fnrNationalityCustom');
  if (fnrNatSel.value === 'ອື່ນໆ') document.getElementById('fnrNationalityCustom').value = fnrNatVal;
  document.getElementById('fnrStayDuration').value = w.stay_duration || 1;
  attachDateFormatDisplays(document.getElementById('fnrModalBody'));
}

async function saveFnRenewal() {
  const workerId = document.getElementById('fnrWorkerId') ? document.getElementById('fnrWorkerId').value : '';
  if (!workerId) { alert('ກະລຸນາຄົ້ນຫາ ແລະ ເລືອກແຮງງານກ່ອນ'); return; }
  const companyId = (currentUser.role === 'company') ? currentUser.companyId : (document.getElementById('fnrCompanyId') ? document.getElementById('fnrCompanyId').value : '');
  const saveBtn = document.querySelector('#fnrModalBody .btn-primary');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = '⏳ ກຳລັງບັນທຶກ...'; }
  try {

  const companyCode = await getCompanyCode(companyId);
  const gen = await generateRegId('FNR', 'foreign_worker_renewals', companyId, companyCode);

  // ນັບຄັ້ງທີຕໍ່ອາຍຸ — ຄັ້ງທີ 1 ຄືການຕໍ່ອາຍຸຄັ້ງທຳອິດຂອງຄົນນີ້ (ນັບຈາກ worker_id)
  const { count: priorRenewals } = await sb.from('foreign_worker_renewals').select('id', { count: 'exact', head: true }).eq('worker_id', workerId);
  const renewalNo = (priorRenewals || 0) + 1;

  // Core fields that exist in foreign_worker_renewals
  const renewalPayload = {
    worker_id: workerId,
    company_id: companyId,
    reg_id: gen.regId,
    reg_year: gen.regYear,
    renewal_no: renewalNo,
    prefix: document.getElementById('fnrPrefix').value,
    firstname: document.getElementById('fnrFirstname').value.trim(),
    lastname: document.getElementById('fnrLastname').value.trim(),
    nationality: getNatValue('fnrNationality','fnrNationalityCustom'),
    gender: document.getElementById('fnrGender').value,
    position: getPositionValue('fnrPositionSel','fnrPositionTxt'),
    salary: parseFloat(document.getElementById('fnrSalary').value) || null,
    dob: document.getElementById('fnrDob').value || null,
    quota_no: document.getElementById('fnrQuotaNo') ? document.getElementById('fnrQuotaNo').value : '',
    quota_date: document.getElementById('fnrQuotaDate') ? document.getElementById('fnrQuotaDate').value || null : null,
    passport_no: document.getElementById('fnrPassportNo').value,
    passport_issue: document.getElementById('fnrPassportIssue').value || null,
    passport_expiry: document.getElementById('fnrPassportExpiry').value || null,
    labour_card_no: document.getElementById('fnrLaborNo').value,
    labour_card_issue: document.getElementById('fnrLaborIssue').value || null,
    labour_card_expiry: document.getElementById('fnrLaborExpiry').value || null,
    residence_card_no: document.getElementById('fnrResidenceNo').value,
    residence_card_issue: document.getElementById('fnrResidenceIssue').value || null,
    residence_card_expiry: document.getElementById('fnrResidenceExpiry').value || null,
    visa_no: document.getElementById('fnrVisaNo').value,
    visa_issue: document.getElementById('fnrVisaIssue').value || null,
    visa_expiry: document.getElementById('fnrVisaExpiry').value || null,
    stay_duration: parseInt(document.getElementById('fnrStayDuration').value) || null
  };

  const photoFile = document.getElementById('fnrPhotoFile').files[0];
  if (photoFile) { const up = await uploadFwFile(photoFile, gen.regId, 'photo'); if (up) renewalPayload.photo_path = up.path; }
  let docFiles = [];
  const docDefs = [['fnrQuotaFile','quota'], ['fnrPassportFile','passport'], ['fnrLaborFile','labour_card'], ['fnrResidenceFile','residence_card'], ['fnrVisaFile','visa']];
  for (const [elId, tag] of docDefs) {
    const f = document.getElementById(elId).files[0];
    if (f) { const up = await uploadFwFile(f, gen.regId, tag); if (up) docFiles.push(up); }
  }
  renewalPayload.doc_files = docFiles;

  const { error: insErr } = await sb.from('foreign_worker_renewals').insert(renewalPayload);
  if (insErr) {
    const isDupRegId = String(insErr.message||'').includes('reg_id') || String(insErr.code) === '23505';
    if (isDupRegId) {
      const gen2 = await generateRegId('FNR', 'foreign_worker_renewals', companyId, companyCode);
      renewalPayload.reg_id = gen2.regId; renewalPayload.reg_year = gen2.regYear;
      const { error: insErr2 } = await sb.from('foreign_worker_renewals').insert(renewalPayload);
      if (insErr2) { alert('ຜິດພາດບັນທຶກ FNR: ' + insErr2.message); return; }
      gen.regId = gen2.regId;
    } else { alert('ຜິດພາດບັນທຶກ FNR: ' + insErr.message); return; }
  }

  // ບັນທຶກ Audit Log — ໃຫ້ Admin ເຫັນ badge ແຈ້ງເຕືອນ (ຈຸດທີ່ເຄີຍຂາດຫາຍໄປ)
  await logAudit('create', 'foreign_worker_renewals', gen.regId, {
    action_detail: `ຕໍ່ອາຍຸເອກະສານແຮງງານຕ່າງປະເທດ: ${renewalPayload.firstname||''} ${renewalPayload.lastname||''}`,
    company: currentUser.companyData?.name_lao || currentUser.companyName || '',
  });

  // ອັບເດດຂໍ້ມູນເອກະສານຫຼ້າສຸດຂອງ foreign_workers — ແຕ່ "ບໍ່ປ່ຽນ reg_id ຫຼັກ" ອີກຕໍ່ໄປ
  // (ID ຫຼັກ FN-xxx ຕ້ອງຄົງທີ່ຕະຫຼອດຊີວິດການເຮັດວຽກ — ຄັ້ງທີຕໍ່ອາຍຸເກັບແຍກໄວ້ໃນ renewal_no ຂອງແຕ່ລະປະຫວັດແທນ)
  const masterUpdate = {
    prefix: renewalPayload.prefix,
    firstname: renewalPayload.firstname,
    lastname: renewalPayload.lastname,
    nationality: renewalPayload.nationality,
    gender: renewalPayload.gender,
    position: renewalPayload.position,
    salary: renewalPayload.salary,
    dob: renewalPayload.dob,
    passport_no: renewalPayload.passport_no,
    passport_issue: renewalPayload.passport_issue,
    passport_expiry: renewalPayload.passport_expiry,
    labour_card_no: renewalPayload.labour_card_no,
    labour_card_issue: renewalPayload.labour_card_issue,
    labour_card_expiry: renewalPayload.labour_card_expiry,
    labour_card_count: parseInt(document.getElementById('fnrLaborCount').value) || 2,
    stay_duration: renewalPayload.stay_duration,
    doc_files: docFiles,
    updated_at: new Date().toISOString()
  };
  if (renewalPayload.photo_path) masterUpdate.photo_path = renewalPayload.photo_path;

  const { error: updErr } = await sb.from('foreign_workers').update(masterUpdate).eq('id', workerId);
  if (updErr) {
    alert(`⚠️ ບັນທຶກ FNR ສຳເລັດ (${gen.regId}) ແຕ່ update ໃນ FW ລົ້ມເຫລວ: ${updErr.message}`);
  }

  const { error: syncErr2 } = await syncForeignWorkersToRecords(companyId) || {};
  if (syncErr2) console.error('FNR Sync error:', syncErr2.message);

  // find old FN reg_id for display (ຄົງທີ່ — ບໍ່ປ່ຽນອີກຕໍ່ໄປ)
  const oldWorker = (_fnAllWorkersCache||[]).find(x => x.id === workerId);
  const oldId = oldWorker?.reg_id || 'FN-???';
  alert(`✅ ບັນທຶກການຕໍ່ອາຍຸສຳເລັດ\n\n🆔 ID ທະບຽນ: ${oldId} (ຄົງທີ່)\n🔄 ນີ້ແມ່ນການຕໍ່ອາຍຸຄັ້ງທີ ${renewalNo}`);

  closeModal('fnrModal');
  document.getElementById('fnrModalBody').innerHTML = '';
  document.getElementById('fnrSearchInput').value = '';
  const latestEl2 = document.getElementById('latestRecord');
  if (latestEl2) loadMyRecord();
  loadFnRenewSearch();
  } catch(e) { alert('ເກີດຂໍ້ຜິດພາດ: ' + e.message); }
  finally { const b2 = document.querySelector('#fnrModalBody .btn-primary'); if (b2) { b2.disabled = false; b2.textContent = '💾 ບັນທຶກຂໍ້ມູນ'; } }
}

async function loadFnrHistory() {
  const el = document.getElementById('fnrHistoryTable');
  if (!el) return;
  let q = sb.from('foreign_worker_renewals').select('*').order('created_at', { ascending: false }).limit(100);
  if (currentUser.role === 'company') q = q.eq('company_id', currentUser.companyId);
  const { data: rawData, error } = await q;
  if (error) { el.innerHTML = `<div class="alert alert-danger">❌ ${error.message}</div>`; return; }
  const data = await attachCompanyInfo(rawData);
  if (!data || data.length === 0) { el.innerHTML = '<div style="text-align:center;color:#aaa;padding:20px;">ຍັງບໍ່ມີປະຫວັດການຕໍ່ອາຍຸ</div>'; return; }
  el.innerHTML = `<table><thead><tr>
    <th>ID ທະບຽນ (ຄົງທີ່)</th><th>ຊື່-ນາມສະກຸນ</th><th>ບໍລິສັດ</th><th>ຕໍ່ອາຍຸຄັ້ງທີ</th><th>ວັນທີຕໍ່ອາຍຸ</th><th>ຈັດການ</th>
  </tr></thead><tbody>
    ${data.map(r => `<tr>
      <td><b>${esc(r.reg_id)}</b></td>
      <td>${esc(r.prefix || '')} ${esc(r.firstname)} ${esc(r.lastname)}</td>
      <td>${esc(r.companies?.username || '-')}</td>
      <td style="text-align:center;"><span style="background:#eaf4ff;color:#1565c0;padding:2px 10px;border-radius:12px;font-weight:600;">${r.renewal_no || '-'}</span></td>
      <td>${laoDate(r.created_at)}</td>
      <td><button class="btn btn-info btn-sm" onclick="printFnRenewal('${r.id}')">🖨️ ພິມ</button></td>
    </tr>`).join('')}
  </tbody></table>`;
}

async function printFnRenewal(renewalId) {
  const { data: rRaw, error } = await sb.from('foreign_worker_renewals').select('*').eq('id', renewalId).single();
  const r = await attachCompanyInfoSingle(rRaw);
  if (error || !r) { alert('ບໍ່ພົບຂໍ້ມູນ'); return; }
  if (r.printed_at) {
    const prev = laoDate(r.printed_at);
    if (!confirm(`ໃບນີ້ (${r.reg_id}) ເຄີຍຖືກພິມໄປແລ້ວເມື່ອ ${prev}\n\nຕ້ອງການພິມຄືນອີກບໍ?`)) return;
  }
  const printWin = window.open('', '_blank');
  printWin.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
    body{font-family:'Phetsarath OT','PhetsarathOT','Noto Sans Lao',sans-serif;font-size:13px;margin:15mm;}
    .header{text-align:center;margin-bottom:14px;}
    table{width:100%;border-collapse:collapse;margin-top:10px;}
    td{padding:6px 8px;border:1px solid #ccc;}
    td.label{background:#f5f5f5;font-weight:600;width:35%;}
    @page{size:A4;margin:12mm;}
  </style></head><body>
    <div class="header">
      <p style="margin:0;font-weight:600;">ສາທາລະນະລັດ ປະຊາທິປະໄຕ ປະຊາຊົນລາວ</p>
      <p style="margin:2px 0;">ສັນຕິພາບ ເອກະລາດ ປະຊາທິປະໄຕ ເອກະພາບ ວັດທະນະຖາວອນ</p>
      <h3 style="margin:8px 0;">ໃບຕໍ່ອາຍຸເອກະສານແຮງງານຕ່າງປະເທດ — ${esc(r.reg_id)}</h3>
    </div>
    <table>
      <tr><td class="label">ບໍລິສັດ</td><td>${esc(r.companies?.username || '')} — ${esc(r.companies?.name_lao || '')} (ເຂດ ${r.companies?.zone || ''})</td></tr>
      <tr><td class="label">ຊື່ ແລະ ນາມສະກຸນ</td><td>${esc(r.prefix || '')} ${esc(r.firstname)} ${esc(r.lastname)}</td></tr>
      <tr><td class="label">ສັນຊາດ / ເພດ</td><td>${esc(r.nationality || '-')} / ${r.gender || '-'}</td></tr>
      <tr><td class="label">ຕຳແໜ່ງງານ</td><td>${esc(r.position || '-')}</td></tr>
      <tr><td class="label">ໜັງສືເດີນທາງ</td><td>${esc(r.passport_no || '-')} (ອອກ ${r.passport_issue || '-'} ໝົດ ${r.passport_expiry || '-'})</td></tr>
      <tr><td class="label">ບັດແຮງງານ (ຄັ້ງທີ ${r.labour_card_count || ''})</td><td>${esc(r.labour_card_no || '-')} (ອອກ ${r.labour_card_issue || '-'} ໝົດ ${r.labour_card_expiry || '-'})</td></tr>
      <tr><td class="label">ບັດພັກເຊົາ</td><td>${esc(r.residence_card_no || '-')} (ອອກ ${r.residence_card_issue || '-'} ໝົດ ${r.residence_card_expiry || '-'})</td></tr>
      <tr><td class="label">ວີຊ່າ</td><td>${r.visa_no || '-'} (ອອກ ${r.visa_issue || '-'} ໝົດ ${r.visa_expiry || '-'})</td></tr>
      <tr><td class="label">ກຳນົດຢູ່ລາວ</td><td>${r.stay_duration || '-'} ເດືອນ</td></tr>
    </table>
    <div style="margin-top:40px;text-align:center;"></div>
  </body></html>`);
  printWin.document.close();
  printWin.print();
  await sb.from('foreign_worker_renewals').update({ printed_at: new Date().toISOString() }).eq('id', renewalId);
}

