function downloadFnrBulkTemplate() {
  if (!window.XLSX) { alert('ກຳລັງໂຫຼດ XLSX...'); return; }
  const headers = [
    'ID ທະບຽນ ຫຼື ເລກ Passport (ຄົ້ນຫາຄົນ)', 'ຊື່ (ອ້າງອີງ)', 'ນາມສະກຸນ (ອ້າງອີງ)',
    'ເລກ Passport', 'ວັນທີອອກ Passport DD/MM/YYYY', 'ວັນໝົດ Passport DD/MM/YYYY',
    'ເລກ ບັດແຮງງານ', 'ວັນທີອອກ ບັດແຮງງານ DD/MM/YYYY', 'ວັນໝົດ ບັດແຮງງານ DD/MM/YYYY',
    'ເລກ ບັດທີ່ຢູ່', 'ວັນທີອອກ ບັດທີ່ຢູ່ DD/MM/YYYY', 'ວັນໝົດ ບັດທີ່ຢູ່ DD/MM/YYYY',
    'ເລກ Visa', 'ວັນທີອອກ Visa DD/MM/YYYY', 'ວັນໝົດ Visa DD/MM/YYYY',
    'ກຳນົດຢູ່ (ເດືອນ)'
  ];
  const example = [
    'P123456789', 'CHEN', 'WEI',
    'P123456789', '01/01/2024', '01/01/2029',
    'LC002', '01/08/2026', '01/08/2028', '12',
    'RC002', '01/08/2026', '01/08/2028',
    'V002', '01/08/2026', '01/08/2028'
  ];
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.aoa_to_sheet([headers, example]);
  ws['!cols'] = headers.map(() => ({ wch: 24 }));
  forceExcelTextColumns(ws, [3,4,5,7,8,9,10,11,12,13,14], 1);
  XLSX.utils.book_append_sheet(wb, ws, 'FNR_Bulk');
  XLSX.writeFile(wb, 'FNR_Bulk_Template.xlsx');
}

async function handleFnrBulkExcel(file) {
  if (!file) return;
  function excelDate(v) {
    if (!v) return null;
    const s = String(v).trim();
    const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (m) return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
    return null;
  }
  try {
    const buf = await file.arrayBuffer();
    const wb = XLSX.read(buf, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, defval: '' });

    const companyId = currentUser.companyId;
    const { data: allWorkers } = await sb.from('foreign_workers').select('*').eq('company_id', companyId);
    const byKey = {};
    (allWorkers || []).forEach(w => {
      if (w.reg_id) byKey[String(w.reg_id).trim().toLowerCase()] = w;
      if (w.passport_no) byKey[String(w.passport_no).trim().toLowerCase()] = w;
    });

    const inserts = [];
    const notFound = [];
    // ນັບຄັ້ງທີຕໍ່ອາຍຸເດີມຂອງແຕ່ລະຄົນ ຄາວດຽວກ່ອນ loop (ຄືກັນກັບ reg_id — ບໍ່ຖາມຖານຂໍ້ມູນຊ້ຳໆໃນ loop)
    const workerIdsInBatch = Object.values(byKey).map(w => w.id);
    const { data: existingRenewals } = workerIdsInBatch.length
      ? await sb.from('foreign_worker_renewals').select('worker_id').in('worker_id', [...new Set(workerIdsInBatch)])
      : { data: [] };
    const renewalCountMap = {};
    (existingRenewals || []).forEach(r => { renewalCountMap[r.worker_id] = (renewalCountMap[r.worker_id] || 0) + 1; });

    // ດຶງ reg_id ທີ່ໃຊ້ໄປແລ້ວທັງໝົດຂອງປີນີ້ ຄາວດຽວ (ບໍ່ໃຊ້ generateRegId() ຊ້ຳໆໃນ loop
    // ຍ້ອນຈະໄດ້ ID ຊ້ຳກັນ — ຂໍ້ມູນທັງໝົດຍັງບໍ່ຖືກ insert ຈິງລະຫວ່າງແຕ່ລະຮອບຂອງ loop)
    const regYear = new Date().getFullYear();
    const regMonth = String(new Date().getMonth() + 1).padStart(2, '0');
    const regYY = String(regYear).slice(-2);
    const companyCode = await getCompanyCode(companyId);
    const idPrefix1 = `FNR${companyCode}`;
    const { data: existingRegs } = await sb.from('foreign_worker_renewals').select('reg_id').eq('company_id', companyId).like('reg_id', `${idPrefix1}%`);
    const usedIds = new Set((existingRegs || []).map(r => r.reg_id));
    let maxSeq1 = 0;
    (existingRegs || []).forEach(r => {
      const n = parseInt(String(r.reg_id || '').slice(-3), 10);
      if (!isNaN(n) && n > maxSeq1) maxSeq1 = n;
    });
    let seq = maxSeq1 + 1;
    function nextRegId() {
      let regId;
      do { regId = `${idPrefix1}${regMonth}${regYY}${String(seq).padStart(3,'0')}`; seq++; } while (usedIds.has(regId));
      usedIds.add(regId);
      return regId;
    }

    for (let i = 1; i < rows.length; i++) {
      const r = rows[i];
      if (!r || !r[0]) continue;
      const key = String(r[0]).trim().toLowerCase();
      const w = byKey[key];
      if (!w) { notFound.push(`ແຖວ ${i+1}: "${r[0]}"`); continue; }
      renewalCountMap[w.id] = (renewalCountMap[w.id] || 0) + 1;
      inserts.push({
        worker_id: w.id, company_id: companyId, reg_id: nextRegId(), reg_year: regYear,
        renewal_no: renewalCountMap[w.id],
        prefix: w.prefix || 'MR', firstname: w.firstname, lastname: w.lastname,
        nationality: w.nationality, gender: w.gender, position: w.position,
        photo_path: w.photo_path || null,
        passport_no: r[3] || w.passport_no || '', passport_issue: excelDate(r[4]), passport_expiry: excelDate(r[5]),
        labour_card_no: r[6] || '', labour_card_issue: excelDate(r[7]), labour_card_expiry: excelDate(r[8]),
        residence_card_no: r[9] || '', residence_card_issue: excelDate(r[10]), residence_card_expiry: excelDate(r[11]),
        visa_no: r[12] || '', visa_issue: excelDate(r[13]), visa_expiry: excelDate(r[14]),
        stay_duration: capStayDuration(r[15]),
      });
    }
    if (!inserts.length) { alert('ບໍ່ພົບຂໍ້ມູນທີ່ຖືກຕ້ອງ ຫຼືຫາຄົນບໍ່ພົບໃນລະບົບ'); return; }

    const { error } = await supabaseRetry(() => sb.from('foreign_worker_renewals').insert(inserts));
    if (error) { alert('ຜິດພາດ: ' + error.message + '\n\nກະລຸນາລອງໃໝ່ອີກຄັ້ງ'); return; }

    await logAudit('create', 'foreign_worker_renewals', `BULK-${inserts.length}`, {
      action_detail: `ຕໍ່ອາຍຸເອກະສານແຮງງານຕ່າງປະເທດຫຼາຍຄົນ (Excel): ${inserts.length} ຄົນ`,
      company: currentUser.companyData?.name_lao || currentUser.companyName || '',
      count: inserts.length,
    });

    let msg = `✅ ຕໍ່ອາຍຸສຳເລັດ ${inserts.length} ຄົນ`;
    if (notFound.length) {
      msg += `\n\n⚠️ ຫາບໍ່ພົບ ${notFound.length} ແຖວ (ກວດ ID ທະບຽນ/ເລກ Passport):\n` + notFound.slice(0,10).join('\n') + (notFound.length>10 ? `\n... ແລະອີກ ${notFound.length-10} ແຖວ` : '');
    }
    alert(msg);
    await loadFwRenewDocsData();
  } catch (e) { alert('ເກີດຂໍ້ຜິດພາດ: ' + e.message); }
}

async function handleFnrBulkPhotos(fileList) {
  if (!fileList || !fileList.length) return;
  const files = Array.from(fileList);
  const companyId = currentUser.companyId;
  const { data: allWorkers } = await sb.from('foreign_workers').select('id,reg_id,passport_no').eq('company_id', companyId);
  const norm = s => String(s || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
  const byKey = {};
  const byKeyLoose = {};
  (allWorkers || []).forEach(w => {
    if (w.reg_id) { byKey[String(w.reg_id).trim().toLowerCase()] = w; byKeyLoose[norm(w.reg_id)] = w; }
    if (w.passport_no) { byKey[String(w.passport_no).trim().toLowerCase()] = w; byKeyLoose[norm(w.passport_no)] = w; }
  });

  let matched = 0; const unmatched = [];
  for (const file of files) {
    if (matched > 0) await new Promise(r => setTimeout(r, 150)); // ຫຼຸດຄວາມໄວການສົ່ງ request ເພື່ອບໍ່ໃຫ້ຕິດ rate limit
    const nameNoExt = file.name.replace(/\.[^.]+$/, '').trim().toLowerCase();
    const w = byKey[nameNoExt] || byKeyLoose[norm(nameNoExt)];
    if (!w) { unmatched.push(file.name); continue; }
    try {
      const path = `fn_photos/${companyId}/${w.id}_${Date.now()}.jpg`;
      const upRes = await supabaseRetry(() => sb.storage.from('foreign-worker-docs').upload(path, file, { upsert: true }));
      if (upRes.error) { unmatched.push(`${file.name} (ອັບໂຫລດຜິດພາດ: ${upRes.error.message})`); continue; }
      const { error: updErr } = await supabaseRetry(() => sb.from('foreign_workers').update({ photo_path: path }).eq('id', w.id));
      if (updErr) { unmatched.push(`${file.name} (ບັນທຶກຖານຂໍ້ມູນຜິດພາດ: ${updErr.message})`); continue; }
      matched++;
    } catch (e) { unmatched.push(`${file.name} (${e.message})`); }
  }

  await logAudit('update', 'foreign_workers', `BULK-PHOTO-${matched}`, {
    action_detail: `ອັບໂຫລດຮູບຖ່າຍຫຼາຍຄົນ: ${matched} ຄົນ`,
    company: currentUser.companyData?.name_lao || currentUser.companyName || '',
  });

  let msg = `✅ ອັບໂຫລດຮູບສຳເລັດ ${matched} ຄົນ`;
  if (unmatched.length) {
    msg += `\n\n⚠️ ຈັບຄູ່ບໍ່ໄດ້ ${unmatched.length} ໄຟລ໌ (ຊື່ໄຟລ໌ບໍ່ກົງກັບ ID ທະບຽນ/Passport ຂອງໃຜ):\n` + unmatched.slice(0,10).join('\n');
  }
  alert(msg);
  await loadFwRenewDocsData();
}

// ============================================================
// FN NEW — BULK EXCEL UPLOAD + BULK PHOTOS (ໜ້າ "ແຮງງານຕ່າງປະເທດເຂົ້າໃໝ່")
// ໃຊ້ຮູບແບບ ID ດຽວກັນກັບການລົງທະບຽນເທື່ອລະຄົນ: FN-ເດືອນປີລຳດັບ (generateRegId)
// ============================================================
function renderFnNewBulkSection() {
  const el = document.getElementById('fnNewBulkSection');
  if (!el) return;
  el.innerHTML = `
    <div class="alert" style="background:#eaf4ff;border-left:4px solid #2980b9;border-radius:8px;padding:14px 16px;">
      <div style="font-weight:600;color:#1a5276;margin-bottom:6px;">📊 ລົງທະບຽນຫຼາຍຄົນພ້ອມກັນ (Excel)</div>
      <div style="font-size:12px;color:#555;margin-bottom:10px;">ສຳລັບລົງທະບຽນແຮງງານຕ່າງປະເທດເຂົ້າໃໝ່ຫຼາຍຄົນເທື່ອດຽວ — ໄດ້ ID ຮູບແບບດຽວກັນກັບການລົງທະບຽນເທື່ອລະຄົນ (FN-xxx)</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        <button class="btn btn-secondary btn-sm" onclick="downloadFnNewBulkTemplate()">⬇️ ດາວໂຫຼດ Template</button>
        <label class="btn btn-primary btn-sm" style="cursor:pointer;margin:0;">
          📊 ອັບໂຫຼດ Excel (ລົງທະບຽນຫຼາຍຄົນ)
          <input type="file" accept=".xlsx,.xls,.csv" style="display:none;" onchange="handleFnNewBulkExcel(this.files[0])">
        </label>
      </div>
      <div style="border-top:1px solid #cfe0ec;margin-top:12px;padding-top:10px;">
        <div style="font-weight:600;color:#1a5276;margin-bottom:6px;font-size:13px;">📷 ອັບໂຫລດຮູບຖ່າຍຫຼາຍຄົນພ້ອມກັນ</div>
        <div style="font-size:12px;color:#555;margin-bottom:8px;">ຕັ້ງຊື່ໄຟລ໌ຮູບເປັນ "ເລກ Passport" ຫຼື "ID ທະບຽນ" ຂອງແຕ່ລະຄົນ (ເຊັ່ນ <code>P123456789.jpg</code>) — ອັບໂຫລດຂໍ້ມູນ Excel ກ່ອນ ຈຶ່ງອັບໂຫລດຮູບ</div>
        <label class="btn btn-info btn-sm" style="cursor:pointer;margin:0;">
          📷 ເລືອກຮູບຫຼາຍຄົນ
          <input type="file" accept="image/*" multiple style="display:none;" onchange="handleFnNewBulkPhotos(this.files)">
        </label>
      </div>
    </div>`;
}

