async function handleFnNewBulkExcel(file) {
  if (!file) return;
  function excelDate(v) {
    if (!v) return null;
    v = String(v).trim();
    if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(v)) {
      const [d,m,y] = v.split('/');
      return `${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
    }
    if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
    const dt = new Date(v);
    return isNaN(dt.getTime()) ? null : dt.toISOString().split('T')[0];
  }
  try {
    if (!window.XLSX) { alert('ກຳລັງໂຫຼດ XLSX, ລອງໃໝ່ອີກສັກຄູ່'); return; }
    const buf = await file.arrayBuffer();
    let rows;
    if (file.name.endsWith('.csv')) {
      const text = new TextDecoder('utf-8').decode(buf).replace(/^\uFEFF/,'');
      rows = text.trim().split('\n').map(r => r.split(',').map(c => c.trim().replace(/^"|"$/g,'')));
    } else {
      const wb = window.XLSX.read(buf, { type:'array' });
      rows = window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header:1, raw:false });
    }
    if (rows.length < 2) { alert('ໄຟລ໌ຫວ່າງ ຫຼື ໃສ່ຂໍ້ມູນ row ທີ 2 ເປັນຕົ້ນໄປ'); return; }

    const dataRows = rows.slice(1).filter(r => r[1] || r[2]);
    if (!dataRows.length) { alert('ບໍ່ພົບຂໍ້ມູນ — ໃສ່ຂໍ້ມູນຕັ້ງແຕ່ row 2'); return; }

    if (!confirm(`ກຽມລົງທະບຽນ ${dataRows.length} ຄົນ\n\nຢືນຢັນ?`)) return;

    // ຄິດໄລ່ reg_id ຄາວດຽວກ່ອນ insert — ຮູບແບບດຽວກັນກັບ generateRegId('FN','foreign_workers')
    // (ບໍ່ເອີ້ນ generateRegId() ຊ້ຳໆໃນ loop ຍ້ອນຈະໄດ້ ID ຊ້ຳກັນ)
    const regYear = new Date().getFullYear();
    const regMonth = String(new Date().getMonth() + 1).padStart(2, '0');
    const regYY = String(regYear).slice(-2);
    const companyId = currentUser.companyId;
    const companyCode = await getCompanyCode(companyId);
    const idPrefix2 = `FN${companyCode}`;
    const { data: existingRegs } = await sb.from('foreign_workers').select('reg_id').eq('company_id', companyId).like('reg_id', `${idPrefix2}%`);
    const usedIds = new Set((existingRegs || []).map(r => r.reg_id));
    let maxSeq2 = 0;
    (existingRegs || []).forEach(r => {
      const n = parseInt(String(r.reg_id || '').slice(-3), 10);
      if (!isNaN(n) && n > maxSeq2) maxSeq2 = n;
    });
    let seq = maxSeq2 + 1;
    function nextRegId() {
      let regId;
      do { regId = `${idPrefix2}${regMonth}${regYY}${String(seq).padStart(3,'0')}`; seq++; } while (usedIds.has(regId));
      usedIds.add(regId);
      return regId;
    }

    const inserts = dataRows.map(r => ({
      company_id: companyId,
      reg_id: nextRegId(),
      reg_year: regYear,
      prefix: r[0]||'', firstname: r[1]||'', lastname: r[2]||'',
      nationality: r[3]||'', gender: r[4]||'ຊາຍ', position: r[5]||'',
      salary: parseFloat(r[6])||null, dob: excelDate(r[7]),
      passport_no: r[8]||'', passport_issue: excelDate(r[9]), passport_expiry: excelDate(r[10]),
      labour_card_no: r[11]||'', labour_card_issue: excelDate(r[12]), labour_card_expiry: excelDate(r[13]),
      stay_duration: capStayDuration(r[14]),
      residence_card_no: r[15]||'', residence_card_issue: excelDate(r[16]), residence_card_expiry: excelDate(r[17]),
      visa_no: r[18]||'', visa_issue: excelDate(r[19]), visa_expiry: excelDate(r[20]),
      start_date: excelDate(r[21]),
      labour_card_count: 1,
      doc_files: [], updated_at: new Date().toISOString()
    }));

    const { error: insertErr } = await supabaseRetry(() => sb.from('foreign_workers').insert(inserts));
    if (insertErr) { alert('ຜິດພາດ: ' + insertErr.message + '\n\nກະລຸນາລອງໃໝ່ອີກຄັ້ງ (ອາດຍ້ອນມີຄົນໃຊ້ລະບົບພ້ອມກັນຫຼາຍ)'); return; }

    await logAudit('create', 'foreign_workers', `BULK-${inserts.length}`, {
      action_detail: `ລົງທະບຽນແຮງງານຕ່າງປະເທດເຂົ້າໃໝ່ຫຼາຍຄົນ (Excel): ${inserts.length} ຄົນ`,
      company: currentUser.companyData?.name_lao || currentUser.companyName || '',
      count: inserts.length,
    });

    const { error: syncErr } = await syncForeignWorkersToRecords(currentUser.companyId) || {};
    if (syncErr) {
      alert(`✅ ລົງທະບຽນ ${inserts.length} ຄົນ ສຳເລັດ — ແຕ່ Sync ສະຖິຕິ ຕປທ ມີບັນຫາ: ${syncErr.message}`);
    } else {
      alert(`✅ ລົງທະບຽນ ${inserts.length} ຄົນ ສຳເລັດ — ຂໍ້ມູນຖືກ Sync ໄປໃນ "ສະຫຼຸບ" ທັນທີ`);
    }
    if (document.getElementById('companyFnTable')) {
      await loadFwNewWorkers();
    } else {
      await loadFnNew();
    }
  } catch (e) { alert('ເກີດຂໍ້ຜິດພາດ: ' + e.message); }
}

async function handleFnNewBulkPhotos(fileList) {
  if (!fileList || !fileList.length) return;
  const files = Array.from(fileList);
  const companyId = currentUser.companyId;
  const { data: allWorkers } = await sb.from('foreign_workers').select('id,reg_id,passport_no').eq('company_id', companyId);
  const norm = s => String(s || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
  const byKey = {};      // exact (lowercased, trimmed) key
  const byKeyLoose = {}; // normalized (letters/numbers only) key — tolerates spaces / dash style differences
  (allWorkers || []).forEach(w => {
    if (w.reg_id) { byKey[String(w.reg_id).trim().toLowerCase()] = w; byKeyLoose[norm(w.reg_id)] = w; }
    if (w.passport_no) { byKey[String(w.passport_no).trim().toLowerCase()] = w; byKeyLoose[norm(w.passport_no)] = w; }
  });

  let matched = 0; const unmatched = [];
  for (const file of files) {
    if (matched > 0) await new Promise(r => setTimeout(r, 150)); // ຫຼຸດຄວາມໄວການສົ່ງ request ເພື່ອບໍ່ໃຫ້ຕິດ rate limit
    const nameNoExt = file.name.replace(/\.[^.]+$/, '').trim().toLowerCase();
    const w = byKey[nameNoExt] || byKeyLoose[norm(nameNoExt)];
    if (!w) { unmatched.push(file.name); continue; }
    try {
      const path = `fn_photos/${companyId}/${w.id}_${Date.now()}.jpg`;
      const upRes = await supabaseRetry(() => sb.storage.from('foreign-worker-docs').upload(path, file, { upsert: true }));
      if (upRes.error) { unmatched.push(`${file.name} (ອັບໂຫລດຜິດພາດ: ${upRes.error.message})`); continue; }
      const { error: updErr } = await supabaseRetry(() => sb.from('foreign_workers').update({ photo_path: path }).eq('id', w.id));
      if (updErr) { unmatched.push(`${file.name} (ບັນທຶກຖານຂໍ້ມູນຜິດພາດ: ${updErr.message})`); continue; }
      matched++;
    } catch (e) { unmatched.push(`${file.name} (${e.message})`); }
  }

  await logAudit('update', 'foreign_workers', `BULK-PHOTO-${matched}`, {
    action_detail: `ອັບໂຫລດຮູບຖ່າຍຫຼາຍຄົນ (ແຮງງານເຂົ້າໃໝ່): ${matched} ຄົນ`,
    company: currentUser.companyData?.name_lao || currentUser.companyName || '',
  });

  let msg = `✅ ອັບໂຫລດຮູບສຳເລັດ ${matched} ຄົນ`;
  if (unmatched.length) {
    msg += `\n\n⚠️ ຈັບຄູ່ບໍ່ໄດ້ ${unmatched.length} ໄຟລ໌ (ຊື່ໄຟລ໌ບໍ່ກົງກັບ ID ທະບຽນ/Passport ຂອງໃຜ):\n` + unmatched.slice(0,10).join('\n');
  }
  alert(msg);
  if (document.getElementById('companyFnTable')) {
    await loadFwNewWorkers();
  } else {
    await loadFnNew();
  }
}

