async function handleFnBulkExcel(file) {
  if (!file) return;
  function excelDate(v) {
    if (!v) return null;
    v = String(v).trim();
    if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(v)) {
      const [d,m,y] = v.split('/');
      return `${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
    }
    if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
    const dt = new Date(v);
    return isNaN(dt.getTime()) ? null : dt.toISOString().split('T')[0];
  }
  try {
    if (!window.XLSX) { alert('ກຳລັງໂຫຼດ XLSX, ລອງໃໝ່ອີກສັກຄູ່'); return; }
    const buf = await file.arrayBuffer();
    let rows;
    if (file.name.endsWith('.csv')) {
      const text = new TextDecoder('utf-8').decode(buf).replace(/^\uFEFF/,'');
      rows = text.trim().split('\n').map(r => r.split(',').map(c => c.trim().replace(/^"|"$/g,'')));
    } else {
      const wb = window.XLSX.read(buf, { type:'array' });
      rows = window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header:1, raw:false });
    }
    if (rows.length < 2) { alert('ໄຟລ໌ຫວ່າງ ຫຼື ໃສ່ຂໍ້ມູນ row ທີ 2 ເປັນຕົ້ນໄປ'); return; }

    // Validate at least 3 columns (prefix, firstname, lastname)
    const dataRows = rows.slice(1).filter(r => r[1] || r[2]);
    if (!dataRows.length) { alert('ບໍ່ພົບຂໍ້ມູນ — ໃສ່ຂໍ້ມູນຕັ້ງແຕ່ row 2'); return; }

    if (!confirm(`ກຽມນຳເຂົ້າ ${dataRows.length} ຄົນ\n\n⚠️ ຫຼັງຈາກນຳເຂົ້າ ຈະບໍ່ສາມາດແກ້ໄຂໄດ້ — ຕ້ອງຕິດຕໍ່ແອັດມີນ\n\nຢືນຢັນ?`)) return;

    // Auto-generate reg_id using same pattern as FN manual
    const now = new Date();
    const yy = String(now.getFullYear()).slice(-2);
    const mm = String(now.getMonth()+1).padStart(2,'0');
    const { data: existing } = await supabaseRetry(() => sb.from('foreign_workers').select('id').eq('company_id', currentUser.companyId));
    let seq = (existing?.length || 0) + 1;

    const inserts = dataRows.map(r => ({
      company_id: currentUser.companyId,
      reg_id: `FN-${(currentUser.companyData?.username||'XX')}${mm}${yy}${String(seq++).padStart(3,'0')}`,
      reg_year: now.getFullYear(),
      prefix: r[0]||'', firstname: r[1]||'', lastname: r[2]||'',
      nationality: r[3]||'', gender: r[4]||'ຊາຍ', position: r[5]||'',
      salary: parseFloat(r[6])||null, dob: excelDate(r[7]),
      passport_no: r[8]||'', passport_issue: excelDate(r[9]), passport_expiry: excelDate(r[10]),
      labour_card_no: r[11]||'', labour_card_issue: excelDate(r[12]), labour_card_expiry: excelDate(r[13]),
      stay_duration: capStayDuration(r[14]),
      residence_card_no: r[15]||'', residence_card_issue: excelDate(r[16]), residence_card_expiry: excelDate(r[17]),
      visa_no: r[18]||'', visa_issue: excelDate(r[19]), visa_expiry: excelDate(r[20]),
      start_date: excelDate(r[21]),
      labour_card_count: 1,
      doc_files: [], updated_at: new Date().toISOString()
    }));

    const { error: insertErr } = await supabaseRetry(() => sb.from('foreign_workers').insert(inserts));
    if (insertErr) { alert('ຜິດພາດ: ' + insertErr.message + '\n\nກະລຸນາລອງໃໝ່ອີກຄັ້ງ (ອາດຍ້ອນມີຄົນໃຊ້ລະບົບພ້ອມກັນຫຼາຍ)'); return; }

    // ບັນທຶກ Audit Log — ໃຫ້ Admin ເຫັນ badge ແຈ້ງເຕືອນ (ຈຸດທີ່ເຄີຍຂາດຫາຍໄປ)
    await logAudit('create', 'foreign_workers', `BULK-${inserts.length}`, {
      action_detail: `ອັບໂຫລດ Excel ນຳເຂົ້າແຮງງານຕ່າງປະເທດ ${inserts.length} ຄົນ`,
      company: currentUser.companyData?.name_lao || currentUser.companyName || '',
      count: inserts.length,
    });

    // Lock: set fn_bulk_uploaded = true on the company
    await supabaseRetry(() => sb.from('companies').update({ fn_bulk_uploaded: true }).eq('id', currentUser.companyId));

    // Sync summary totals (ຄືກັບການບັນທຶກເທື່ອລະຄົນ) — ບໍ່ດັ່ງນັ້ນ "ສະຫຼຸບແຮງງານທັງໝົດ" ຈະຄ້າງເລກ 0
    const { error: syncErr } = await syncForeignWorkersToRecords(currentUser.companyId) || {};
    if (syncErr) {
      alert(`✅ ນຳເຂົ້າ ${inserts.length} ຄົນ ສຳເລັດ — ແຕ່ Sync ສະຖິຕິ ຕປທ ມີບັນຫາ: ${syncErr.message}`);
    } else {
      alert(`✅ ນຳເຂົ້າ ${inserts.length} ຄົນ ສຳເລັດ — ຂໍ້ມູນໄດ້ຖືກລ໋ອກແລ້ວ ແລະ Sync ໄປໃນ "ສະຫຼຸບ" ທັນທີ`);
    }
    await renderFnBulkSection();
    await loadFwRenewDocsData();
  } catch(e) { alert('ເກີດຂໍ້ຜິດພາດ: ' + e.message); }
}

// Separate data-loading from full loadFwRenewDocs so we can reload without re-render
async function loadFwRenewDocsData() {
  const { data: rawAll, error: fwErr } = await sb.from('foreign_workers')
    .select('*')
    .eq('company_id', currentUser.companyId)
    .order('firstname');
  if (fwErr) console.warn('loadFwRenewDocsData error:', fwErr.message);
  _fnAllWorkersCache = await attachCompanyInfo(rawAll || []);

  const alertEl = document.getElementById('fnrExpiryAlert');
  if (alertEl && _fnAllWorkersCache.length > 0) {
    const today = new Date(); today.setHours(0,0,0,0);
    const d60 = new Date(today); d60.setDate(d60.getDate() + 60);
    const expiring = _fnAllWorkersCache.filter(w => {
      const expDate = w.labour_card_expiry ? new Date(w.labour_card_expiry) : null;
      return expDate && expDate <= d60;
    }).sort((a,b) => new Date(a.labour_card_expiry) - new Date(b.labour_card_expiry));
    if (expiring.length > 0) {
      alertEl.innerHTML = `
        <div class="alert" style="background:#fff3cd;border-left:4px solid #f39c12;border-radius:8px;padding:12px 16px;">
          <div style="font-weight:600;color:#856404;margin-bottom:8px;">⚠️ ແຮງງານ ${expiring.length} ຄົນ ໃກ້/ຄົບກຳນົດ ບັດແຮງງານ (ພາຍໃນ 60 ວັນ)</div>
          <div style="display:flex;flex-wrap:wrap;gap:8px;">
            ${expiring.map(w => {
              const exp = new Date(w.labour_card_expiry);
              const daysLeft = Math.ceil((exp - today) / 86400000);
              const color = daysLeft < 0 ? '#e74c3c' : daysLeft <= 15 ? '#e74c3c' : '#f39c12';
              return `<button class="btn btn-sm" style="background:#fff;border:2px solid ${color};color:${color};font-size:12px;" onclick="selectFnrWorkerById('${w.id}')">
                ${esc(w.firstname)} ${esc(w.lastname)}
                <span style="display:block;font-size:10px;">${daysLeft < 0 ? '❌ ໝົດແລ້ວ '+ Math.abs(daysLeft)+' ວັນ' : '⏳ ໃກ້ '+ daysLeft +' ວັນ'}</span>
              </button>`;
            }).join('')}
          </div>
        </div>`;
    } else {
      alertEl.innerHTML = '<div class="alert alert-success" style="padding:10px 16px;">✅ ແຮງງານທຸກຄົນຍັງບໍ່ທັນຄົບກຳນົດໃນ 60 ວັນຂ້າງໜ້າ</div>';
    }
  }
  const preSelectId = sessionStorage.getItem('fnrPreSelectId');
  if (preSelectId) {
    sessionStorage.removeItem('fnrPreSelectId');
    selectFnrWorkerById(preSelectId);
  }
  loadFnrHistory();
}

// Admin: unlock bulk upload for a company
async function unlockFnBulk(companyId, companyName) {
  if (!confirm(`ອະນຸຍາດໃຫ້ "${companyName}" ອັບໂຫຼດຂໍ້ມູນ FN Bulk ຄືນໃໝ່?\n(ຂໍ້ມູນ FN ເກົ່າຂອງເຂົາຈະຍັງຄົງຢູ່ — ເພາະ INSERT ໃໝ່ ທ່ານຄວນລຶບ duplicates ຕ່າງຫາກ)`)) return;
  const { error } = await sb.from('companies').update({ fn_bulk_uploaded: false }).eq('id', companyId);
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  alert(`✅ ອ່ານລ໋ອກ "${companyName}" ສຳເລັດ — ເຂົາສາມາດ re-upload FN Bulk ໄດ້ແລ້ວ`);
  loadCompanyTable();
}

// ============================================================
function selectFnrWorkerById(id) {
  const w = (_fnAllWorkersCache || []).find(x => x.id === id);
  if (!w) return;
  selectFnForRenewal(w.id);
}

// Update openFwLetterPanel to accept type hint
async function openFwLetterPanel(typeHint) {
  const panel = document.getElementById('fwLetterPanel');
  if (!panel) return;
  const typeEl = document.getElementById('fwLetterType');
  const type = typeHint || (typeEl ? typeEl.value : 'new');
  panel.style.display = 'block';
  panel.scrollIntoView({ behavior: 'smooth' });

  const listEl = document.getElementById('fwLetterWorkerList');
  if (!listEl) return;
  listEl.innerHTML = '<div style="color:#aaa;padding:10px;">ກຳລັງໂຫຼດ...</div>';

  let workers = [];
  let loadError = null;

  if (type === 'renew') {
    // Load FNR workers: those in foreign_workers whose reg_id starts FNR-
    // (safer than querying foreign_worker_renewals which may have missing columns)
    const { data: fwData, error } = await sb.from('foreign_workers')
      .select('id,reg_id,prefix,firstname,lastname,nationality,gender,position,passport_no,passport_expiry,stay_duration,photo_path,salary,dob')
      .eq('company_id', currentUser.companyId)
      .order('created_at', { ascending: false });
    loadError = error;
    if (fwData) workers = fwData.filter(w => String(w.reg_id||'').startsWith('FNR'));
  } else {
    // FN new: load from foreign_workers, exclude already-renewed (reg_id starts FNR-)
    const { data: fwData, error } = await sb.from('foreign_workers')
      .select('id,reg_id,prefix,firstname,lastname,nationality,gender,position,passport_no,passport_expiry,stay_duration,photo_path,salary,dob')
      .eq('company_id', currentUser.companyId)
      .order('created_at', { ascending: false });
    loadError = error;
    if (fwData) workers = fwData.filter(w => !String(w.reg_id||'').startsWith('FNR'));
  }

  if (loadError) {
    listEl.innerHTML = `<div class="alert alert-danger">❌ ${loadError.message}</div>`;
    return;
  }
  if (!workers.length) {
    const msg = type === 'renew'
      ? 'ຍັງບໍ່ມີປະຫວັດຕໍ່ເອກະສານ — ກົດ "💾 ບັນທຶກ" ໃນ form ຕໍ່ເອກະສານກ່ອນ ຈຶ່ງກັບມາສ້າງໃບສະເໜີ'
      : 'ຍັງບໍ່ມີແຮງງານທີ່ລົງທະບຽນໄວ້ — ກົດ "+ ລົງທະບຽນໃໝ່" ກ່ອນ';
    listEl.innerHTML = `<div class="alert alert-info">${msg}</div>`;
    return;
  }

  listEl.innerHTML = `
    <div style="margin-bottom:10px;">
      <label style="cursor:pointer;"><input type="checkbox" id="fwLetterSelectAll" onchange="toggleSelectAllWorkers(this)"> ເລືອກທັງໝົດ (${workers.length} ຄົນ)</label>
    </div>
    <div class="table-wrap"><table><thead><tr>
      <th style="width:40px;"></th><th>ຮູບ</th><th>ID ທະບຽນ</th><th>ຊື່-ນາມສະກຸນ</th><th>ສັນຊາດ</th><th>ຕຳແໜ່ງ</th><th>ເລກ Passport</th><th>ກຳນົດຢູ່</th>
    </tr></thead><tbody>
      ${workers.map(w => {
        const thumb = w.photo_path
          ? `<img src="${sb.storage.from('foreign-worker-docs').getPublicUrl(w.photo_path).data.publicUrl}" style="width:32px;height:42px;object-fit:cover;border-radius:4px;">`
          : `<div style="width:32px;height:42px;border:1px dashed #ccc;border-radius:4px;display:flex;align-items:center;justify-content:center;color:#ccc;">👤</div>`;
        return `<tr>
          <td><input type="checkbox" class="fwWorkerChk" value="${w.id}" data-worker='${JSON.stringify(w).replace(/'/g,"&#39;")}'></td>
          <td>${thumb}</td>
          <td><b>${esc(w.reg_id)}</b></td>
          <td>${esc(w.prefix||'')} ${esc(w.firstname)} ${esc(w.lastname)}</td>
          <td>${esc(w.nationality||'-')}</td>
          <td>${esc(w.position||'-')}</td>
          <td>${esc(w.passport_no||'-')}</td>
          <td>${w.stay_duration ? w.stay_duration + ' ເດືອນ' : '-'}</td>
        </tr>`;
      }).join('')}
    </tbody></table></div>`;
}

