async function loadFwRequestsAdmin() {
  const el = document.getElementById('fwRequestsAdminTable');
  if (!el) return;
  const { data: rawData, error } = await sb.from('fw_requests').select('*').order('created_at', { ascending: false });
  const data = await attachCompanyInfo(rawData);
  if (error) { el.innerHTML = `<div class="alert alert-danger">❌ ${error.message}<br><span style="font-size:11px;">ກວດສອບວ່າໄດ້ Run section_c_company_request.sql ໃນ Supabase ແລ້ວບໍ່</span></div>`; return; }
  if (!data || data.length === 0) { el.innerHTML = '<div style="text-align:center;color:#aaa;padding:30px;">ຍັງບໍ່ມີຄຳຂໍຈາກບໍລິສັດ</div>'; return; }
  el.innerHTML = `<table><thead><tr>
    <th>ວັນທີສົ່ງ</th><th>ບໍລິສັດ</th><th>ປະເພດ</th><th>ຈຳນວນ (ຊາຍ/ຍິງ)</th><th>ສະຖານະ</th><th>ຈັດການ</th>
  </tr></thead><tbody>
    ${data.map(r => `<tr>
      <td>${laoDate(r.created_at)}</td>
      <td>${esc(r.companies?.username || '-')} — ${esc(r.companies?.name_lao || '')}</td>
      <td>${r.request_type === 'new' ? '🆕 ລົງທະບຽນໃໝ່' : '🔄 ຕໍ່ອາຍຸ'}</td>
      <td>${r.male_count || 0} / ${r.female_count || 0}</td>
      <td>${r.rejected ? '<span style="color:#c0392b;">❌ ປະຕິເສດ</span>' : r.final_approved ? '<span class="status-ok">🏁 ອະນຸມັດແລ້ວ</span>' : r.status === 'reviewed' ? '<span style="color:#1769C2;">✅ ກວດແລ້ວ</span>' : '<span style="color:#e67e22;">📥 ໃໝ່</span>'}</td>
      <td>
        <button class="btn btn-info btn-sm" onclick="viewFwRequest('${r.id}')">🔍 ເບິ່ງ</button>
        ${r.status !== 'reviewed' ? `<button class="btn btn-success btn-sm" onclick="markFwRequestReviewed('${r.id}')">✅ ກວດແລ້ວ</button>` : ''}
      </td>
    </tr>`).join('')}
  </tbody></table>`;
}

async function viewFwRequest(id) {
  const { data: r, error } = await sb.from('fw_requests').select('*, companies(*)').eq('id', id).single();
  if (error || !r) { alert('ບໍ່ພົບຂໍ້ມູນ'); return; }
  window._currentFwRequestId = id;

  const quotaUrl = companyDocUrl(r.quota_file);
  const taxUrl = companyDocUrl(r.tax_cert_file);
  const co = r.companies || {};
  // ເອກະສານປະຈຳບໍລິສັດ (ຕັ້ງແຕ່ຕອນເພີ່ມຂໍ້ມູນບໍລິສັດເຂົ້າລະບົບ) — ຕິກອັດຕະໂນມັດຖ້າມີຂໍ້ມູນນັ້ນຢູ່ໃນໂປຣໄຟລ໌ບໍລິສັດແລ້ວ (ອ່ານຢ່າງດຽວ, ບໍ່ນັບເຂົ້າເງື່ອນໄຂ "ກວດແລ້ວ" ຂອງຄຳຮ້ອງນີ້)
  const companyDocChecklist = [
    ['ໃບທະບຽນວິສາຫະກິດ', !!(co.biz_reg_no || co.biz_reg_file)],
    ['ໃບອະນຸຍາດລົງທຶນ', !!(co.invest_no || co.invest_file)],
    ['ໃບທະບຽນອາກອນ', !!(co.tax_no || co.tax_file)],
    ['ໃບທະບຽນປະກັນສັງຄົມ', !!(co.social_no || co.social_file)],
    ['ໃບອະນຸຍາດນຳໃຊ້ກົດລະບຽບ', !!(co.rule_no || co.rule_file)],
  ];
  const companyDocsHtml = `
    <div style="background:#fff;border:1px solid #e1e8f0;border-radius:10px;padding:14px 16px;margin-bottom:16px;">
      <div style="font-size:13px;font-weight:700;color:#154360;margin-bottom:8px;">🏢 ເອກະສານປະຈຳບໍລິສັດ (ອ້າງອີງຈາກໂປຣໄຟລ໌ບໍລິສັດ)</div>
      ${companyDocChecklist.map(([label, has]) => `
      <label style="display:flex;align-items:center;gap:8px;font-size:13px;margin-bottom:6px;color:${has?'#333':'#aaa'};">
        <input type="checkbox" disabled ${has ? 'checked' : ''}> ${label} ${has ? '' : '<span style="font-size:11px;">(ຍັງບໍ່ໄດ້ຕື່ມໃນໂປຣໄຟລ໌ບໍລິສັດ)</span>'}
      </label>`).join('')}
    </div>`;
  const docsHtml = `
    <div style="background:#f7f9fb;border-radius:10px;padding:14px 16px;margin-bottom:16px;">
      <div style="font-size:13px;font-weight:700;color:#154360;margin-bottom:8px;">📎 ເອກະສານຄັດຕິດ (ຈາກບໍລິສັດ)</div>
      <div style="font-size:13px;margin-bottom:6px;">
        ${quotaUrl ? `<a href="${escAttr(quotaUrl)}" target="_blank" rel="noopener" style="color:#1769C2;font-weight:600;">📄 ໃບອະນຸຍາດໂຄຕ້າ (ເລກທີ ${esc(r.quota_no||'-')})</a>` : '<span style="color:#aaa;">- ບໍ່ມີໄຟລ໌ໃບໂຄຕ້າ -</span>'}
      </div>
      <div style="font-size:13px;">
        ${taxUrl ? `<a href="${escAttr(taxUrl)}" target="_blank" rel="noopener" style="color:#1769C2;font-weight:600;">📄 ໃບແຈ້ງເສຍອາກອນປະຈຳປີ (ເລກທີ ${esc(r.tax_cert_no||'-')})</a>` : '<span style="color:#aaa;">- ບໍ່ມີໄຟລ໌ໃບອາກອນ -</span>'}
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e1e8f0;border-radius:10px;padding:14px 16px;margin-bottom:16px;">
      <div style="font-size:13px;font-weight:700;color:#154360;margin-bottom:8px;">✅ ເຊັກລິດການກວດເອກະສານ</div>
      <label style="display:flex;align-items:center;gap:8px;font-size:13px;margin-bottom:6px;cursor:pointer;">
        <input type="checkbox" id="fwCheckWorkers" ${r.checked_workers ? 'checked' : ''} onchange="updateFwRequestChecklist('${id}','checked_workers',this.checked)"> ກວດຂໍ້ມູນ/ບັນຊີລາຍຊື່ພະນັກງານແລ້ວ
      </label>
      <label style="display:flex;align-items:center;gap:8px;font-size:13px;margin-bottom:6px;cursor:pointer;">
        <input type="checkbox" id="fwCheckQuota" ${r.checked_quota ? 'checked' : ''} onchange="updateFwRequestChecklist('${id}','checked_quota',this.checked)"> ກວດໃບອະນຸຍາດໂຄຕ້າແລ້ວ
      </label>
      <label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer;">
        <input type="checkbox" id="fwCheckTax" ${r.checked_tax ? 'checked' : ''} onchange="updateFwRequestChecklist('${id}','checked_tax',this.checked)"> ກວດໃບແຈ້ງເສຍອາກອນປະຈຳປີແລ້ວ
      </label>
      <div id="fwCheckStatus" style="font-size:12px;margin-top:10px;color:${r.status==='reviewed'?'#2e9d67':'#e67e22'};font-weight:600;">
        ${r.status === 'reviewed' ? '✅ ກວດຄົບຖ້ວນແລ້ວ — ບໍລິສັດຈະໄດ້ຮັບການແຈ້ງເຕືອນ' : '📥 ຍັງກວດບໍ່ຄົບ — ຕ້ອງກາຄົບທັງ 3 ຂໍ້ ຈຶ່ງຈະແຈ້ງເຕືອນໄປຫາບໍລິສັດ'}
      </div>
    </div>`;

  const finalActionsHtml = `
    <div style="background:#fff;border:1px solid #e1e8f0;border-radius:10px;padding:14px 16px;margin-bottom:16px;">
      <div style="font-size:13px;font-weight:700;color:#154360;margin-bottom:8px;">🏁 ຂັ້ນຕອນສຸດທ້າຍ</div>
      ${r.final_approved
        ? `<div style="font-size:13px;color:#2e9d67;font-weight:600;">✅ ອະນຸມັດຂັ້ນສຸດທ້າຍແລ້ວ ${r.final_approved_at ? '(' + laoDate(r.final_approved_at) + ')' : ''}</div>
           ${companyDocUrl(r.approved_file_original) ? `<div style="font-size:12px;margin-top:6px;"><a href="${escAttr(companyDocUrl(r.approved_file_original))}" target="_blank" rel="noopener" style="color:#1769C2;">📄 ເບິ່ງເອກະສານຕົ້ນສະບັບ (ບໍ່ມີລາຍນ້ຳ — ສະເພາະແອັດມິນ)</a></div>` : ''}`
        : r.rejected
        ? `<div style="font-size:13px;color:#c0392b;font-weight:600;">❌ ຖືກປະຕິເສດແລ້ວ</div>`
        : r.status === 'reviewed'
        ? `<div style="display:flex;gap:8px;">
             <button class="btn btn-success btn-sm" onclick="finalApproveFwRequest('${id}')">✅ ອະນຸມັດຂັ້ນສຸດທ້າຍ</button>
             <button class="btn btn-danger btn-sm" onclick="rejectFwRequest('${id}')">❌ ປະຕິເສດ</button>
           </div>`
        : `<div style="font-size:12px;color:#aaa;">ຕ້ອງກວດເອກະສານໃຫ້ຄົບ 3 ຂໍ້ຂ້າງເທິງກ່ອນ ຈຶ່ງຈະອະນຸມັດຂັ້ນສຸດທ້າຍໄດ້</div>`}
    </div>`;

  document.getElementById('fwReqViewBody').innerHTML = buildFwTrackerHtml(r) + docsHtml + companyDocsHtml + finalActionsHtml + buildFwRequestLetterHtml(r);
  document.getElementById('fwReqViewModal').classList.add('show');
}

// ອະນຸມັດຂັ້ນສຸດທ້າຍ — ຂັ້ນຕອນສຸດທ້າຍຂອງລະບົບແທຣັກກິງ, ແຈ້ງເຕືອນໄປຫາບໍລິສັດ
// ປະທັບລາຍນ້ຳ "COPY" ສີແດງໃຫຍ່ຂວາງກາງໜ້າ PDF (ໃຊ້ pdf-lib, ເຮັດຢູ່ browser ກ່ອນອັບໂຫລດ) — ສະບັບນີ້ຄືສະບັບທີ່ບໍລິສັດຈະເຫັນ, ບໍ່ແມ່ນເອກະສານແທ້
async function addCopyWatermark(file) {
  const { PDFDocument, rgb, degrees, StandardFonts } = PDFLib;
  const bytes = await file.arrayBuffer();
  const pdfDoc = await PDFDocument.load(bytes);
  const font = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const pages = pdfDoc.getPages();
  pages.forEach(page => {
    const { width, height } = page.getSize();
    const text = 'COPY';
    const fontSize = Math.min(width, height) * 0.28;
    const textWidth = font.widthOfTextAtSize(text, fontSize);
    page.drawText(text, {
      x: width / 2 - textWidth / 2.6,
      y: height / 2 - fontSize / 3,
      size: fontSize,
      font,
      color: rgb(0.85, 0.1, 0.1),
      opacity: 0.35,
      rotate: degrees(-35),
    });
  });
  const watermarkedBytes = await pdfDoc.save();
  return new Blob([watermarkedBytes], { type: 'application/pdf' });
}

async function finalApproveFwRequest(id) {
  const { data: r } = await sb.from('fw_requests').select('doc_no,created_at').eq('id', id).single();
  const docNo = r?.doc_no || '-';
  const docDate = r?.created_at ? laoDate(r.created_at) : '-';

  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.78);z-index:99999;display:flex;align-items:center;justify-content:center;padding:24px;';
  const panel = document.createElement('div');
  panel.style.cssText = 'background:#fff;border-radius:16px;width:min(480px,94vw);padding:26px;position:relative;box-shadow:0 20px 60px rgba(0,0,0,0.4);';
  panel.onclick = (e) => e.stopPropagation();
  panel.innerHTML = `
    <div style="font-size:16px;font-weight:700;color:#154360;margin-bottom:4px;">✅ ອະນຸມັດຂັ້ນສຸດທ້າຍ</div>
    <div style="font-size:12px;color:#888;margin-bottom:14px;">ອ້າງອີງໃບສະເໜີ ເລກທີ <b>${esc(docNo)}</b> ລົງວັນທີ <b>${docDate}</b></div>
    <div class="form-field" style="margin-bottom:10px;"><label>ອັບໂຫລດເອກະສານທີ່ເຊັນອະນຸມັດແລ້ວ (PDF) <span style="color:red;">*</span></label>
      <div style="display:flex;gap:6px;align-items:center;">
        <button type="button" class="btn btn-secondary btn-sm" onclick="document.getElementById('fwApprovedFileInput').click()">📎 ເລືອກໄຟລ໌</button>
        <span id="fwApprovedFileStatus" style="font-size:12px;color:#888;">ຍັງບໍ່ໄດ້ເລືອກໄຟລ໌</span>
      </div>
      <input type="file" id="fwApprovedFileInput" accept="application/pdf" style="display:none;">
    </div>
    <div style="text-align:right;margin-top:18px;display:flex;justify-content:flex-end;gap:8px;">
      <button class="btn btn-secondary" id="fwApprovedCancelBtn">ຍົກເລີກ</button>
      <button class="btn btn-success" id="fwApprovedConfirmBtn">✅ ຢືນຢັນອະນຸມັດ</button>
    </div>`;
  const closeFn = () => overlay.remove();
  overlay.appendChild(panel);
  document.body.appendChild(overlay);

  let approvedFile = null;
  document.getElementById('fwApprovedFileInput').onchange = (e) => {
    approvedFile = e.target.files[0] || null;
    document.getElementById('fwApprovedFileStatus').textContent = approvedFile ? `✅ ${approvedFile.name}` : 'ຍັງບໍ່ໄດ້ເລືອກໄຟລ໌';
  };
  document.getElementById('fwApprovedCancelBtn').onclick = closeFn;
  document.getElementById('fwApprovedConfirmBtn').onclick = async () => {
    if (!approvedFile) { alert('ກະລຸນາອັບໂຫລດເອກະສານທີ່ເຊັນອະນຸມັດແລ້ວກ່ອນ'); return; }
    const confirmBtn = document.getElementById('fwApprovedConfirmBtn');
    confirmBtn.disabled = true; confirmBtn.textContent = '⏳ ກຳລັງປະທັບລາຍນ້ຳ...';
    const safeDocNo = String(docNo).replace(/[^a-zA-Z0-9]/g, '');
    const ts = Date.now();

    // 1) ເກັບເອກະສານຕົ້ນສະບັບໄວ້ (ສະບັບແທ້, ໃຫ້ແອັດມິນເບິ່ງ — ບໍ່ມີລາຍນ້ຳ)
    const originalPath = `approved-original/${safeDocNo}_${ts}.pdf`;
    const { error: origErr } = await supabaseRetry(() => sb.storage.from('company-docs').upload(originalPath, approvedFile, { upsert: true }));
    if (origErr) { alert('ອັບໂຫລດຜິດພາດ (ຕົ້ນສະບັບ): ' + origErr.message); confirmBtn.disabled = false; confirmBtn.textContent = '✅ ຢືນຢັນອະນຸມັດ'; return; }

    // 2) ສ້າງສະບັບລາຍນ້ຳ "COPY" ສີແດງ ໃຫ້ບໍລິສັດເຫັນແທນ
    let watermarkedBlob;
    try {
      watermarkedBlob = await addCopyWatermark(approvedFile);
    } catch (e) {
      alert('ບໍ່ສາມາດປະທັບລາຍນ້ຳໄດ້ (ອາດຍ້ອນໄຟລ໌ບໍ່ແມ່ນ PDF ປົກກະຕິ): ' + e.message);
      confirmBtn.disabled = false; confirmBtn.textContent = '✅ ຢືນຢັນອະນຸມັດ';
      return;
    }
    confirmBtn.textContent = '⏳ ກຳລັງອັບໂຫລດ...';
    const path = `approved/${safeDocNo}_${ts}.pdf`;
    const { error: upErr } = await supabaseRetry(() => sb.storage.from('company-docs').upload(path, watermarkedBlob, { upsert: true }));
    if (upErr) { alert('ອັບໂຫລດຜິດພາດ: ' + upErr.message); confirmBtn.disabled = false; confirmBtn.textContent = '✅ ຢືນຢັນອະນຸມັດ'; return; }

    const { error } = await sb.from('fw_requests').update({ final_approved: true, final_approved_at: new Date().toISOString(), approved_file: path, approved_file_original: originalPath }).eq('id', id);
    if (error) { alert('ຜິດພາດ: ' + error.message); confirmBtn.disabled = false; confirmBtn.textContent = '✅ ຢືນຢັນອະນຸມັດ'; return; }
    closeFn();
    viewFwRequest(id);
    loadFwRequestsAdmin();
  };
}

async function rejectFwRequest(id) {
  const reason = prompt('ເຫດຜົນການປະຕິເສດ (ຈະສະແດງໃຫ້ບໍລິສັດເຫັນ):');
  if (reason === null) return; // ຍົກເລີກ
  const { error } = await sb.from('fw_requests').update({ rejected: true, rejected_reason: reason || null }).eq('id', id);
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  viewFwRequest(id);
  loadFwRequestsAdmin();
}

// ອັບເດດເຊັກລິດການກວດເອກະສານ — ຖ້າກາຄົບທັງ 3 ຂໍ້ ຈະປ່ຽນສະຖານະເປັນ "ກວດແລ້ວ" ອັດຕະໂນມັດ ແລະ ແຈ້ງເຕືອນໄປຫາບໍລິສັດ (ຜ່ານລະບົບແຈ້ງເຕືອນ 🔔 ຝັ່ງບໍລິສັດ)
async function updateFwRequestChecklist(id, field, value) {
  const { error } = await sb.from('fw_requests').update({ [field]: value }).eq('id', id);
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  const { data: r } = await sb.from('fw_requests').select('checked_workers,checked_quota,checked_tax,status').eq('id', id).single();
  if (!r) return;
  const allChecked = r.checked_workers && r.checked_quota && r.checked_tax;
  const statusEl = document.getElementById('fwCheckStatus');
  if (allChecked && r.status !== 'reviewed') {
    await sb.from('fw_requests').update({ status: 'reviewed', reviewed_at: new Date().toISOString() }).eq('id', id);
    if (statusEl) { statusEl.textContent = '✅ ກວດຄົບຖ້ວນແລ້ວ — ບໍລິສັດຈະໄດ້ຮັບການແຈ້ງເຕືອນ'; statusEl.style.color = '#2e9d67'; }
    loadFwRequestsAdmin();
  } else if (!allChecked && r.status === 'reviewed') {
    // ຖ້າຍົກເລີກຕິກກັບຄືນ (ບໍ່ຄົບອີກ) ໃຫ້ຖອນສະຖານະ "ກວດແລ້ວ" ຄືນ
    await sb.from('fw_requests').update({ status: 'submitted' }).eq('id', id);
    if (statusEl) { statusEl.textContent = '📥 ຍັງກວດບໍ່ຄົບ — ຕ້ອງກາຄົບທັງ 3 ຂໍ້ ຈຶ່ງຈະແຈ້ງເຕືອນໄປຫາບໍລິສັດ'; statusEl.style.color = '#e67e22'; }
    loadFwRequestsAdmin();
  }
}

async function markFwRequestReviewed(id) {
  const { error } = await sb.from('fw_requests').update({ status: 'reviewed', checked_workers: true, checked_quota: true, checked_tax: true, reviewed_at: new Date().toISOString() }).eq('id', id);
  if (error) { alert('ຜິດພາດ: ' + error.message); return; }
  loadFwRequestsAdmin();
}

