function switchEmpTab(name, btn) {
  document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.tabs .tab').forEach(t => t.classList.remove('active'));
  document.getElementById('tab-' + name)?.classList.add('active');
  btn.classList.add('active');
}

// Download Excel template
function downloadTemplate(type) {
  const wb = XLSX.utils.book_new();
  let headers, sheetName, dateColIdx;
  if(type === '8.1') {
    headers = [['ຊື່','ນາມສະກຸນ','ເພດ (ຊາຍ/ຍິງ)','ວຸດທິການສຶກສາ','ຕຳແໜ່ງ/ໜ້າທີ່','ສະຖານະ (ຝຶກງານ/ຖາວອນ)','ມື້ເຂົ້າເຮັດວຽກ DD/MM/YYYY']];
    sheetName = '8.1-ລາວເຂົ້າໃໝ່'; dateColIdx = [6];
  } else if(type === '8.2') {
    headers = [['ຊື່','ນາມສະກຸນ','ເພດ (ຊາຍ/ຍິງ)','ວຸດທິການສຶກສາ','ຕຳແໜ່ງ/ໜ້າທີ່','ເຫດຜົນການລາອອກ','ມື້ເຂົ້າເຮັດວຽກ DD/MM/YYYY','ມື້ລາອອກ DD/MM/YYYY']];
    sheetName = '8.2-ລາວລາອອກ'; dateColIdx = [6,7];
  } else if(type === '8.3') {
    headers = [['ຊື່','ນາມສະກຸນ','ເພດ (ຊາຍ/ຍິງ)','ສັນຊາດ','ວຸດທິການສຶກສາ','ຕຳແໜ່ງ/ໜ້າທີ່','ວັນທີເຂົ້າມາລາວ DD/MM/YYYY','ກຳນົດຢູ່ລາວ (1/3/6/12 ເດືອນ)']];
    sheetName = '8.3-ຕປທເຂົ້າໃໝ່'; dateColIdx = [6];
  } else {
    headers = [['ຊື່','ນາມສະກຸນ','ເພດ (ຊາຍ/ຍິງ)','ສັນຊາດ','ວຸດທິການສຶກສາ','ຕຳແໜ່ງ/ໜ້າທີ່','ເຫດຜົນການລາອອກ','ວັນທີເຂົ້າມາລາວ DD/MM/YYYY','ມື້ລາອອກ DD/MM/YYYY','ກຳນົດຢູ່ລາວ (1/3/6/12 ເດືອນ)']];
    sheetName = '8.4-ຕປທລາອອກ'; dateColIdx = [7,8];
  }
  // Add sample row
  if(type === '8.1') headers.push(['ສົມສີ','ສີລາ','ຊາຍ','ປະລິຍາຕີ','ຊ່າງ','ຖາວອນ','15/01/2025']);
  else if(type === '8.2') headers.push(['ສົມສີ','ສີລາ','ຊາຍ','ປະລິຍາຕີ','ຊ່າງ','ຍ້າຍໄປຕ່າງແຂວງ','15/01/2023','01/06/2025']);
  else if(type === '8.3') headers.push(['WANG','WEI','ຊາຍ','ຈີນ','ປະລິຍາຕີ','ວິສະວະກອນ','01/02/2025','12']);
  else headers.push(['WANG','WEI','ຊາຍ','ຈີນ','ປະລິຍາຕີ','ວິສະວະກອນ','ໝົດສັນຍາ','01/02/2023','01/06/2025','12']);

  const ws = XLSX.utils.aoa_to_sheet(headers);
  ws['!cols'] = headers[0].map(()=>({wch:22}));
  forceExcelTextColumns(ws, dateColIdx, headers.length - 1);
  XLSX.utils.book_append_sheet(wb, ws, sheetName);
  XLSX.writeFile(wb, `SVKSEZ_Form_${type}.xlsx`);
}

// Upload and preview Excel
async function uploadEmpExcel(input, type) {
  const file = input.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = async (e) => {
    try {
      const wb = XLSX.read(e.target.result, {type:'binary', cellDates:true});
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(ws, {header:1, defval:''});
      if(rows.length < 2) { alert('ໄຟລຫວ່າງ ຫຼື ບໍ່ມີຂໍ້ມູນ'); return; }

      const headers = rows[0];
      const dataRows = rows.slice(1).filter(r => r.some(c => c !== ''));
      if(dataRows.length === 0) { alert('ບໍ່ມີຂໍ້ມູນໃນໄຟລ'); return; }

      // Normalize date columns (handle Excel serial numbers)
      const dateColIdx = { '8.1':[6], '8.2':[6,7], '8.3':[6], '8.4':[7,8] };
      const idxToFix = dateColIdx[type] || [];
      const normRows = dataRows.map(r => {
        const r2 = [...r];
        idxToFix.forEach(i => { if(r2[i] !== '' && r2[i] != null) r2[i] = normalizeDateValue(r2[i]); });
        return r2;
      });

      // Preview table
      const previewEl = document.getElementById('preview-' + type);
      let tableHtml = `<div class="alert alert-success">✅ ພົບຂໍ້ມູນ ${normRows.length} ລາຍການ</div>`;
      tableHtml += '<div class="table-wrap"><table><thead><tr>';
      headers.forEach(h => tableHtml += `<th>${h}</th>`);
      tableHtml += '<th>ອາຍຸການ (ອັດຕະໂນມັດ)</th></tr></thead><tbody>';

      // Parse rows based on type
      const parsedRows = normRows.map(r => {
        let duration = '-';
        if(type === '8.1') duration = calcDuration(r[6]);
        else if(type === '8.2') duration = calcDuration(r[6], r[7]);
        else if(type === '8.3') duration = calcDuration(r[6]);
        else if(type === '8.4') duration = calcDuration(r[7], r[8]);
        return { row: r, duration };
      });

      parsedRows.forEach(({row, duration}) => {
        tableHtml += '<tr>';
        row.forEach(c => tableHtml += `<td>${c||'-'}</td>`);
        tableHtml += `<td style="color:#27ae60;font-weight:600;">${duration}</td></tr>`;
      });
      tableHtml += '</tbody></table></div>';
      tableHtml += `<div class="mt-4"><button class="btn btn-primary" onclick="saveEmpDataFromStore('${type}')">💾 ບັນທຶກຂໍ້ມູນເຂົ້າລະບົບ</button></div>`;
      window._empPreviewStore = window._empPreviewStore || {};
      window._empPreviewStore[type] = parsedRows;
      previewEl.innerHTML = tableHtml;
    } catch(err) {
      alert('ເກີດຂໍ້ຜິດພາດ: ' + err.message);
    }
  };
  reader.readAsBinaryString(file);
}

function saveEmpDataFromStore(type) {
  const parsedRows = window._empPreviewStore && window._empPreviewStore[type];
  if(!parsedRows || parsedRows.length === 0) {
    alert('ບໍ່ພົບຂໍ້ມູນທີ່ກຽມໄວ້ ກະລຸນາອັບໂຫຼດໄຟລໃໝ່');
    return;
  }
  saveEmpData(type, parsedRows);
}

async function saveEmpData(type, parsedRows) {
  if(!confirm(`ຢືນຢັນບັນທຶກຂໍ້ມູນ ${parsedRows.length} ລາຍການ? ຫຼັງຈາກບັນທຶກແລ້ວບໍ່ສາມາດແກ້ໄຂໄດ້`)) return;

  const records = parsedRows.map(({row, duration}) => {
    let base = {
      company_id: currentUser.companyId,
      emp_type: type,
      firstname: row[0] || '',
      lastname: row[1] || '',
      duration_auto: duration,
      created_at: new Date().toISOString()
    };
    if(type === '8.1') {
      base = {...base, gender: row[2], education: row[3], position: row[4], status: row[5], start_date: row[6]||null};
    } else if(type === '8.2') {
      base = {...base, gender: row[2], education: row[3], position: row[4], resign_reason: row[5], start_date: row[6]||null, end_date: row[7]||null};
    } else if(type === '8.3') {
      base = {...base, gender: row[2], nationality: row[3], education: row[4], position: row[5], start_date: row[6]||null, stay_duration_months: row[7]||null};
    } else {
      base = {...base, gender: row[2], nationality: row[3], education: row[4], position: row[5], resign_reason: row[6], start_date: row[7]||null, end_date: row[8]||null, stay_duration_months: row[9]||null};
    }
    return base;
  });

  const { error } = await supabaseRetry(() => sb.from('emp_movements').insert(records));
  if(error) { alert('ຜິດພາດ: ' + error.message + '\n\nກະລຸນາລອງໃໝ່ອີກຄັ້ງ (ອາດຍ້ອນມີຄົນໃຊ້ລະບົບພ້ອມກັນຫຼາຍ)'); return; }
  alert('✅ ບັນທຶກສຳເລັດ ' + records.length + ' ລາຍການ');
  if(window._empPreviewStore) delete window._empPreviewStore[type];
  document.getElementById('preview-' + type).innerHTML = '';
  loadMyEmpRecords();
}

async function loadMyEmpRecords() {
  const el = document.getElementById('myEmpRecords');
  if(!el) return;
  const { data, error } = await sb.from('emp_movements').select('*').eq('company_id', currentUser.companyId).order('created_at', {ascending:false});
  if(error) {
    el.innerHTML = `<div class="alert alert-danger">❌ ເກີດຂໍ້ຜິດພາດ: ${error.message}</div>`;
    return;
  }
  if(!data || data.length === 0) { el.innerHTML = '<div style="text-align:center;color:#aaa;padding:20px;">ຍັງບໍ່ມີຂໍ້ມູນ</div>'; return; }

  const grouped = {};
  data.forEach(r => { if(!grouped[r.emp_type]) grouped[r.emp_type] = []; grouped[r.emp_type].push(r); });

  let html = '';
  Object.entries(grouped).forEach(([type, rows]) => {
    html += `<div class="section-title mt-4">${EMP_TYPE_LABELS[type]} (${rows.length} ລາຍການ)</div>`;
    html += '<div class="table-wrap"><table><thead><tr><th>ຊື່</th><th>ນາມສະກຸນ</th><th>ເພດ</th>';
    if(type==='8.3'||type==='8.4') html += '<th>ສັນຊາດ</th>';
    html += '<th>ວຸດທິ</th><th>ຕຳແໜ່ງ</th>';
    if(type==='8.1') html += '<th>ສະຖານະ</th>';
    if(type==='8.2'||type==='8.4') html += '<th>ເຫດຜົນ</th>';
    html += type==='8.3'||type==='8.4' ? '<th>ວັນທີເຂົ້າມາລາວ</th>' : '<th>ມື້ເຂົ້າ</th>';
    if(type==='8.2'||type==='8.4') html += '<th>ມື້ອອກ</th>';
    html += type==='8.3'||type==='8.4' ? '<th>ກຳນົດຢູ່ລາວ</th>' : '<th>ອາຍຸການ</th>';
    html += '</tr></thead><tbody>';
    rows.forEach(r => {
      const dur = (type==='8.1'||type==='8.3') ? calcDuration(r.start_date) : calcDuration(r.start_date, r.end_date);
      const stayLabel = r.stay_duration_months ? `${r.stay_duration_months} ເດືອນ` : '-';
      const genderIcon = r.gender==='ຍິງ'?'♀':'♂';
      const genderColor = r.gender==='ຍິງ'?'#e91e8c':'#2980b9';
      html += `<tr><td>${esc(r.firstname)}</td><td>${esc(r.lastname)}</td>`;
      html += `<td style="color:${genderColor};font-weight:600;">${genderIcon} ${r.gender||'-'}</td>`;
      if(type==='8.3'||type==='8.4') html += `<td>${esc(r.nationality||'-')}</td>`;
      html += `<td>${esc(r.education||'-')}</td><td>${esc(r.position||'-')}</td>`;
      if(type==='8.1') html += `<td>${r.status||'-'}</td>`;
      if(type==='8.2'||type==='8.4') html += `<td>${esc(r.resign_reason||'-')}</td>`;
      html += `<td>${r.start_date||'-'}</td>`;
      if(type==='8.2'||type==='8.4') html += `<td>${r.end_date||'-'}</td>`;
      html += (type==='8.3'||type==='8.4')
        ? `<td style="color:#27ae60;font-weight:600;">${stayLabel}</td></tr>`
        : `<td style="color:#27ae60;font-weight:600;">${dur}</td></tr>`;
    });
    html += '</tbody></table></div>';
  });
  el.innerHTML = html;
}

