function switchEmpTabAdmin(name, btn) {
  document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.tabs .tab').forEach(t => t.classList.remove('active'));
  document.getElementById('tab-' + name)?.classList.add('active');
  btn.classList.add('active');
  loadAdminEmpTab(name.replace('a',''));
}

async function loadEmpMovement() {
  await loadAdminEmpTab('81');
}

async function loadAdminEmpTab(tab) {
  const typeMap = {'81':'8.1','82':'8.2','83':'8.3','84':'8.4'};
  const type = typeMap[tab];
  const el = document.getElementById('adminEmp' + tab);
  if(!el) return;
  el.innerHTML = '<div style="text-align:center;color:#aaa;padding:20px;">ກຳລັງໂຫຼດ...</div>';

  const { data: rawData, error } = await sb.from('emp_movements').select('*').eq('emp_type', type).order('created_at',{ascending:false});
  const data = await attachCompanyInfo(rawData);
  if(error) {
    el.innerHTML = `<div class="alert alert-danger">❌ ເກີດຂໍ້ຜິດພາດ: ${error.message}<br><span style="font-size:11px;">ກວດສອບວ່າຕາຕະລາງ emp_movements ຖືກສ້າງໃນ Supabase ແລ້ວບໍ່</span></div>`;
    return;
  }
  if(!data || data.length===0) { el.innerHTML = '<div style="text-align:center;color:#aaa;padding:20px;">ຍັງບໍ່ມີຂໍ້ມູນ (ຫຼື ບໍລິສັດຍັງບໍ່ໄດ້ບັນທຶກ)</div>'; return; }

  let html = `<div style="margin-bottom:8px;color:#666;font-size:13px;">ທັງໝົດ: <b>${data.length}</b> ລາຍການ</div>`;
  html += '<div class="table-wrap"><table><thead><tr><th>ບໍລິສັດ</th><th>ເຂດ</th><th>ຊື່</th><th>ນາມສະກຸນ</th><th>ເພດ</th>';
  if(type==='8.3'||type==='8.4') html += '<th>ສັນຊາດ</th>';
  html += '<th>ວຸດທິ</th><th>ຕຳແໜ່ງ</th>';
  if(type==='8.1') html += '<th>ສະຖານະ</th>';
  if(type==='8.2'||type==='8.4') html += '<th>ເຫດຜົນ</th>';
  html += type==='8.3'||type==='8.4' ? '<th>ວັນທີເຂົ້າມາລາວ</th>' : '<th>ມື້ເຂົ້າ</th>';
  if(type==='8.2'||type==='8.4') html += '<th>ມື້ອອກ</th>';
  html += type==='8.3'||type==='8.4' ? '<th>ກຳນົດຢູ່ລາວ</th>' : '<th>ອາຍຸການ</th>';
  html += '</tr></thead><tbody>';

  data.forEach(r => {
    const dur = (type==='8.1'||type==='8.3') ? calcDuration(r.start_date) : calcDuration(r.start_date, r.end_date);
    const stayLabel = r.stay_duration_months ? `${r.stay_duration_months} ເດືອນ` : '-';
    const gIcon = r.gender==='ຍິງ'?'♀':'♂';
    const gCol = r.gender==='ຍິງ'?'#e91e8c':'#2980b9';
    html += `<tr><td><b>${esc(r.companies?.username||'-')}</b><br><span style="font-size:11px;color:#888;">${esc(r.companies?.name_lao||'')}</span></td>`;
    html += `<td>ເຂດ ${r.companies?.zone||'-'}</td>`;
    html += `<td>${esc(r.firstname)}</td><td>${esc(r.lastname)}</td>`;
    html += `<td style="color:${gCol};font-weight:600;">${gIcon} ${r.gender||'-'}</td>`;
    if(type==='8.3'||type==='8.4') html += `<td>${esc(r.nationality||'-')}</td>`;
    html += `<td>${esc(r.education||'-')}</td><td>${esc(r.position||'-')}</td>`;
    if(type==='8.1') html += `<td>${r.status||'-'}</td>`;
    if(type==='8.2'||type==='8.4') html += `<td>${esc(r.resign_reason||'-')}</td>`;
    html += `<td>${r.start_date||'-'}</td>`;
    if(type==='8.2'||type==='8.4') html += `<td>${r.end_date||'-'}</td>`;
    html += (type==='8.3'||type==='8.4')
      ? `<td style="color:#27ae60;font-weight:600;">${stayLabel}</td></tr>`
      : `<td style="color:#27ae60;font-weight:600;">${dur}</td></tr>`;
  });
  html += '</tbody></table></div>';
  el.innerHTML = html;
}

