let _lwAdminCache = [];

async function loadLaoWorkersAdmin() {
  const el = document.getElementById('lwAdminTable');
  if (!el) return;
  const compSel = document.getElementById('lwAdminCompany');
  if (compSel && compSel.options.length === 1) {
    activeCompanies.forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id; opt.textContent = `${c.username} — ${c.name_lao}`;
      compSel.appendChild(opt);
    });
  }
  const { data, error } = await sb.from('lao_workers')
    .select('*, companies(id,username,name_lao,zone)')
    .order('created_at', { ascending: false });
  if (error) {
    el.innerHTML = `<div class="alert alert-danger">❌ ເກີດຂໍ້ຜິດພາດ: ${error.message}<br>
      <span style="font-size:11px;">ກວດສອບວ່າຕາຕະລາງ <b>lao_workers</b> ຖືກສ້າງໃນ Supabase ແລ້ວ</span></div>`;
    return;
  }
  _lwAdminCache = data || [];
  renderLaoRegDateSummary(_lwAdminCache, 'lwAdminRegDateSummary');
  renderLaoWorkersAdmin(_lwAdminCache);
}

function filterLaoWorkersAdmin() {
  const q      = (document.getElementById('lwAdminSearch')?.value  || '').toLowerCase();
  const zone   = (document.getElementById('lwAdminZone')?.value    || '');
  const status = (document.getElementById('lwAdminStatus')?.value  || '');
  const compId = (document.getElementById('lwAdminCompany')?.value || '');
  const from   = (document.getElementById('lwAdminFrom')?.value    || '');
  const to     = (document.getElementById('lwAdminTo')?.value      || '');

  const filtered = _lwAdminCache.filter(w => {
    const matchQ      = !q      || (`${esc(w.firstname||'')} ${esc(w.lastname||'')} ${esc(w.reg_id||'')} ${esc(w.position||'')}`).toLowerCase().includes(q);
    const matchZone   = !zone   || (w.companies?.zone === zone);
    const matchStatus = !status || (w.status === status);
    const matchComp   = !compId || (w.company_id === compId);
    let matchDate = true;
    if ((from || to) && w.reg_date) {
      const rd = w.reg_date.slice(0,7);
      if (from && rd < from) matchDate = false;
      if (to   && rd > to)   matchDate = false;
    }
    return matchQ && matchZone && matchStatus && matchComp && matchDate;
  });

  renderLaoRegDateSummary(filtered, 'lwAdminRegDateSummary');
  renderLaoWorkersAdmin(filtered);
}

function renderLaoWorkersAdmin(workers) {
  const statsEl = document.getElementById('lwAdminStats');
  if (statsEl) {
    const total=workers.length, male=workers.filter(w=>w.gender!=='ຍິງ').length;
    const female=workers.filter(w=>w.gender==='ຍິງ').length;
    const perm=workers.filter(w=>w.status==='ຖາວອນ').length, prob=workers.filter(w=>w.status!=='ຖາວອນ').length;
    statsEl.innerHTML = [['👥 ທັງໝົດ',total,'#1a5276'],['♂ ຊາຍ',male,'#2980b9'],['♀ ຍິງ',female,'#e91e8c'],['✅ ຖາວອນ',perm,'#27ae60'],['🎓 ຝຶກງານ',prob,'#f39c12']]
      .map(([l,v,c])=>`<div style="background:#fff;border-radius:10px;padding:10px 18px;box-shadow:0 2px 6px rgba(0,0,0,.08);border-left:4px solid ${c};min-width:110px;"><div style="font-size:11px;color:#666;">${l}</div><div style="font-size:22px;font-weight:700;color:${c};">${v}</div></div>`).join('');
  }
  const el = document.getElementById('lwAdminTable');
  if (!el) return;
  if (!workers.length) { el.innerHTML = '<div style="text-align:center;color:#aaa;padding:30px;">ຍັງບໍ່ມີຂໍ້ມູນ ຫຼື ບໍ່ຕົງກັບເງື່ອນໄຂ</div>'; return; }
  el.innerHTML = `<table id="lwAdminTableEl" style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:#1a5276;color:#fff;">
      <th style="padding:8px;">ລ/ດ</th><th style="padding:8px;">ທະບຽນ ID</th><th style="padding:8px;">ຊື່-ນາມສະກຸນ</th>
      <th style="padding:8px;">ເພດ</th><th style="padding:8px;">ວຸດທິ</th><th style="padding:8px;">ຕຳແໜ່ງ</th>
      <th style="padding:8px;">ສະຖານະ</th><th style="padding:8px;">ວັນທີເຂົ້າ</th><th style="padding:8px;">ວັນທີລົງທະບຽນ</th><th style="padding:8px;">ໄລຍະ</th>
      <th style="padding:8px;">ແຂວງ</th><th style="padding:8px;">ບໍລິສັດ</th><th style="padding:8px;">ເຂດ</th>
    </tr></thead>
    <tbody>${workers.map((w,i)=>{
      const gCol=w.gender==='ຍິງ'?'#e91e8c':'#2980b9';
      const sBg=w.status==='ຖາວອນ'?'#c8e6c9':'#fff3cd', sCol=w.status==='ຖາວອນ'?'#2e7d32':'#856404';
      return `<tr style="background:${i%2?'#f8f8f8':'#fff'}">
        <td style="padding:7px;text-align:center;color:#888;">${i+1}</td>
        <td style="padding:7px;color:#1a5276;font-weight:600;">${esc(w.reg_id||'-')}</td>
        <td style="padding:7px;">${esc(w.prefix||'')} ${esc(w.firstname||'')} ${esc(w.lastname||'')}</td>
        <td style="padding:7px;text-align:center;color:${gCol};font-weight:600;">${w.gender==='ຍິງ'?'♀':'♂'}</td>
        <td style="padding:7px;">${esc(w.education||'-')}</td><td style="padding:7px;">${esc(w.position||'-')}</td>
        <td style="padding:7px;text-align:center;"><span style="padding:2px 8px;border-radius:12px;font-size:11px;background:${sBg};color:${sCol};">${w.status||'-'}</span></td>
        <td style="padding:7px;text-align:center;white-space:nowrap;">${laoDate(w.start_date)}</td>
        <td style="padding:7px;text-align:center;white-space:nowrap;">${laoDate(w.reg_date)}</td>
        <td style="padding:7px;text-align:center;white-space:nowrap;">${calcDuration(w.start_date)}</td>
        <td style="padding:7px;">${esc((w.province||'-').replace('ແຂວງ','').replace('ນະຄອນຫຼວງ','ນ.ຫ.'))}</td>
        <td style="padding:7px;"><b>${esc(w.companies?.username||'-')}</b><br><span style="font-size:10px;color:#888;">${esc(w.companies?.name_lao||'')}</span></td>
        <td style="padding:7px;text-align:center;">ເຂດ ${w.companies?.zone||'-'}</td>
      </tr>`;
    }).join('')}</tbody></table>`;
}

function exportLaoWorkersAdmin() {
  const table = document.getElementById('lwAdminTableEl');
  if (!table) { alert('ກະລຸນາໂຫຼດຂໍ້ມູນກ່ອນ'); return; }
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.table_to_sheet(table);
  XLSX.utils.book_append_sheet(wb, ws, 'LaoWorkers C3');
  XLSX.writeFile(wb, 'SVKSEZ_LaoWorkers_C3.xlsx');
}

