function switchRsTab(tab) {
  document.getElementById('rsTabList').style.display = tab==='list' ? '' : 'none';
  document.getElementById('rsTabMovement').style.display = tab==='movement' ? '' : 'none';
  document.getElementById('rsTab1Btn').className = 'btn btn-sm ' + (tab==='list' ? 'btn-primary' : 'btn-secondary');
  document.getElementById('rsTab2Btn').className = 'btn btn-sm ' + (tab==='movement' ? 'btn-primary' : 'btn-secondary');
}

async function searchWorkerMovement() {
  const q = (document.getElementById('mvSearchInput')?.value || '').trim().toLowerCase();
  const typeFilter = document.getElementById('mvWorkerTypeFilter')?.value || '';
  const el = document.getElementById('mvResult');
  if (!el) return;
  if (q.length < 2) { el.innerHTML = '<div style="color:#aaa;padding:16px;text-align:center;">ພິມຊື່ຢ່າງໜ້ອຍ 2 ຕົວອັກສອນ</div>'; return; }
  el.innerHTML = '<div style="color:#aaa;padding:10px;">ກຳລັງຄົ້ນຫາ...</div>';

  // Query all sources in parallel — search by name, reg_id, passport
  const [
    { data: resignsRaw },
    { data: activeFwRaw },
    { data: activeLaoRaw },
    { data: fnrHistoryRaw }
  ] = await Promise.all([
    sb.from('resignations')
      .select('*')
      .order('resign_date', { ascending: true }),
    sb.from('foreign_workers')
      .select('id,reg_id,prefix,firstname,lastname,nationality,gender,position,labour_card_issue,passport_no,company_id')
      .or(`firstname.ilike.%${q}%,lastname.ilike.%${q}%,reg_id.ilike.%${q}%,passport_no.ilike.%${q}%`),
    sb.from('lao_workers')
      .select('id,reg_id,prefix,firstname,lastname,gender,position,start_date,company_id')
      .or(`firstname.ilike.%${q}%,lastname.ilike.%${q}%,reg_id.ilike.%${q}%`),
    sb.from('foreign_worker_renewals')
      .select('id,reg_id,worker_id,prefix,firstname,lastname,nationality,gender,position,passport_no,created_at,company_id')
      .or(`firstname.ilike.%${q}%,lastname.ilike.%${q}%,reg_id.ilike.%${q}%,passport_no.ilike.%${q}%`)
      .order('created_at', { ascending: true })
  ]);
  const [resigns, activeFw, activeLao, fnrHistory] = await Promise.all([
    attachCompanyInfo(resignsRaw), attachCompanyInfo(activeFwRaw), attachCompanyInfo(activeLaoRaw), attachCompanyInfo(fnrHistoryRaw)
  ]);

  // Filter resignations by name, reg_id, passport
  const matchedResigns = (resigns||[]).filter(r =>
    (r.firstname||'').toLowerCase().includes(q) ||
    (r.lastname||'').toLowerCase().includes(q) ||
    (r.reg_id||'').toLowerCase().includes(q) ||
    (r.er_id||'').toLowerCase().includes(q)
  );

  const personMap = {};

  const addPerson = (key, r, type, extraDate) => {
    if (!personMap[key]) personMap[key] = {
      firstname: r.firstname, lastname: r.lastname, prefix: r.prefix,
      nationality: r.nationality || (r.worker_type === 'lao' ? 'ລາວ' : '-'),
      gender: r.gender, history: []
    };
    personMap[key].history.push({
      type,
      date: type === 'resign' ? r.resign_date : (extraDate || null),
      company: r.companies?.username || '-',
      companyName: r.companies?.name_lao || '',
      reg_id: r.reg_id,
      er_id: r.er_id || null,
      reason: r.resign_reason || null,
      category: r.resign_category || null,
      position: r.position || '-',
      worker_type: r.worker_type || null
    });
  };

  // 1. Resignations (lao + fn + fnr)
  matchedResigns.forEach(r => addPerson((r.firstname+'_'+r.lastname+'_'+(r.gender||'?')).toLowerCase(), r, 'resign'));

  // 2. Active Lao workers
  (activeLao||[]).forEach(w => addPerson((w.firstname+'_'+w.lastname+'_'+(w.gender||'?')).toLowerCase(), w, 'active', w.start_date));

  // 3. Active FW — split FN vs FNR
  (activeFw||[]).forEach(w => {
    const key = (w.firstname+'_'+w.lastname+'_'+(w.gender||'?')).toLowerCase();
    if (!personMap[key]) personMap[key] = {
      firstname: w.firstname, lastname: w.lastname, prefix: w.prefix,
      nationality: w.nationality || '-', gender: w.gender, history: []
    };
    personMap[key].history.push({
      type: 'active',
      date: w.labour_card_issue || null,
      company: w.companies?.username || '-',
      companyName: w.companies?.name_lao || '',
      reg_id: w.reg_id,
      er_id: null, reason: null, category: null,
      position: w.position || '-',
      worker_type: String(w.reg_id||'').startsWith('FNR') ? 'fnr' : 'fn'
    });
  });

  // 4. FNR renewal history — create person if not exists (covers FW who resigned after FNR)
  (fnrHistory||[]).forEach(r => {
    const key = (r.firstname+'_'+r.lastname+'_'+(r.gender||'?')).toLowerCase();
    if (!personMap[key]) {
      personMap[key] = {
        firstname: r.firstname, lastname: r.lastname, prefix: r.prefix,
        nationality: r.nationality || '-', gender: r.gender, history: []
      };
    }
    personMap[key].history.push({
      type: 'renewal',
      date: r.created_at ? r.created_at.split('T')[0] : null,
      company: r.companies?.username || '-',
      companyName: r.companies?.name_lao || '',
      reg_id: r.reg_id,
      er_id: null, reason: null, category: null,
      position: r.position || '-',
      worker_type: 'fnr'
    });
  });

  // Sort each person's history by date
  Object.values(personMap).forEach(p =>
    p.history.sort((a,b) => !a.date ? 1 : !b.date ? -1 : new Date(a.date)-new Date(b.date))
  );

  if (!Object.keys(personMap).length) { el.innerHTML = '<div style="color:#aaa;padding:16px;">ບໍ່ພົບຂໍ້ມູນ — ລອງໃສ່ຊື່ ຫຼື ນາມສະກຸນ</div>'; return; }

  // Filter by worker type if selected
  let filtered = Object.values(personMap);
  if (typeFilter === 'lao') {
    filtered = filtered.filter(p => p.nationality === 'ລາວ' || (p.history[0]?.worker_type === null && p.nationality !== '-'));
  } else if (typeFilter === 'fw') {
    filtered = filtered.filter(p => p.nationality !== 'ລາວ' || p.history.some(h => h.worker_type === 'fn' || h.worker_type === 'fnr'));
  }
  if (!filtered.length) { el.innerHTML = '<div style="color:#aaa;padding:16px;">ບໍ່ພົບຂໍ້ມູນ ສຳລັບປະເພດທີ່ເລືອກ</div>'; return; }
  const cards = filtered.map((person, idx) => {
    const name = [person.prefix, person.firstname, person.lastname].filter(Boolean).map(esc).join(' ');
    const isActive = person.history.some(h => h.type === 'active');
    const coCount  = new Set(person.history.map(h => h.company)).size;
    const lastEvent = person.history[person.history.length - 1];
    const encoded = encodeURIComponent(JSON.stringify(person));
    return `<div class="mv-card" onclick="showMvDetail(this,'${encoded}')"
      style="background:#fff;border-left:4px solid ${isActive?'#27ae60':'#e74c3c'};border-radius:8px;padding:12px 14px;margin-bottom:8px;cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,.08);">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;">
        <div>
          <div style="font-size:14px;font-weight:700;">${name}</div>
          <div style="font-size:11px;color:#888;margin-top:2px;">${esc(person.nationality||'')} • ${person.gender||''}</div>
        </div>
        <span style="background:${isActive?'#eafaf1':'#fdf2f2'};color:${isActive?'#27ae60':'#e74c3c'};padding:2px 8px;border-radius:20px;font-size:11px;white-space:nowrap;">${isActive?'🟢 ທຳງານຢູ່':'🔴 ບໍ່ທຳງານ'}</span>
      </div>
      <div style="margin-top:6px;font-size:11px;color:#555;">
        <span style="background:#eaf4ff;color:#1565c0;padding:1px 7px;border-radius:12px;">🏭 ${coCount} ບໍລິສັດ</span>
        <span style="margin-left:6px;color:#888;">${esc(lastEvent?.reg_id||'')}</span>
      </div>
      ${!isActive && lastEvent?.date ? `<div style="font-size:11px;color:#e74c3c;margin-top:4px;">ລາອອກ: ${laoDate(lastEvent.date)}</div>` : ''}
    </div>`;
  }).join('');

  el.innerHTML = `<div style="display:grid;grid-template-columns:280px 1fr;gap:16px;align-items:flex-start;">
    <div id="mvCardList" style="max-height:65vh;overflow-y:auto;">${cards}</div>
    <div id="mvDetailPanel" style="background:#f8fafc;border-radius:12px;padding:16px;min-height:200px;border:1px solid #e2e8f0;">
      <div style="text-align:center;color:#aaa;padding:40px 0;">
        <div style="font-size:32px;">👆</div>
        <div>ກົດທີ່ລາຍຊື່ດ້ານຊ້າຍ<br>ເພື່ອເບິ່ງປະຫວັດລາຍລະອຽດ</div>
      </div>
    </div>
  </div>`;
}

function showMvDetail(el, encoded) {
  // Highlight selected card
  document.querySelectorAll('.mv-card').forEach(c => c.style.background = '#fff');
  el.style.background = '#eaf4ff';

  const person = JSON.parse(decodeURIComponent(encoded));
  const name = [person.prefix, person.firstname, person.lastname].filter(Boolean).map(esc).join(' ');
  const isActive = person.history.some(h => h.type === 'active');

  // Calculate total tenure
  const dates = person.history.filter(h => h.date).map(h => new Date(h.date));
  const firstDate = person.history.find(h => h.date)?.date;
  const lastDate  = person.history.filter(h => h.date).pop()?.date;
  const totalMonths = firstDate && lastDate
    ? Math.round((new Date(lastDate) - new Date(firstDate)) / 86400000 / 30)
    : null;

  // ກວດວັນທີຊ້ອນກັນລະຫວ່າງບໍລິສັດ — ອາດເປັນສັນຍານວ່າບໍ່ແມ່ນຄົນດຽວກັນຈິງ (ຊື່ຄືກັນໂດຍບັງເອີນ)
  const dateCompanyMap = {};
  person.history.forEach(h => {
    if (!h.date) return;
    if (!dateCompanyMap[h.date]) dateCompanyMap[h.date] = new Set();
    dateCompanyMap[h.date].add(h.company);
  });
  const overlapWarning = Object.entries(dateCompanyMap).some(([d, cos]) => cos.size > 1);

  // Build timeline
  const timeline = person.history.map((h, i) => {
    const isLast = i === person.history.length - 1;
    const cat = (RESIGN_CATEGORIES.find(c => c.value === h.category)||{}).label || '';
    const isResign  = h.type === 'resign';
    const isRenewal = h.type === 'renewal';
    const dotColor = isResign ? '#e74c3c' : isRenewal ? '#f39c12' : '#27ae60';
    const bgColor  = isResign ? '#fdf2f2' : isRenewal ? '#fef9e7' : '#eafaf1';
    const bdColor  = isResign ? '#f5b7b1' : isRenewal ? '#fdebd0' : '#a9dfbf';
    const badge = isResign
      ? `<span style="background:#e74c3c;color:#fff;padding:1px 6px;border-radius:4px;font-size:10px;margin-left:6px;">🚪 ລາອອກ</span>`
      : isRenewal
      ? `<span style="background:#f39c12;color:#fff;padding:1px 6px;border-radius:4px;font-size:10px;margin-left:6px;">🔄 ຕໍ່ອາຍຸ FNR</span>`
      : h.worker_type === 'fnr'
      ? `<span style="background:#2980b9;color:#fff;padding:1px 6px;border-radius:4px;font-size:10px;margin-left:6px;">🟢 FNR ປະຈຸບັນ</span>`
      : h.worker_type === 'fn'
      ? `<span style="background:#27ae60;color:#fff;padding:1px 6px;border-radius:4px;font-size:10px;margin-left:6px;">🟢 FN ປະຈຸບັນ</span>`
      : `<span style="background:#27ae60;color:#fff;padding:1px 6px;border-radius:4px;font-size:10px;margin-left:6px;">🟢 ປະຈຸບັນ</span>`;

    // Calculate duration at this company
    const nextH = person.history[i + 1];
    const durMonths = h.date && nextH?.date
      ? Math.round((new Date(nextH.date) - new Date(h.date)) / 86400000 / 30)
      : null;

    return `<div style="display:flex;gap:12px;margin-bottom:${isLast?'0':'14px'};">
      <div style="display:flex;flex-direction:column;align-items:center;min-width:24px;">
        <div style="width:16px;height:16px;border-radius:50%;background:${dotColor};flex-shrink:0;margin-top:3px;border:2px solid #fff;box-shadow:0 0 0 2px ${dotColor};"></div>
        ${!isLast ? '<div style="width:2px;flex:1;background:#ddd;margin-top:4px;min-height:28px;"></div>' : ''}
      </div>
      <div style="flex:1;background:${bgColor};border:1px solid ${bdColor};border-radius:10px;padding:10px 14px;">
        <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px;">
          <div>
            <span style="font-weight:700;font-size:13px;">${esc(h.company)}</span>
            <span style="font-size:11px;color:#888;margin-left:6px;">${esc(h.companyName)}</span>
          </div>
          ${h.date ? `<span style="font-size:11px;color:#888;">${laoDate(h.date)}</span>` : ''}
        </div>
        <div style="margin-top:4px;font-size:12px;">
          <b>${esc(h.reg_id)||''}</b>
          <span style="color:#555;margin-left:6px;">${esc(h.position)||'-'}</span>
          ${badge}
        </div>
        ${h.er_id ? `<div style="font-size:11px;color:#c0392b;margin-top:3px;">ER ID: <b>${esc(h.er_id)}</b></div>` : ''}
        ${isResign && (h.category||h.reason) ? `<div style="font-size:11px;color:#888;margin-top:3px;">ສາເຫດ: ${esc((RESIGN_CATEGORIES.find(c=>c.value===h.category)||{}).label||h.reason||'')}</div>` : ''}
        ${durMonths !== null ? `<div style="font-size:11px;color:#2980b9;margin-top:3px;">⏱ ຢູ່ ${durMonths} ເດືອນ</div>` : ''}
      </div>
    </div>`;
  }).join('');

  document.getElementById('mvDetailPanel').innerHTML = `
    <div style="border-bottom:1px solid #e2e8f0;padding-bottom:12px;margin-bottom:14px;">
      <div style="font-size:17px;font-weight:700;">${name}</div>
      <div style="font-size:12px;color:#888;margin-top:2px;">${esc(person.nationality)||''} • ${esc(person.gender)||''}</div>
      <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap;">
        <span style="background:${isActive?'#eafaf1':'#fdf2f2'};color:${isActive?'#27ae60':'#e74c3c'};padding:3px 12px;border-radius:20px;font-size:12px;">${isActive?'🟢 ທຳງານຢູ່':'🔴 ບໍ່ທຳງານໃນ SVKSEZ'}</span>
        <span style="background:#eaf4ff;color:#1565c0;padding:3px 12px;border-radius:20px;font-size:12px;">🏭 ${new Set(person.history.map(h=>h.company)).size} ບໍລິສັດ</span>
        ${totalMonths !== null ? `<span style="background:#fef9e7;color:#7d6608;padding:3px 12px;border-radius:20px;font-size:12px;">⏱ ລວມ ${totalMonths} ເດືອນ</span>` : ''}
      </div>
    </div>
    ${overlapWarning ? `<div style="background:#fdf2f2;border:1px solid #f5b7b1;border-radius:8px;padding:8px 12px;margin-bottom:10px;font-size:12px;color:#c0392b;">⚠️ ພົບວັນທີຊ້ອນກັນລະຫວ່າງບໍລິສັດ — ອາດ<b>ບໍ່ແມ່ນຄົນດຽວກັນ</b> (ຊື່-ນາມສະກຸນ-ເພດຄືກັນໂດຍບັງເອີນ). ກະລຸນາກວດສອບຂໍ້ມູນເພີ່ມເຕີມກັບບໍລິສັດກ່ອນສະຫຼຸບຜົນ.</div>` : ''}
    <div style="background:#eaf4ff;border-radius:8px;padding:8px 12px;margin-bottom:14px;font-size:11px;color:#555;">💡 ຂໍ້ມູນນີ້ຈັບຄູ່ຈາກ <b>ຊື່-ນາມສະກຸນ-ເພດ</b> ເທົ່ານັ້ນ (ບໍ່ໄດ້ໃຊ້ເລກປະຈຳຕົວ ເພື່ອຫຼີກລ່ຽງການເກັບຂໍ້ມູນອ່ອນໄຫວ) — ອາດຄາດເຄື່ອນໄດ້ຖ້າມີຫຼາຍຄົນຊື່ດຽວກັນ ກະລຸນາໃຊ້ເປັນຂໍ້ມູນອ້າງອີງເບື້ອງຕົ້ນເທົ່ານັ້ນ.</div>
    <div style="font-size:12px;font-weight:600;color:#555;margin-bottom:10px;">📋 ປະຫວັດການເຄື່ອນໄຫວ</div>
    ${timeline}`;
}

async function loadResignationsCompany() {
  // Load count stats only for company side
  let q = sb.from('resignations').select('worker_type, er_id, firstname, lastname, resign_date, resign_category')
    .eq('company_id', currentUser.companyId).order('resign_date', { ascending: false });
  const { data } = await q;
  const rows = data || [];
  const setEl = (id, val) => { const e = document.getElementById(id); if (e) e.textContent = val; };
  setEl('rsLaoCount', rows.filter(r=>r.worker_type==='lao').length);
  setEl('rsFnCount',  rows.filter(r=>r.worker_type==='fn').length);
  setEl('rsFnrCount', rows.filter(r=>r.worker_type==='fnr').length);

  // Show brief history (no detail — admin only)
  const histEl = document.getElementById('rsCoHistory');
  if (histEl && rows.length > 0) {
    histEl.innerHTML = `<div class="section-title">ລາຍຊື່ທີ່ບັນທຶກໄວ້ (${rows.length} ຄົນ)</div>
      <table style="font-size:12px;"><thead><tr><th>ER ID</th><th>ຊື່</th><th>ວັນທີລາອອກ</th><th>ໝວດ</th></tr></thead><tbody>
      ${rows.map(r=>`<tr>
        <td><b style="color:#c0392b;">${esc(r.er_id||'-')}</b></td>
        <td>${esc(r.firstname||'')} ${esc(r.lastname||'')}</td>
        <td>${laoDate(r.resign_date)}</td>
        <td style="font-size:11px;">${(RESIGN_CATEGORIES.find(c=>c.value===r.resign_category)||{}).label||'-'}</td>
      </tr>`).join('')}
      </tbody></table>`;
  }
}
async function loadResignationsAdmin() {
  const coId = document.getElementById('rsAdminCoFilter')?.value || '';
  const type = document.getElementById('rsAdminTypeFilter')?.value || '';
  await _renderResignTable(coId, 'rsAdminTable', 'rsAdminLaoCount', 'rsAdminFnCount', 'rsAdminFnrCount', type);
}
async function _renderResignTable(coId, tableElId, laoId, fnId, fnrId, typeFilter) {
  const el = document.getElementById(tableElId);
  if (!el) return;
  el.innerHTML = '<div style="text-align:center;color:#aaa;padding:20px;">ກຳລັງໂຫຼດ...</div>';
  let q = sb.from('resignations').select('*').order('resign_date', { ascending: false });
  if (coId) q = q.eq('company_id', coId);
  if (typeFilter) q = q.eq('worker_type', typeFilter);
  const { data: rawData, error } = await q;
  if (error) { el.innerHTML = `<div class="alert alert-danger">❌ ${error.message}</div>`; return; }
  const data = await attachCompanyInfo(rawData);
  const rows = data || [];
  const setEl = (id, val) => { const e = document.getElementById(id); if (e) e.textContent = val; };
  setEl(laoId, rows.filter(r=>r.worker_type==='lao').length);
  setEl(fnId,  rows.filter(r=>r.worker_type==='fn').length);
  setEl(fnrId, rows.filter(r=>r.worker_type==='fnr').length);
  if (!rows.length) { el.innerHTML = '<div style="text-align:center;color:#aaa;padding:30px;">ຍັງບໍ່ມີຂໍ້ມູນການລາອອກ</div>'; return; }

  const isAdminView = (tableElId === 'rsAdminTable');

  el.innerHTML = `<table><thead><tr>
    ${isAdminView ? '<th>ບໍລິສັດ</th>' : ''}
    <th>ER ID</th><th>ຊື່-ນາມສະກຸນ</th><th>ປະເພດ</th>
    <th>ສັນຊາດ</th><th>ຕຳແໜ່ງ</th><th>ອາຍຸການ</th>
    <th>ໝວດສາເຫດ</th><th>ສາເຫດ</th><th>ວັນທີລາອອກ</th>
    ${isAdminView ? '<th>ພິມ</th><th></th>' : ''}
  </tr></thead><tbody>
    ${rows.map(r => {
      const tenure = r.start_date && r.resign_date
        ? Math.round((new Date(r.resign_date)-new Date(r.start_date))/86400000/30)+' ດ.' : '-';
      const catLabel = (RESIGN_CATEGORIES.find(c=>c.value===r.resign_category)||{}).label || '-';
      const badge = r.worker_type==='lao'
        ? '<span style="background:#e8f5e9;color:#2e7d32;padding:2px 5px;border-radius:4px;font-size:10px;">🇱🇦 ລາວ</span>'
        : r.worker_type==='fnr'
        ? '<span style="background:#e3f2fd;color:#1565c0;padding:2px 5px;border-radius:4px;font-size:10px;">🔄 FNR</span>'
        : '<span style="background:#fff3e0;color:#e65100;padding:2px 5px;border-radius:4px;font-size:10px;">🆔 FN</span>';
      const erId = r.er_id || `ER-${esc(r.reg_id||'')}-${esc(r.companies?.username||'')}`;
      return `<tr>
        ${isAdminView ? `<td style="font-size:11px;">${esc(r.companies?.username||'-')}<br><small style="color:#888;">${esc(r.companies?.name_lao||'')}</small></td>` : ''}
        <td><b style="color:#c0392b;font-size:12px;">${erId}</b><br><small style="color:#999;">${esc(r.reg_id||'')}</small></td>
        <td>${esc(r.prefix||'')} ${esc(r.firstname||'')} ${esc(r.lastname||'')}</td>
        <td>${badge}</td>
        <td style="font-size:12px;">${esc(r.nationality||'-')}</td>
        <td style="font-size:12px;">${esc(r.position||'-')}</td>
        <td style="font-size:12px;color:#e74c3c;font-weight:600;">${tenure}</td>
        <td style="font-size:11px;">${catLabel}</td>
        <td style="font-size:11px;max-width:140px;word-break:break-word;">${esc(r.resign_reason||'-')}</td>
        <td style="white-space:nowrap;font-size:12px;">${laoDate(r.resign_date)}</td>
        ${isAdminView ? `
        <td><button class="btn btn-info btn-sm" onclick="printResignation('${r.id}')">🖨️</button></td>
        <td><button class="btn btn-danger btn-sm" onclick="deleteResignation('${r.id}')">🗑️</button></td>` : ''}
      </tr>`;
    }).join('')}
  </tbody></table>`;
}

let _rsWorkerCache = [];
function openResignModal() {
  ['rsSearchInput','rsReason','rsNotes'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  const sl = document.getElementById('rsSearchList'); if(sl) sl.style.display='none';
  const wi = document.getElementById('rsWorkerInfo'); if(wi) wi.style.display='none';
  ['rsWorkerId','rsRegId','rsWorkerTypeHidden'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  const rd = document.getElementById('rsResignDate'); if(rd) rd.value=new Date().toISOString().split('T')[0];
  document.getElementById('resignModal').classList.add('show');
  loadResignWorkerList();
}
async function loadResignWorkerList() {
  const type = document.getElementById('rsWorkerType')?.value || 'fn';
  const coId = currentUser.role==='admin' ? (document.getElementById('rsAdminCo')?.value||'') : currentUser.companyId;
  if (!coId) { _rsWorkerCache=[]; return; }
  if (type==='lao') {
    const {data} = await sb.from('lao_workers').select('id,reg_id,prefix,firstname,lastname,gender,position,start_date').eq('company_id',coId).order('firstname');
    _rsWorkerCache=(data||[]).map(w=>({...w,_type:'lao',_label:`${esc(w.reg_id)} — ${esc(w.firstname)} ${esc(w.lastname)}`}));
  } else {
    const {data} = await sb.from('foreign_workers').select('id,reg_id,prefix,firstname,lastname,nationality,gender,position,labour_card_issue').eq('company_id',coId).order('firstname');
    const all=data||[];
    const filtered=type==='fnr' ? all.filter(w=>String(w.reg_id||'').startsWith('FNR')) : all.filter(w=>!String(w.reg_id||'').startsWith('FNR'));
    _rsWorkerCache=filtered.map(w=>({...w,_type:type,_label:`${esc(w.reg_id)} — ${esc(w.firstname)} ${esc(w.lastname)}`}));
  }
}
function doResignSearch() {
  const q=(document.getElementById('rsSearchInput')?.value||'').trim().toLowerCase();
  const list=document.getElementById('rsSearchList');
  if(!q){list.style.display='none';return;}
  const matches=_rsWorkerCache.filter(w=>w._label.toLowerCase().includes(q)||(w.firstname||'').toLowerCase().includes(q));
  if(!matches.length){list.innerHTML='<div style="padding:10px;color:#aaa;">ບໍ່ພົບ</div>';list.style.display='block';return;}
  list.style.display='block';
  list.innerHTML=matches.slice(0,12).map(w=>`<div class="autocomplete-item" onclick="selectResignWorker('${w.id}')"><b>${esc(w.reg_id)}</b> — ${esc(w.prefix||'')} ${esc(w.firstname)} ${esc(w.lastname)}</div>`).join('');
}
function selectResignWorker(id) {
  const w=_rsWorkerCache.find(x=>x.id===id); if(!w) return;
  document.getElementById('rsSearchInput').value=w._label;
  document.getElementById('rsSearchList').style.display='none';
  document.getElementById('rsWorkerId').value=w.id;
  document.getElementById('rsRegId').value=w.reg_id||'';
  document.getElementById('rsWorkerTypeHidden').value=w._type;
  const startDate=w.start_date||w.labour_card_issue||null;
  const tenure=startDate ? Math.round((new Date()-new Date(startDate))/86400000/30)+' ເດືອນ (ຈາກ '+laoDate(startDate)+')' : 'ບໍ່ທາງຮູ້';
  const wi=document.getElementById('rsWorkerInfo');
  wi.style.display='block';
  wi.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
    <div><b>ID:</b> ${esc(w.reg_id)}</div><div><b>ຊື່:</b> ${esc(w.prefix||'')} ${esc(w.firstname)} ${esc(w.lastname)}</div>
    <div><b>ສັນຊາດ:</b> ${esc(w.nationality||'ລາວ')}</div><div><b>ເພດ:</b> ${w.gender||'-'}</div>
    <div><b>ຕຳແໜ່ງ:</b> ${esc(w.position||'-')}</div>
    <div><b>ອາຍຸການ:</b> <span style="color:#e74c3c;font-weight:600;">${tenure}</span></div>
  </div>`;
}
async function saveResignation() {
  const wId=document.getElementById('rsWorkerId').value;
  if(!wId){alert('ກະລຸນາເລືອກພະນັກງານກ່ອນ');return;}
  const resignDate=document.getElementById('rsResignDate').value;
  if(!resignDate){alert('ກະລຸນາລະບຸວັນທີລາອອກ');return;}
  const reason=document.getElementById('rsReason').value.trim();
  if(!reason){alert('ກະລຸນາລະບຸສາເຫດ');return;}
  const coId=currentUser.role==='admin'?(document.getElementById('rsAdminCo')?.value||''):currentUser.companyId;
  if(!coId){alert('ກະລຸນາເລືອກບໍລິສັດ');return;}
  const w=_rsWorkerCache.find(x=>x.id===wId);
  const workerType=document.getElementById('rsWorkerTypeHidden').value||document.getElementById('rsWorkerType').value;
  const oldRegId=document.getElementById('rsRegId').value||w?.reg_id||'';

  // Get company username for ER id
  const co = (allCompanies||[]).find(c=>c.id===coId);
  const coUsername = co?.username || currentUser.companyData?.username || coId.slice(0,6);
  const erId = `ER-${oldRegId}-${coUsername}`;

  const btn=document.getElementById('rsSubmitBtn');
  if(btn){btn.disabled=true;btn.textContent='⏳ ກຳລັງບັນທຶກ...';}
  try {
    // 1. Insert resignation record with ER id
    const {error:insErr}=await sb.from('resignations').insert({
      company_id:coId,
      worker_type:workerType,
      worker_id:wId,
      reg_id:oldRegId,
      er_id:erId,
      prefix:w?.prefix||'', firstname:w?.firstname||'', lastname:w?.lastname||'',
      nationality:w?.nationality||(workerType==='lao'?'ລາວ':''),
      gender:w?.gender||'', position:w?.position||'',
      start_date:w?.start_date||w?.labour_card_issue||null,
      resign_date:resignDate, resign_reason:reason,
      resign_category:document.getElementById('rsCategory').value,
      notes:document.getElementById('rsNotes').value.trim(),
      recorded_by:currentUser.username||currentUser.companyData?.username||'admin'
    });
    if(insErr){alert('ຜິດພາດ: '+insErr.message);return;}
    await logAudit('create', 'resignations', erId, { name: `${esc(w?.firstname||'')} ${esc(w?.lastname||'')}`.trim(), worker_type: workerType });

    // 2. Delete worker from their source table (remove from company)
    if(workerType==='lao') {
      await sb.from('lao_workers').delete().eq('id',wId);
      await logAudit('delete', 'lao_workers', wId, { action_detail: 'ລາອອກ (ຍ້າຍໄປ resignations)', er_id: erId });
    } else {
      await sb.from('foreign_workers').delete().eq('id',wId);
      await logAudit('delete', 'foreign_workers', wId, { action_detail: 'ລາອອກ (ຍ້າຍໄປ resignations)', er_id: erId });
      // Sync stats after delete
      try { await syncForeignWorkersToRecords(coId); } catch(e){}
    }

    alert(`✅ ບັນທຶກການລາອອກສຳເລັດ\n\nID ພະນັກງານລາອອກ: ${erId}\nຊື່: ${w?.firstname||''} ${w?.lastname||''}\nໄດ້ລຶບອອກຈາກລາຍຊື່ພະນັກງານບໍລິສັດແລ້ວ`);
    document.getElementById('resignModal').classList.remove('show');
    if(currentUser.role==='admin') loadResignationsAdmin(); else loadResignationsCompany();
  } catch(e){alert('ເກີດຂໍ້ຜິດພາດ: '+e.message);}
  finally{if(btn){btn.disabled=false;btn.textContent='💾 ບັນທຶກການລາອອກ';}}
}
async function deleteResignation(id) {
  if(!confirm('ລຶບຂໍ້ມູນການລາອອກນີ້ອອກ?')) return;
  const {error}=await sb.from('resignations').delete().eq('id',id);
  if(error){alert('ຜິດພາດ: '+error.message);return;}
  await logAudit('delete', 'resignations', id, {});
  if(currentUser.role==='admin') loadResignationsAdmin(); else loadResignationsCompany();
}

// ============================================================
// EXCEL BULK UPLOAD — ບັນທຶກການລາອອກຫຼາຍຄົນພ້ອມກັນ
// ============================================================
function downloadResignBulkTemplate() {
  if (!window.XLSX) { alert('ກຳລັງໂຫຼດ XLSX, ລອງໃໝ່ອີກສັກຄູ່'); return; }
  const headers = ['ປະເພດ (lao/fn/fnr)', 'ID ທະບຽນ', 'ຊື່ (ອ້າງອີງເທົ່ານັ້ນ)', 'ນາມສະກຸນ (ອ້າງອີງເທົ່ານັ້ນ)', 'ວັນທີລາອອກ DD/MM/YYYY', 'ໝວດສາເຫດ', 'ສາເຫດລາອອກ (ລາຍລະອຽດ)', 'ໝາຍເຫດ'];
  const examples = [
    ['lao', 'LW-0001', 'ບຸນມີ', 'ວົງສະຫວັນ', '01/03/2025', 'voluntary', 'ຍ້າຍໄປເຮັດວຽກບ່ອນອື່ນ', ''],
    ['lao', 'LW-0007', 'ສົມສະໜຸກ', 'ພົມມະວົງ', '05/03/2025', 'terminated', 'ຂາດວຽກຕິດຕໍ່ກັນເກີນກຳນົດ', 'ແຈ້ງລ່ວງໜ້າ 3 ວັນ'],
    ['fn', 'FN-0012', 'John', 'Smith', '10/03/2025', 'contract_end', 'ໝົດສັນຍາຈ້າງງານ ບໍ່ຕໍ່ອາຍຸ', ''],
    ['fn', 'FN-0025', 'Li', 'Wei', '15/03/2025', 'completed', 'ສຳເລັດສັນຍາ ກັບປະເທດຕົ້ນທາງ', 'ອອກປະເທດ 20/03/2025'],
    ['fnr', 'FNR-0003', 'Somsak', 'Kaew', '20/03/2025', 'no_renewal', 'ຕໍ່ອາຍຸເອກະສານແລ້ວ ແຕ່ຂໍລາອອກພາຍຫຼັງ', ''],
  ];
  const catNote = ['ໝວດສາເຫດທີ່ໃຊ້ໄດ້:', 'voluntary=ລາອອກເອງ, contract_end=ໝົດສັນຍາ/ບໍ່ຕໍ່ອາຍຸFN, no_renewal=ຕໍ່FNRແລ້ວແຕ່ຂໍລາອອກ, terminated=ຖືກໄລ່ອອກ, completed=ສຳເລັດສັນຍາ/ກັບປະເທດ, other=ອື່ນໆ', '⚠️ ຊື່/ນາມສະກຸນ ໃຊ້ອ້າງອີງເທົ່ານັ້ນ — ລະບົບຄົ້ນຫາຈາກ "ID ທະບຽນ" ເທົ່ານັ້ນ ບໍ່ໄດ້ໃຊ້ຊື່ໃນການຄົ້ນຫາ', '', '', '', '', ''];
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.aoa_to_sheet([headers, ...examples, catNote]);
  ws['!cols'] = headers.map(() => ({ wch: 24 }));
  forceExcelTextColumns(ws, [4], examples.length + 1);
  XLSX.utils.book_append_sheet(wb, ws, 'Resign_Bulk');
  XLSX.writeFile(wb, 'Resignation_Bulk_Template.xlsx');
}

async function handleResignBulkExcel(file) {
  if (!file) return;
  const coId = currentUser.role === 'admin' ? (document.getElementById('rsAdminCoFilter')?.value || '') : currentUser.companyId;
  if (!coId) { alert('ກະລຸນາເລືອກບໍລິສັດສະເພາະ (ບໍ່ແມ່ນ "ທຸກບໍລິສັດ") ຢູ່ຕົວກອງ "ກອງຕາມບໍລິສັດ" ກ່ອນອັບໂຫລດ'); return; }
  if (!window.XLSX) { alert('ກຳລັງໂຫລດ XLSX, ລອງໃໝ່ອີກສັກຄູ່'); return; }

  function excelDate(v) {
    if (!v) return null;
    const s = String(v).trim();
    if (s.includes('/')) {
      const parts = s.split('/');
      if (parts.length === 3) {
        const [d, m, y] = parts;
        const yyyy = y.length === 2 ? '20' + y : y;
        if (d && m && yyyy) return `${yyyy.padStart(4,'0')}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
      }
    }
    if (s.includes('-') && s.length === 10) return s; // already YYYY-MM-DD
    return null;
  }

  let rows;
  try {
    const buf = await file.arrayBuffer();
    const wb = window.XLSX.read(buf, { type: 'array' });
    rows = window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, raw: false });
  } catch (e) { alert('ອ່ານໄຟລ໌ Excel ບໍ່ໄດ້: ' + e.message); return; }

  rows = (rows || []).slice(1).filter(r => r && (r[0] || r[1]));
  if (!rows.length) { alert('ບໍ່ພົບຂໍ້ມູນໃນໄຟລ໌ (ຫຼືມີແຕ່ແຖວຫົວຂໍ້)'); return; }

  const co = (allCompanies || []).find(c => c.id === coId);
  const coUsername = co?.username || currentUser.companyData?.username || String(coId).slice(0, 6);

  let okCount = 0;
  const failRows = [];

  for (const row of rows) {
    const workerType = String(row[0] || '').trim().toLowerCase();
    const regId = String(row[1] || '').trim();
    // row[2]=ຊື່, row[3]=ນາມສະກຸນ — ອ້າງອີງເທົ່ານັ້ນ, ບໍ່ໄດ້ໃຊ້ຄົ້ນຫາ (ຄົ້ນຫາຈາກ ID ທະບຽນເທົ່ານັ້ນ)
    const resignDate = excelDate(row[4]);
    const category = String(row[5] || 'other').trim();
    const reason = String(row[6] || '').trim();
    const notes = String(row[7] || '').trim();

    if (!['lao', 'fn', 'fnr'].includes(workerType)) { failRows.push(`${regId || '(ບໍ່ມີ ID)'}: ປະເພດບໍ່ຖືກຕ້ອງ "${row[0]}" (ຕ້ອງເປັນ lao/fn/fnr)`); continue; }
    if (!regId) { failRows.push('ແຖວໜຶ່ງ: ບໍ່ມີ ID ທະບຽນ'); continue; }
    if (!resignDate) { failRows.push(`${regId}: ວັນທີບໍ່ຖືກຕ້ອງ "${row[4]}" (ຕ້ອງເປັນ DD/MM/YYYY)`); continue; }

    try {
      const sourceTable = workerType === 'lao' ? 'lao_workers' : 'foreign_workers';
      const { data: w } = await supabaseRetry(() => sb.from(sourceTable).select('*').eq('company_id', coId).eq('reg_id', regId).maybeSingle());
      if (!w) { failRows.push(`${regId}: ບໍ່ພົບພະນັກງານນີ້ໃນບໍລິສັດ (ອາດລາອອກໄປແລ້ວ ຫຼື ID ພິມຜິດ)`); continue; }

      const erId = `ER-${regId}-${coUsername}`;
      const { error: insErr } = await supabaseRetry(() => sb.from('resignations').insert({
        company_id: coId, worker_type: workerType, worker_id: w.id, reg_id: regId, er_id: erId,
        prefix: w.prefix || '', firstname: w.firstname || '', lastname: w.lastname || '',
        nationality: w.nationality || (workerType === 'lao' ? 'ລາວ' : ''), gender: w.gender || '', position: w.position || '',
        start_date: w.start_date || w.labour_card_issue || null,
        resign_date: resignDate, resign_reason: reason || '(ນຳເຂົ້າຜ່ານ Excel)', resign_category: category, notes,
        recorded_by: currentUser.username || currentUser.companyData?.username || 'admin'
      }));
      if (insErr) { failRows.push(`${regId}: ${insErr.message}`); continue; }
      await logAudit('create', 'resignations', erId, { name: `${esc(w.firstname || '')} ${esc(w.lastname || '')}`.trim(), worker_type: workerType, action_detail: 'ນຳເຂົ້າຜ່ານ Excel (ຫຼາຍຄົນ)' });

      await supabaseRetry(() => sb.from(sourceTable).delete().eq('id', w.id));
      await logAudit('delete', sourceTable, w.id, { action_detail: 'ລາອອກ (ນຳເຂົ້າຜ່ານ Excel)', er_id: erId });
      if (workerType !== 'lao') { try { await syncForeignWorkersToRecords(coId); } catch (e) {} }

      okCount++;
    } catch (e) {
      failRows.push(`${regId}: ${e.message}`);
    }
  }

  let msg = `✅ ນຳເຂົ້າສຳເລັດ ${okCount} ຄົນ`;
  if (failRows.length) {
    msg += `\n\n⚠️ ຜິດພາດ/ຂ້າມ ${failRows.length} ແຖວ:\n` + failRows.slice(0, 15).join('\n') + (failRows.length > 15 ? `\n... ແລະອີກ ${failRows.length - 15} ແຖວ` : '');
  }
  alert(msg);
  if (currentUser.role === 'admin') loadResignationsAdmin(); else loadResignationsCompany();
}

